const SCENE_ORCHESTRATION_PHASE_LOG_TYPES = {
    queued: 'info',
    llm_submit: 'process',
    llm_returned: 'info',
    importing: 'process',
    imported: 'success',
    failed: 'error',
};

const deriveSceneOrchestrationPhase = (unit) => {
    if (!unit) return 'unknown';
    const explicit = String(unit.orchestration_phase || '').trim().toLowerCase();
    if (explicit) return explicit;
    const importStatus = String(unit.import_status || '').trim().toLowerCase();
    const parseStatus = String(unit.parse_status || '').trim().toLowerCase();
    if (importStatus === 'success' || importStatus === 'imported') return 'imported';
    if (importStatus === 'importing') return 'importing';
    if (importStatus === 'awaiting_workspace_import') return 'llm_returned';
    if (importStatus === 'llm_returned') return 'llm_returned';
    if (importStatus === 'llm_running' || importStatus === 'running') return 'llm_submit';
    if (importStatus === 'failed' || parseStatus === 'failed') return 'failed';
    if (importStatus === 'queued') return 'queued';
    return importStatus || 'unknown';
};

const buildSceneOrchestrationPhaseMessage = (sceneId, phase, { sceneOrder, totalScenes, errorCode, t }) => {
    const orderLabel = sceneOrder && totalScenes ? ` (${sceneOrder}/${totalScenes})` : '';
    switch (phase) {
        case 'queued':
            return t(
                `[场景编排] ${sceneId}${orderLabel} 已排队，等待提交 LLM...`,
                `[Scene beats] ${sceneId}${orderLabel} queued, waiting to submit to LLM...`
            );
        case 'llm_submit':
            return t(
                `[场景编排] ${sceneId}${orderLabel} 已提交 LLM，等待返回...`,
                `[Scene beats] ${sceneId}${orderLabel} submitted to LLM, waiting for response...`
            );
        case 'llm_returned':
            return t(
                `[场景编排] ${sceneId}${orderLabel} LLM 已返回，校验通过`,
                `[Scene beats] ${sceneId}${orderLabel} LLM returned and passed validation`
            );
        case 'importing':
            return t(
                `[场景编排] ${sceneId}${orderLabel} 正在导入工作区...`,
                `[Scene beats] ${sceneId}${orderLabel} importing into workspace...`
            );
        case 'imported':
            return t(
                `[场景编排] ${sceneId}${orderLabel} 导入完成`,
                `[Scene beats] ${sceneId}${orderLabel} import completed`
            );
        case 'failed': {
            let detail = String(errorCode || '').trim();
            if (detail.startsWith('SCENE_MARKDOWN_MISSING_BEAT_1')) {
                return t(
                    `[场景编排] ${sceneId}${orderLabel} 跳过：输入无 Beat 标记，场景不对`,
                    `[Scene beats] ${sceneId}${orderLabel} skipped: no Beat marker in input (invalid scene)`
                );
            }
            if (detail.startsWith('SCENE_MARKDOWN_SCENE_ID_MISMATCH')) {
                const expectedMatch = detail.match(/expected=([^,]+)/i);
                const gotMatch = detail.match(/got=([^,]+)/i);
                const expectedId = expectedMatch?.[1] || sceneId;
                const gotId = gotMatch?.[1] || '';
                return t(
                    `[场景编排] ${sceneId}${orderLabel} 失败：返回 Scene ID 与期望不一致（期望 ${expectedId}${gotId ? `，实际 ${gotId}` : ''}）`,
                    `[Scene beats] ${sceneId}${orderLabel} failed: returned Scene ID mismatch (expected ${expectedId}${gotId ? `, got ${gotId}` : ''})`
                );
            }
            if (
                detail === 'import_no_result'
                || detail === 'workspace_import_failed'
                || detail.startsWith('import_no_result')
                || detail.startsWith('workspace_import_failed')
            ) {
                return t(
                    `[场景编排] ${sceneId}${orderLabel} 失败：场景未写入工作区（场景表缺少 Scene No/Scene ID、解析失败或导入服务不可用）`,
                    `[Scene beats] ${sceneId}${orderLabel} failed: scene was not written to workspace (missing Scene No/Scene ID, parse failure, or import unavailable)`
                );
            }
            return t(
                `[场景编排] ${sceneId}${orderLabel} 失败${detail ? `：${detail}` : ''}`,
                `[Scene beats] ${sceneId}${orderLabel} failed${detail ? `: ${detail}` : ''}`
            );
        }
        default:
            return '';
    }
};

const createSceneOrchestrationPanelReporter = ({ totalScenes = 1, t }) => {
    const importedScenes = new Set();
    const reportedPhases = new Map();
    const resolvedTotal = Math.max(1, Number(totalScenes) || 1);

    const formatOrderLabel = (sceneOrder, total) => (
        sceneOrder && total ? ` (${sceneOrder}/${total})` : ''
    );

    const buildHighlightHint = (sceneId, phase, sceneOrder, total) => {
        const orderLabel = formatOrderLabel(sceneOrder, total);
        switch (phase) {
            case 'queued':
                return t(
                    `「${sceneId}」已排队${orderLabel}`,
                    `"${sceneId}" queued${orderLabel}`
                );
            case 'llm_submit':
                return t(
                    `「${sceneId}」已提交 AI 引擎${orderLabel}`,
                    `"${sceneId}" submitted to AI engine${orderLabel}`
                );
            case 'llm_returned':
                return t(
                    `「${sceneId}」AI 已返回并校验通过${orderLabel}`,
                    `"${sceneId}" AI response validated${orderLabel}`
                );
            case 'importing':
                return t(
                    `「${sceneId}」正在入库${orderLabel}`,
                    `"${sceneId}" importing into workspace${orderLabel}`
                );
            case 'imported':
                return t(
                    `「${sceneId}」已入库，可在场景页查看${orderLabel}`,
                    `"${sceneId}" imported — open Scenes tab${orderLabel}`
                );
            case 'failed':
                return t(
                    `「${sceneId}」入库/编排失败${orderLabel}`,
                    `"${sceneId}" orchestration/import failed${orderLabel}`
                );
            default:
                return '';
        }
    };

    const buildAggregateMessage = (total) => {
        const imported = importedScenes.size;
        const totalCount = Math.max(resolvedTotal, Number(total) || 0, imported);
        const labels = [...importedScenes].sort().join('、');
        if (imported >= totalCount && totalCount > 0) {
            return t(
                `✅ 场景编排已完成 (${imported}/${totalCount}${labels ? `：${labels}` : ''})`,
                `Scene orchestration completed (${imported}/${totalCount}${labels ? `: ${labels.replace(/、/g, ', ')}` : ''})`
            );
        }
        return t(
            `场景编排进行中 (${imported}/${totalCount} 已入库${labels ? `：${labels}` : ''})...`,
            `Scene orchestration in progress (${imported}/${totalCount} imported${labels ? `: ${labels.replace(/、/g, ', ')}` : ''})...`
        );
    };

    return {
        report({ sceneId, phase, sceneOrder, totalScenes: totalOverride, errorCode }) {
            const stableSceneId = String(sceneId || '').trim();
            const stablePhase = String(phase || '').trim().toLowerCase();
            if (!stableSceneId || !stablePhase) return null;

            const reported = reportedPhases.get(stableSceneId) || new Set();
            if (reported.has(stablePhase)) return null;
            reported.add(stablePhase);
            reportedPhases.set(stableSceneId, reported);

            const total = Math.max(resolvedTotal, Number(totalOverride) || 0, importedScenes.size);
            if (stablePhase === 'imported') importedScenes.add(stableSceneId);

            if (stablePhase === 'failed') {
                return {
                    phase: 'warning',
                    message: buildSceneOrchestrationPhaseMessage(stableSceneId, stablePhase, {
                        sceneOrder,
                        totalScenes: total,
                        errorCode,
                        t,
                    }),
                    highlightHint: buildHighlightHint(stableSceneId, stablePhase, sceneOrder, total),
                };
            }

            return {
                phase: 'scene_beats',
                message: buildAggregateMessage(total),
                highlightHint: buildHighlightHint(stableSceneId, stablePhase, sceneOrder, total),
            };
        },
    };
};

const resolveEpisodeSceneIdPrefix = (episode, scriptText = '') => {
    const text = String(scriptText || '');
    for (const pattern of [
        /\b(EP\d+)_SC\d+\b/i,
        /\[SCENE_START:(EP\d+)_SC\d+\]/i,
        /\|\s*(EP\d+)\s*\|\s*EP\d+_SC\d+\s*\|/i,
    ]) {
        const match = text.match(pattern);
        if (match?.[1]) return String(match[1]).trim().toUpperCase();
    }

    const info = episode?.episode_info && typeof episode.episode_info === 'object'
        ? episode.episode_info
        : {};
    for (const key of ['episode_script_episode_number', 'story_dna_episode_number', 'episode_number', 'index']) {
        const n = Number(info[key]);
        if (Number.isFinite(n) && n > 0) return `EP${String(Math.floor(n)).padStart(2, '0')}`;
    }

    const title = String(episode?.title || '');
    for (const pattern of [/EP\s*(\d+)/i, /第\s*(\d+)\s*集/, /^(\d+)\s*[-_.]/]) {
        const match = title.match(pattern);
        if (match?.[1]) {
            const n = Number(match[1]);
            if (Number.isFinite(n) && n > 0) return `EP${String(Math.floor(n)).padStart(2, '0')}`;
        }
    }

    const parsedEpisodeNumber = parseEpisodeNumberFromText(title);
    if (Number.isFinite(parsedEpisodeNumber) && parsedEpisodeNumber > 0) {
        return `EP${String(Math.floor(parsedEpisodeNumber)).padStart(2, '0')}`;
    }
    return 'EP01';
};

const canonicalizeSceneUnitId = (sceneId, sceneOrder, episodePrefix) => {
    const sid = String(sceneId || '').trim();
    const prefix = String(episodePrefix || 'EP01').trim().toUpperCase();
    const order = Math.max(1, Number(sceneOrder) || 0);
    const canonicalMatch = sid.match(/^([A-Za-z]+)(\d+)_SC(\d+)([A-Za-z]*)$/i);
    if (canonicalMatch) {
        const head = String(canonicalMatch[1] || '').toUpperCase();
        const scNum = String(Number(canonicalMatch[3])).padStart(2, '0');
        const suffix = String(canonicalMatch[4] || '').toUpperCase();
        if (head === 'EP') return `${prefix}_SC${scNum}${suffix}`;
        return `${head}${String(Number(canonicalMatch[2])).padStart(2, '0')}_SC${scNum}${suffix}`;
    }
    if (/^\d+$/.test(sid)) return `${prefix}_SC${String(Number(sid)).padStart(2, '0')}`;
    const scMatch = sid.match(/^SC?(\d+)$/i);
    if (scMatch) return `${prefix}_SC${String(Number(scMatch[1])).padStart(2, '0')}`;
    const trailing = sid.match(/(\d+)\s*$/);
    if (trailing && sid.length <= 8) return `${prefix}_SC${String(Number(trailing[1])).padStart(2, '0')}`;
    return sid || `${prefix}_SC${String(order).padStart(2, '0')}`;
};

const applyCanonicalSceneIdsToUnits = (units, episodePrefix) => (
    (Array.isArray(units) ? units : []).map((unit, idx) => {
        const order = Number(unit?.sceneOrder) || idx + 1;
        const newId = canonicalizeSceneUnitId(unit?.sceneId, order, episodePrefix);
        if (newId === unit?.sceneId) {
            return { ...unit, sceneOrder: order };
        }
        return {
            ...unit,
            sceneId: newId,
            sceneOrder: order,
            markerStartToken: `[SCENE_START:${newId}]`,
            markerEndToken: `[SCENE_END:${newId}]`,
        };
    })
);

const sceneIdHasLetterSuffix = (sceneId) => (
    /^EP\d+_SC\d+[A-Za-z]+$/i.test(String(sceneId || '').trim())
);

const normalizeSceneIdToken = (value) => (
    String(value || '').trim().toLowerCase().replace(/[\s_\-./]+/g, '')
);

const deriveSceneOrderFromSceneId = (sceneId) => {
    const sid = String(sceneId || '').trim();
    if (!sid) return null;
    const suffixMatch = sid.match(/^EP\d+_SC(\d+)[A-Za-z]+$/i);
    if (suffixMatch) {
        const order = Number(suffixMatch[1]);
        return Number.isFinite(order) && order > 0 ? order : null;
    }
    const canonicalMatch = sid.match(/^EP\d+_SC(\d+)$/i);
    if (canonicalMatch) {
        const order = Number(canonicalMatch[1]);
        return Number.isFinite(order) && order > 0 ? order : null;
    }
    if (/^\d+$/.test(sid)) {
        const order = Number(sid);
        return Number.isFinite(order) && order > 0 ? order : null;
    }
    const scMatch = sid.match(/^SC?(\d+)$/i);
    if (scMatch) {
        const order = Number(scMatch[1]);
        return Number.isFinite(order) && order > 0 ? order : null;
    }
    const trailing = sid.match(/(\d+)\s*$/);
    if (trailing && sid.length <= 12) {
        const order = Number(trailing[1]);
        return Number.isFinite(order) && order > 0 ? order : null;
    }
    return null;
};

const findDbSceneByPatchSceneId = (dbScenes, patchSceneId) => {
    const patchToken = normalizeSceneIdToken(patchSceneId);
    if (!patchToken) return null;
    const rows = Array.isArray(dbScenes) ? dbScenes : [];
    // Prefer exact Scene ID / scene_no / scene_code token match.
    const exact = rows.find((row) => (
        [row?.scene_no, row?.scene_id, row?.scene_code]
            .map(normalizeSceneIdToken)
            .some((token) => token && token === patchToken)
    ));
    if (exact) return exact;

    // Same episode scene number aliases: EP01_SC03 ↔ "3" / "03".
    // Letter-suffix IDs stay exact-only so SC03A never steals SC03.
    if (sceneIdHasLetterSuffix(patchSceneId)) return null;
    const patchOrder = deriveSceneOrderFromSceneId(patchSceneId);
    if (!(Number.isFinite(patchOrder) && patchOrder > 0)) return null;
    return rows.find((row) => {
        const candidates = [row?.scene_no, row?.scene_id, row?.scene_code];
        return candidates.some((raw) => {
            if (!String(raw || '').trim()) return false;
            if (sceneIdHasLetterSuffix(raw)) return false;
            const order = deriveSceneOrderFromSceneId(raw);
            return Number.isFinite(order) && order > 0 && order === patchOrder;
        });
    }) || null;
};

const dbSceneMatchesPatchSceneId = (dbScenes, patchSceneId) => (
    !!findDbSceneByPatchSceneId(dbScenes, patchSceneId)
);

const resolveSceneRowFromImportReport = (importReport, markerSceneId) => {
    const rows = [
        ...(Array.isArray(importReport?.importedSceneRows) ? importReport.importedSceneRows : []),
        ...(Array.isArray(importReport?.scenes) ? importReport.scenes : []),
    ];
    if (!rows.length) return null;
    if (markerSceneId) {
        return findDbSceneByPatchSceneId(rows, markerSceneId) || null;
    }
    return null;
};

const resolveImportedDbSceneIdFromReport = (importReport, markerSceneId) => {
    const rows = [
        ...(Array.isArray(importReport?.importedSceneRows) ? importReport.importedSceneRows : []),
        ...(Array.isArray(importReport?.scenes) ? importReport.scenes : []),
    ];
    const markerToken = normalizeSceneIdToken(markerSceneId);
    if (!markerToken) return null;
    for (const row of rows) {
        const id = Number(row?.id || 0);
        if (!Number.isFinite(id) || id <= 0) continue;
        const tokens = [row?.scene_no, row?.scene_id, row?.scene_code]
            .map(normalizeSceneIdToken)
            .filter(Boolean);
        if (tokens.some((token) => token === markerToken)) return id;
    }
    // No single-row fallback: a leftover importReport must not bind the wrong scene.
    return null;
};

const filterDbScenesByCanonicalMarkers = (dbScenes, canonicalMarkers, episodePrefix = 'EP01') => {
    const rows = Array.isArray(dbScenes) ? dbScenes : [];
    const markers = Array.isArray(canonicalMarkers)
        ? canonicalMarkers
        : (canonicalMarkers instanceof Set ? [...canonicalMarkers] : []);
    const allowed = expandSceneIdAllowlist(markers, episodePrefix);
    if (!allowed.size) return rows;
    const matched = rows.filter((row) => (
        [row?.scene_no, row?.scene_id, row?.scene_code]
            .some((raw) => raw && isSceneIdInAllowlist(String(raw), allowed, episodePrefix))
    ));
    // Markers that do not token-match DB scene_no (EP01_SC01 vs "1") must not
    // collapse coverage to "0 scenes, all done".
    return matched.length > 0 ? matched : rows;
};

