// Character Canon (Authoritative) generator (shared)

import { CANON_TAG_STORAGE_KEY, CANON_IDENTITY_STORAGE_KEY, PROJECT_SCENE_ANALYSIS_OVERVIEW_FIELDS, DEFAULT_CANON_TAG_CATEGORIES, DEFAULT_CANON_IDENTITY_CATEGORIES, canonOptionValue, normalizeCanonTagCategories, normalizeUserListValues, formatUserListForTextarea, formatManagedUserHint, resolveMaxShotSeconds } from '../editorConstants';
const isDummySubject = (itemName) => {
    if (!itemName) return false;
    const lcName = String(itemName).trim().toLowerCase().replace(/[\s_\-]/g, '');
    return ['subjectindex', 'subjectsindex', 'sceneanalysis', 'entities', 'character', 'characters', 'prop', 'props', 'environment', 'environments', 'role', 'roles', 'item', 'items', 'scene', 'scenes', '角色', '道具', '场景', '人物', '环境', '物件'].includes(lcName);
};

const extractTaggedItemName = (block, tag) => {
    const match = String(block || '').match(new RegExp(`\\[${tag}\\][\\s\\S]{0,160}名称\\s*[=：:]\\s*([^｜|\\r\\n]+)`, 'i'));
    return String(match?.[1] || '').trim();
};

const splitTaggedExtractItems = (text, tag) => {
    const source = String(text || '');
    if (!source || !tag) return [];
    const startRe = new RegExp(`\\[${tag}\\](?!_)`, 'gi');
    const starts = [];
    let match = startRe.exec(source);
    while (match) {
        starts.push(match.index);
        match = startRe.exec(source);
    }
    return starts.map((start, idx) => {
        const end = idx + 1 < starts.length ? starts[idx + 1] : source.length;
        const block = source.slice(start, end).trim();
        const name = extractTaggedItemName(block, tag);
        return { name, block };
    }).filter((item) => item.name);
};

const collectStage1SlotTexts = (stageOutputsRaw) => {
    const texts = [];
    const raw = String(stageOutputsRaw || '').trim();
    if (!raw) return texts;
    try {
        const payload = JSON.parse(raw);
        const outputs = ((payload?.stages || {}).stage1 || {}).outputs || {};
        ['scene_split', 'raw_text', 'adapted_script', 'environment_plan'].forEach((key) => {
            const slot = outputs[key];
            if (slot && typeof slot === 'object') texts.push(String(slot.content || ''));
            else if (typeof slot === 'string') texts.push(slot);
        });
    } catch (_) {
        texts.push(raw);
    }
    return texts;
};

/** Scene-split extracts and environment plan live in result / stage1 slots, not only adaptation. */
const collectEpisodeAssetDesignSourceTexts = (fresh) => (
    [
        fresh?.ai_scene_analysis_adaptation,
        fresh?.ai_scene_analysis_result,
        ...collectStage1SlotTexts(fresh?.ai_stage_outputs),
    ]
        .map((text) => String(text || '').trim())
        .filter(Boolean)
);

const mergeAssetSubtaskReports = (prevReports, nextReports) => {
    const merged = new Map();
    (Array.isArray(prevReports) ? prevReports : []).forEach((item) => {
        const key = String(item?.key || item?.traceId || '').trim();
        if (key) merged.set(key, item);
    });
    (Array.isArray(nextReports) ? nextReports : []).forEach((item) => {
        const key = String(item?.key || item?.traceId || '').trim();
        if (key) merged.set(key, item);
    });
    return Array.from(merged.values());
};

const readStage1OutputSlotContent = (stageOutputsRaw, outputKey) => {
    const raw = String(stageOutputsRaw || '').trim();
    const key = String(outputKey || '').trim();
    if (!raw || !key) return '';
    try {
        const payload = JSON.parse(raw);
        const slot = ((payload?.stages || {}).stage1 || {}).outputs?.[key];
        if (slot && typeof slot === 'object' && !Array.isArray(slot)) {
            return String(slot.content || '').trim();
        }
        if (typeof slot === 'string') return slot.trim();
    } catch (_) {
        // Ignore malformed stage outputs and fall back to marker scans.
    }
    return '';
};

const readStage1EnvironmentPlanContent = (stageOutputsRaw) => (
    readStage1OutputSlotContent(stageOutputsRaw, 'environment_plan')
);

const environmentPlanExtractedBody = (text) => {
    const source = String(text || '').replace(/\r\n/g, '\n').trim();
    if (!source) return '';
    const marker = /`?\[ENVIRONMENT_PLAN_OUTPUT_END[^\]]*\]`?/i;
    const match = marker.exec(source);
    return (match ? source.slice(0, match.index) : source).trim();
};

const textHasEnvironmentPlanSignals = (text) => {
    const body = environmentPlanExtractedBody(text);
    if (body.length <= 100) return false;
    return /\[SCENE_ENV_IDENT_START/i.test(body)
        || /\[ENV_SCENE_PATCH_START/i.test(body)
        || /【主环境】/.test(body);
};

const textHasTaggedExtractItems = (text, tag) => {
    const source = String(text || '').replace(/<think>[\s\S]*?<\/think>/gi, '');
    if (!source) return false;
    if (new RegExp(`\\[${tag}\\][\\s\\S]{0,160}名称\\s*[=：:]`, 'i').test(source)) return true;
    const startRe = new RegExp(`\\[${tag}_EXTRACT_START[^\\]]*\\]`, 'i');
    const startMatch = startRe.exec(source);
    if (!startMatch) return false;
    const afterStart = startMatch.index + startMatch[0].length;
    const endRe = new RegExp(`\\[${tag}_EXTRACT_END[^\\]]*\\]`, 'i');
    endRe.lastIndex = afterStart;
    const endMatch = endRe.exec(source);
    const body = (endMatch ? source.slice(afterStart, endMatch.index) : source.slice(afterStart)).trim();
    return Boolean(body) && !/^\s*无\s*$/.test(body);
};

const taggedExtractHasStart = (text, tag) => new RegExp(`\\[${tag}_EXTRACT_START`, 'i').test(String(text || ''));

const taggedExtractIsExplicitNone = (text, tag) => (
    taggedExtractHasStart(text, tag) && !textHasTaggedExtractItems(text, tag)
);

const pickFirstMatchingText = (candidates, predicate) => {
    for (const text of candidates || []) {
        const value = String(text || '').trim();
        if (value && predicate(value)) return value;
    }
    return '';
};

const resolveCategoryAssetSourceText = (candidates, category) => {
    const key = String(category || '').trim().toLowerCase();
    if (key === 'characters') {
        const withStart = pickFirstMatchingText(candidates, (text) => taggedExtractHasStart(text, 'CHAR'));
        if (withStart) return withStart;
        return pickFirstMatchingText(candidates, (text) => textHasTaggedExtractItems(text, 'CHAR'));
    }
    if (key === 'props') {
        const withStart = pickFirstMatchingText(candidates, (text) => taggedExtractHasStart(text, 'PROP'));
        if (withStart) return withStart;
        return pickFirstMatchingText(candidates, (text) => textHasTaggedExtractItems(text, 'PROP'));
    }
    if (key === 'environments') {
        return pickFirstMatchingText(candidates, (text) => textHasEnvironmentPlanSignals(text) || collectMainEnvironmentNames(text).length > 0);
    }
    return pickFirstMatchingText(candidates, hasAssetRerunExtractSignals);
};

const resolveCategoryAssetBriefText = (sourceText, category) => {
    const source = String(sourceText || '').trim();
    if (!source) return '';
    const key = String(category || '').trim().toLowerCase();
    if (key === 'characters') return takeTaggedExtractBlock(source, 'CHAR') || source;
    if (key === 'props') return takeTaggedExtractBlock(source, 'PROP') || source;
    return source;
};

