const takeTaggedExtractInner = (text, tag) => {
    const source = String(text || '');
    const startRe = new RegExp(`\\[${tag}_EXTRACT_START[^\\]]*\\]`, 'i');
    const endRe = new RegExp(`\\[${tag}_EXTRACT_END[^\\]]*\\]`, 'i');
    const startMatch = startRe.exec(source);
    if (!startMatch) return '';
    const afterStart = startMatch.index + startMatch[0].length;
    endRe.lastIndex = afterStart;
    const endMatch = endRe.exec(source);
    if (!endMatch) return '';
    return source.slice(afterStart, endMatch.index).trim();
};

const takeTaggedExtractBlock = (text, tag) => {
    const source = String(text || '');
    if (!new RegExp(`\\[${tag}_EXTRACT_START`, 'i').test(source) && !new RegExp(`\\[${tag}\\][\\s\\S]{0,160}名称\\s*[=：:]`, 'i').test(source)) {
        return '';
    }
    const inner = takeTaggedExtractInner(source, tag);
    if (inner) return `[${tag}_EXTRACT_START]\n${inner}\n[${tag}_EXTRACT_END]`;
    const items = splitTaggedExtractItems(source, tag);
    if (!items.length) return '';
    return `[${tag}_EXTRACT_START]\n${items.map((item) => item.block).join('\n\n')}\n[${tag}_EXTRACT_END]`;
};

const normalizeExtractReplacementInner = (content, tag) => {
    const raw = String(content || '').trim();
    if (!raw) return '无';
    const wrappedInner = takeTaggedExtractInner(raw, tag);
    if (wrappedInner) return wrappedInner;
    return raw.replace(new RegExp(`\\[${tag}_EXTRACT_(START|END)[^\\]]*\\]`, 'gi'), '').trim() || '无';
};

const replaceTaggedExtractBlock = (text, tag, nextInner) => {
    const source = String(text || '');
    const inner = String(nextInner || '').trim() || '无';
    const replacement = `[${tag}_EXTRACT_START]\n${inner}\n[${tag}_EXTRACT_END]`;
    const startRe = new RegExp(`\\[${tag}_EXTRACT_START[^\\]]*\\]`, 'i');
    const endRe = new RegExp(`\\[${tag}_EXTRACT_END[^\\]]*\\]`, 'i');
    const startMatch = startRe.exec(source);
    if (!startMatch) {
        const endBlockRe = /\[SCENES_BLOCK_END[^\]]*\]/i;
        const endBlock = endBlockRe.exec(source);
        if (endBlock) {
            return `${source.slice(0, endBlock.index).trimEnd()}\n\n${replacement}\n${source.slice(endBlock.index)}`;
        }
        return source ? `${source.trimEnd()}\n\n${replacement}` : replacement;
    }
    const afterStart = startMatch.index + startMatch[0].length;
    endRe.lastIndex = afterStart;
    const endMatch = endRe.exec(source);
    if (!endMatch) {
        return `${source.slice(0, startMatch.index)}${replacement}${source.slice(afterStart)}`;
    }
    return `${source.slice(0, startMatch.index)}${replacement}${source.slice(endMatch.index + endMatch[0].length)}`;
};

const parseTaggedExtractItemFields = (block, tag) => {
    const source = String(block || '').replace(/\r\n/g, '\n').trim();
    const fields = {};
    const fieldOrder = [];
    const remember = (key, value) => {
        const stable = String(key || '').trim();
        if (!stable) return;
        if (!fieldOrder.includes(stable)) fieldOrder.push(stable);
        fields[stable] = String(value ?? '').trim();
    };
    const lines = source.split('\n').map((line) => String(line || '').trim()).filter(Boolean);
    if (!lines.length) return { fields, fieldOrder };
    const first = lines[0].replace(new RegExp(`^\\[${tag}\\]\\s*`, 'i'), '');
    first.split(/[｜|]/).forEach((part) => {
        const eq = String(part || '').match(/^([^＝=:]+)[=：:]([\s\S]*)$/);
        if (eq) remember(eq[1], eq[2]);
    });
    lines.slice(1).forEach((line) => {
        const eq = String(line || '').match(/^([^＝=:]+)[=：:]([\s\S]*)$/);
        if (eq) remember(eq[1], eq[2]);
    });
    return { fields, fieldOrder };
};

const getExtractEditableFieldKeys = (tag, fields = {}, fieldOrder = []) => {
    const preferred = tag === 'PROP' ? PROP_EXTRACT_FIELD_KEYS : CHAR_EXTRACT_FIELD_KEYS;
    const keys = [];
    [...preferred, ...(Array.isArray(fieldOrder) ? fieldOrder : []), ...Object.keys(fields || {})].forEach((key) => {
        const stable = String(key || '').trim();
        if (stable && !keys.includes(stable)) keys.push(stable);
    });
    return keys;
};

const serializeTaggedExtractItem = (tag, fields = {}, fieldOrder = []) => {
    const headerKeys = EXTRACT_HEADER_KEYS[tag] || ['名称'];
    const preferred = tag === 'PROP' ? PROP_EXTRACT_FIELD_KEYS : CHAR_EXTRACT_FIELD_KEYS;
    const order = [];
    [...headerKeys, ...preferred, ...(Array.isArray(fieldOrder) ? fieldOrder : []), ...Object.keys(fields || {})].forEach((key) => {
        const stable = String(key || '').trim();
        if (stable && !order.includes(stable)) order.push(stable);
    });
    const header = `[${tag}] ${headerKeys.map((key) => `${key}=${String(fields?.[key] ?? '').trim()}`).join('｜')}`;
    const body = order
        .filter((key) => !headerKeys.includes(key))
        .map((key) => `${key}=${String(fields?.[key] ?? '').trim()}`)
        .join('\n');
    return [header, body].filter(Boolean).join('\n');
};

const replaceTaggedExtractItemInSource = (source, tag, oldName, newBlock) => {
    const items = splitTaggedExtractItems(source, tag);
    const wanted = normalizeSubjectKey(oldName);
    let found = false;
    const nextItems = items.map((item) => {
        if (wanted && normalizeSubjectKey(item.name) === wanted) {
            found = true;
            return { ...item, block: String(newBlock || '').trim() };
        }
        return item;
    }).filter((item) => String(item?.block || '').trim());
    if (!found && String(newBlock || '').trim()) {
        nextItems.push({
            name: extractTaggedItemName(newBlock, tag),
            block: String(newBlock || '').trim(),
        });
    }
    const inner = nextItems.map((item) => item.block).filter(Boolean).join('\n\n') || '无';
    return replaceTaggedExtractBlock(source, tag, inner);
};

const removeTaggedExtractItemInSource = (source, tag, name) => {
    const wanted = normalizeSubjectKey(name);
    const nextItems = splitTaggedExtractItems(source, tag).filter((item) => (
        !wanted || normalizeSubjectKey(item.name) !== wanted
    ));
    const inner = nextItems.map((item) => item.block).filter(Boolean).join('\n\n') || '无';
    return replaceTaggedExtractBlock(source, tag, inner);
};

const extractTagForRerunEntry = (entry) => {
    const type = String(entry?.type || '').trim().toLowerCase();
    if (type === 'character' || entry?.category === 'characters') return 'CHAR';
    if (type === 'prop' || entry?.category === 'props') return 'PROP';
    return '';
};

const applyExtractEntryPatchesToSource = (source, displayEntries, deletedSubjectKeys, originalEntries) => {
    let next = String(source || '');
    const deletedMap = (deletedSubjectKeys && typeof deletedSubjectKeys === 'object') ? deletedSubjectKeys : {};
    (originalEntries || []).forEach((original) => {
        if (original?.sourceKind !== 'extract') return;
        const tag = extractTagForRerunEntry(original);
        if (!tag || !deletedMap[original.key]) return;
        next = removeTaggedExtractItemInSource(next, tag, original.name);
    });
    (displayEntries || []).forEach((entry) => {
        if (entry?.sourceKind !== 'extract') return;
        const tag = extractTagForRerunEntry(entry);
        if (!tag) return;
        const original = (originalEntries || []).find((item) => item?.key === entry.key);
        const newBlock = serializeTaggedExtractItem(tag, entry.fields, entry.fieldOrder);
        if (!newBlock) return;
        next = replaceTaggedExtractItemInSource(next, tag, original?.name || entry.name, newBlock);
    });
    return next;
};

const filterTaggedExtractByNames = (text, tag, names) => {
    const wanted = new Set(
        (Array.isArray(names) ? names : [names])
            .map((name) => normalizeSubjectKey(name))
            .filter(Boolean)
    );
    if (!wanted.size) return '';
    const matched = splitTaggedExtractItems(text, tag).filter((item) => wanted.has(normalizeSubjectKey(item.name)));
    if (!matched.length) return '';
    const startToken = tag === 'PROP' ? '[PROP_EXTRACT_START]' : '[CHAR_EXTRACT_START]';
    const endToken = tag === 'PROP' ? '[PROP_EXTRACT_END]' : '[CHAR_EXTRACT_END]';
    return `${startToken}\n${matched.map((item) => item.block).join('\n\n')}\n${endToken}`;
};

const cleanCollectedMainEnvironmentName = (raw) => {
    const cleaned = String(raw || '').trim().replace(/^[`'“”‘’"[\]]+|[`'“”‘’"[\]]+$/g, '');
    const first = cleaned.split(/[｜|]/)[0].trim()
        .replace(/^(名称|主环境|环境名|环境)\s*[=：:]\s*/, '')
        .replace(/【活动空间】.*$/, '')
        .trim();
    if (!first || first.startsWith('─') || first.startsWith('-')) return '';
    const normalized = first.replace(/[\s_*`'"]+/g, '').toLowerCase();
    if (['none', 'null', 'nil', 'n/a', 'na', '无', '空'].includes(normalized)) return '';
    if (/主环境角色|活动空间|未落/.test(first)) return '';
    return first;
};

const collectMainEnvironmentNames = (text) => {
    const names = [];
    const seen = new Set();
    const add = (raw) => {
        const name = cleanCollectedMainEnvironmentName(raw);
        const key = normalizeSubjectKey(name);
        if (!name || !key || seen.has(key) || isDummySubject(name) || isDerivedEnvironmentName(name)) {
            return;
        }
        seen.add(key);
        names.push(name);
    };
    const source = String(text || '');
    const identRe = /^\s*`?\[ENV\]\s*名称\s*[=：:]\s*([^｜|\r\n]+)/gim;
    let match = identRe.exec(source);
    while (match) {
        add(match[1]);
        match = identRe.exec(source);
    }
    const mainRe = /^[ \t]*【主环境】[ \t]*(.+?)\s*$/gm;
    match = mainRe.exec(source);
    while (match) {
        add(match[1]);
        match = mainRe.exec(source);
    }
    return names;
};

const hasAssetRerunExtractSignals = (text) => {
    const source = String(text || '');
    return textHasTaggedExtractItems(source, 'CHAR')
        || textHasTaggedExtractItems(source, 'PROP')
        || /\[SCENE_ENV_IDENT_START/i.test(source)
        || /\[ENV_SCENE_PATCH_START/i.test(source)
        || /【主环境】/.test(source);
};

const resolveAssetCategoryKeysFromTargets = (targetEntityTypes) => {
    const raw = Array.isArray(targetEntityTypes) ? targetEntityTypes : null;
    if (!raw || raw.length === 0) return ['characters', 'props', 'environments'];
    const keys = new Set();
    for (const item of raw) {
        const key = String(item || '').trim().toLowerCase();
        if (['character', 'characters', 'role', 'roles', '人物', '角色'].includes(key)) keys.add('characters');
        else if (['prop', 'props', 'item', 'items', '道具', '物件'].includes(key)) keys.add('props');
        else if (['environment', 'environments', 'env', 'scene', 'scenes', '场景', '环境', 'poster', 'posters', 'cover', 'covers', 'cover_poster', '海报', '封面'].includes(key)) {
            keys.add('environments');
        }
    }
    return Array.from(keys);
};

const normalizeAssetCategoryKey = (value) => {
    const raw = String(value || '').trim().toLowerCase();
    if (['character', 'characters', 'role', 'roles'].includes(raw)) return 'characters';
    if (['prop', 'props', 'item', 'items'].includes(raw)) return 'props';
    if (['environment', 'environments', 'env', 'poster', 'posters', 'cover', 'covers', 'cover_poster'].includes(raw)) {
        return 'environments';
    }
    return raw;
};

const liveKeyForAssetCategory = (category) => {
    const key = normalizeAssetCategoryKey(category);
    if (key === 'characters') return 'character';
    if (key === 'props') return 'prop';
    if (key === 'environments') return 'environment';
    return '';
};

const SUBJECT_INDEX_STANDARD_HEADERS = [
    'subject_no',
    'subject_type',
    'subject_name_zh',
    'subject_name_en',
    'base_entity',
    'dependency_reference',
    'entity_attributes',
    'script_entity_coverage',
    'form_continuity',
];

const SUBJECT_INDEX_LONG_TEXT_FIELDS = new Set([
    'entity_attributes',
    'script_entity_coverage',
    'form_continuity',
    'description',
    'description_cn',
    'narrative_description',
]);

const SUBJECT_INDEX_FIELD_LABELS = {
    subject_no: { zh: '编号', en: 'Subject No' },
    subject_type: { zh: '类型', en: 'Type' },
    subject_name_zh: { zh: '中文名', en: 'Name (ZH)' },
    subject_name_en: { zh: '英文名', en: 'Name (EN)' },
    base_entity: { zh: '基准实体', en: 'Base Entity' },
    dependency_reference: { zh: '依赖引用', en: 'Dependency Reference' },
    entity_attributes: { zh: '实体属性', en: 'Entity Attributes' },
    script_entity_coverage: { zh: '剧本覆盖', en: 'Script Coverage' },
    form_continuity: { zh: '服化道连续性', en: 'Form Continuity' },
};

const resolveSubjectFieldValueByAliases = (fields, aliases = []) => {
    if (!fields || typeof fields !== 'object') return '';
    const normalizedMap = {};
    Object.entries(fields).forEach(([key, value]) => {
        const stableKey = String(key || '').trim();
        if (!stableKey) return;
        normalizedMap[stableKey] = String(value ?? '');
        normalizedMap[stableKey.toLowerCase()] = String(value ?? '');
        normalizedMap[stableKey.toLowerCase().replace(/[^a-z0-9_\u4e00-\u9fa5]+/g, '_')] = String(value ?? '');
    });
    for (const alias of aliases) {
        const stableAlias = String(alias || '').trim();
        if (!stableAlias) continue;
        const candidates = [
            stableAlias,
            stableAlias.toLowerCase(),
            stableAlias.toLowerCase().replace(/[^a-z0-9_\u4e00-\u9fa5]+/g, '_'),
        ];
        for (const candidate of candidates) {
            if (Object.prototype.hasOwnProperty.call(normalizedMap, candidate)) {
                return String(normalizedMap[candidate] ?? '').trim();
            }
        }
    }
    return '';
};

const normalizeSubjectIndexEntryFields = (rawFields = {}, entry = {}) => {
    const merged = {};
    if (rawFields && typeof rawFields === 'object') {
        Object.entries(rawFields).forEach(([key, value]) => {
            const stableKey = String(key || '').trim();
            if (!stableKey) return;
            merged[stableKey] = String(value ?? '').trim();
        });
    }

    const aliasGroups = {
        subject_no: ['subject_no', 'id', '编号'],
        subject_type: ['subject_type', 'type', '类型', '类别'],
        subject_name_zh: ['subject_name_zh', 'subject_name_exact', 'subject_name', 'name', '名称', '名字'],
        subject_name_en: ['subject_name_en', 'name_en', 'english_name', 'en_name'],
        base_entity: ['base_entity', 'base_entity_zh', '基准实体'],
        dependency_reference: ['dependency_reference', 'dependency', '依赖引用'],
        entity_attributes: ['entity_attributes', 'attributes', '实体属性'],
        script_entity_coverage: ['script_entity_coverage', 'coverage', '剧本覆盖'],
        form_continuity: ['form_continuity', '服化道连续性', '形态变化', '形态连续性'],
    };

    const resolved = {};
    Object.entries(aliasGroups).forEach(([canonical, aliases]) => {
        let value = String(merged[canonical] || '').trim();
        if (!value) {
            value = resolveSubjectFieldValueByAliases(merged, aliases);
        }
        if (!value && canonical === 'subject_name_zh') {
            value = String(entry?.name || '').trim();
        }
        if (!value && canonical === 'subject_no') {
            value = String(entry?.subjectNo || '').trim();
        }
        if (!value && canonical === 'subject_type') {
            value = String(entry?.type || '').trim();
        }
        resolved[canonical] = value;
    });

    SUBJECT_INDEX_STANDARD_HEADERS.forEach((header) => {
        if (!Object.prototype.hasOwnProperty.call(resolved, header)) {
            resolved[header] = '';
        }
    });

    Object.entries(merged).forEach(([key, value]) => {
        const stableKey = String(key || '').trim();
        if (!stableKey || SUBJECT_INDEX_STANDARD_HEADERS.includes(stableKey)) return;
        resolved[stableKey] = String(value ?? '').trim();
    });

    return resolved;
};

