    const wrapSceneUnitAsScriptBlock = useCallback((unit) => {
        if (!unit) return '';
        const sceneId = String(unit?.sceneId || '').trim();
        let sceneText = stripBlockLevelMarkersFromSceneText(unit?.sceneText || '');
        let markerStartToken = String(unit?.markerStartToken || '').trim();
        let markerEndToken = String(unit?.markerEndToken || '').trim();
        if (!markerStartToken && sceneId) markerStartToken = `[SCENE_START:${sceneId}]`;
        if (!markerEndToken && sceneId) markerEndToken = `[SCENE_END:${sceneId}]`;
        if (/^scenes?_table$/i.test(markerStartToken) && sceneId) markerStartToken = `[SCENE_START:${sceneId}]`;
        if (/^scenes?_table$/i.test(markerEndToken) && sceneId) markerEndToken = `[SCENE_END:${sceneId}]`;
        if (!sceneText) {
            sceneText = String(unit?.sceneMarkdown || unit?.scene_markdown || '').trim();
        }
        // Prefer Beat blocks; fall back to full scene when split fails / too short.
        const { bodyText, usedSceneFallback } = resolveSceneBeatsBodyForStage22(sceneText, sceneId);
        const bodyWithoutTransitionNotes = stripBeatTransitionNotesFromScript(bodyText);
        // Inject Stage 1 scene header only for beats-only body; full-scene fallback already contains it.
        const sceneNameMatch = !usedSceneFallback
            ? String(sceneText || '').match(/【场景名称】\s*[^\n【]+/)
            : null;
        const sceneNameHeader = sceneNameMatch ? String(sceneNameMatch[0] || '').trim() : '';
        const derivedEnvironmentNames = extractSceneDerivedEnvironmentNames(sceneText);
        return [
            SCENES_BLOCK_START_TOKEN,
            markerStartToken,
            sceneNameHeader,
            derivedEnvironmentNames ? `【本场衍生环境名】${derivedEnvironmentNames}` : '',
            bodyWithoutTransitionNotes,
            markerEndToken,
            SCENES_BLOCK_END_TOKEN,
        ].filter((part) => String(part || '').trim()).join('\n');
    }, []);

    const extractSceneDisplayLabel = useCallback((unit) => {
        const sceneId = String(unit?.sceneId || '').trim();
        const firstLine = String(unit?.sceneText || '')
            .split('\n')
            .map((line) => String(line || '').trim())
            .find(Boolean) || '';
        const namedFieldMatch = String(unit?.sceneText || '').match(/【场景名称】\s*([^\n【]+)/);
        const nameMatch = namedFieldMatch
            || firstLine.match(/【场景\s*\d+[：:]\s*([^】]+)】/)
            || firstLine.match(/\*\*【场景\s*[^】]+】\*\*/)
            || firstLine.match(/Scene\s*\d+\s*[:：]\s*(.+)$/i);
        const sceneName = nameMatch
            ? String(nameMatch[1] || nameMatch[0] || '')
                .replace(/[*【】]/g, '')
                .replace(/\s*[｜|]\s*.*$/, '')
                .trim()
            : '';
        if (sceneId && sceneName) return `${sceneId} · ${sceneName}`;
        return sceneId || sceneName || (uiLang === 'zh' ? '未命名场景' : 'Unnamed scene');
    }, [uiLang]);

