        const key = String(header || '').toLowerCase().replace(/[\s_.\-]/g, '');
        if (key.includes('coresceneinfo') || key.includes('核心场景') || key.includes('beats') || key.includes('节拍')) return 16;
        if (key.includes('adaptedscript') || key.includes('改编剧本')) return 8;
