    const openStageArtifactEditModal = useCallback(async (kind, options = {}) => {
        const stableKind = String(kind || '').trim();
        const requestedSceneId = String(options?.sceneId || '').trim();
        const episodePrefix = resolveEpisodeSceneIdPrefix(activeEpisode);
        if (activeEpisode?.id) {
            try {
                const freshEpisode = await fetchEpisode(activeEpisode.id);
                const freshNodeOutputs = collectStage1NodeOutputsFromSlotMap(
                    parseStageOutputsObject(freshEpisode?.ai_stage_outputs || '')?.stages?.stage1?.outputs
                );
                latestStage1NodeOutputsRef.current = {
                    ...freshNodeOutputs,
                    ...collectStage1NodeOutputsFromSlotMap(latestStage1NodeOutputsRef.current),
                };
            } catch (_) {}
        }
        if (SCENE_SUBSKILL_EDIT_KINDS.has(stableKind)) {
            const stage1Outputs = currentStageOutputs?.stages?.stage1?.outputs || {};
            const stepKey = SCENE_SUBSKILL_RESULT_KEYS[stableKind];
            const storedMap = parseSceneSubskillResultsMap(
                latestStage1NodeOutputsRef.current?.scene_subskill_results
                || stage1Outputs?.scene_subskill_results?.content
            );
            const source = String(
                latestStage1NodeOutputsRef.current?.scene_subskills
                || resolveScriptOptBeatsContent()
                || stage1Outputs?.scene_subskills?.content
                || stage1Outputs?.adapted_script?.content
                || activeEpisode?.ai_scene_analysis_adaptation
                || ''
            ).trim();
            const content = resolveCurrentSceneStage1Body({
                resultsMap: storedMap,
                sceneId: requestedSceneId,
                stepKey,
                episodePrefix,
                pipelineBlock: lookupPipelineSceneBlock(
                    diagnosticsPipelineNodesRef.current,
                    requestedSceneId,
                    episodePrefix
                ),
                scriptText: source,
            });
            if (!content) {
                reportAnalysisPanelNotice(t('暂无该场逐场优化内容可编辑。', 'No per-scene refinement content is available to edit.'), 'warning');
                return;
            }
            const labels = {
                drama_opt: ['文戏优化', 'Drama Refinement'],
                combat_opt: ['武戏增强', 'Action Enhancement'],
                framing_opt: ['场景现场编排', 'Floor Staging'],
                staging_opt: ['建置入戏', 'Staging'],
            };
            const [titleZh, titleEn] = labels[stableKind] || ['逐场优化', 'Per-Scene Refinement'];
            setStageArtifactEditModal({
                open: true,
                kind: stableKind,
                titleZh: `${titleZh} · ${requestedSceneId}`,
                titleEn: `${titleEn} · ${requestedSceneId}`,
                hintZh: '编辑该场当前 Stage 1 正文（含已完成的文戏/武戏/景别/建置）。保存只回写这一场，下游节点需按需重跑。',
                hintEn: 'Edit this scene’s current Stage 1 body (including completed drama/action/framing/staging). Saving writes back only this scene; rerun downstream nodes as needed.',
                content,
                editing: false,
                saving: false,
                sceneId: requestedSceneId,
                dbSceneId: null,
                scenes: [],
                headers: [],
                fields: {},
            });
            return;
        }
        if (stableKind === 'char_extract' || stableKind === 'prop_extract') {
            const tag = stableKind === 'char_extract' ? 'CHAR' : 'PROP';
            const source = String(
                currentStageOutputs?.stages?.stage1?.outputs?.scene_split?.content
                || latestStage1NodeOutputsRef.current?.scene_split
                || activeEpisode?.ai_scene_analysis_result
                || adaptationText
                || ''
            ).trim();
            const content = takeTaggedExtractBlock(source, tag)
                || `[${tag}_EXTRACT_START]\n无\n[${tag}_EXTRACT_END]`;
            setStageArtifactEditModal({
                open: true,
                kind: stableKind,
                titleZh: tag === 'CHAR' ? '角色提取描述' : '道具提取描述',
                titleEn: tag === 'CHAR' ? 'Character Extract' : 'Prop Extract',
                hintZh: '编辑全局统筹角色/道具提取描述后保存，再重跑对应资产生成。名称须与提取块 `名称=` 保持一致。',
                hintEn: 'Edit scene-split character/prop extract descriptions, save, then rerun that asset category. Keep `名称=` identical to the extract name.',
                content,
                editing: false,
                saving: false,
                sceneId: '',
                scenes: [],
                headers: [],
                fields: {},
            });
            return;
        }
        if (['scene_split', 'environment_plan', 'scene_subskills'].includes(stableKind)) {
            const content = String(
                latestStage1NodeOutputsRef.current?.[stableKind]
                || currentStageOutputs?.stages?.stage1?.outputs?.[stableKind]?.content
                || (stableKind === 'scene_subskills' ? resolveScriptOptBeatsContent() : '')
                || ''
            ).trim();
            if (!content) {
                reportAnalysisPanelNotice(t('暂无该节点内容可编辑。', 'No editable output is available for this node.'), 'warning');
                return;
            }
            const labels = {
                scene_split: ['全局统筹', 'Global Orchestration'],
                environment_plan: ['环境规划', 'Environment Plan'],
                scene_subskills: ['逐场优化', 'Per-Scene Refinement'],
            };
            const [titleZh, titleEn] = labels[stableKind];
            setStageArtifactEditModal({
                open: true,
                kind: stableKind,
                titleZh,
                titleEn,
                hintZh: '编辑该独立节点的完整输出；保存后将其作为当前 Stage 1 权威文本，后续节点应按需重跑。',
                hintEn: 'Edit this node’s complete output. Saving makes it the current authoritative Stage 1 text; rerun downstream nodes as needed.',
                content,
                editing: false,
                saving: false,
                sceneId: '',
                scenes: [],
                headers: [],
                fields: {},
            });
            return;
        }
        if (stableKind === 'script_opt') {
            const content = resolveScriptOptBeatsContent();
            if (!content) {
                reportAnalysisPanelNotice(t('暂无剧本统筹内容可查看。', 'No script-coordination content available yet.'), 'warning');
                return;
            }
            setStageArtifactEditModal({
                open: true,
                kind: 'script_opt',
                titleZh: '剧本统筹 · 完整剧本',
                titleEn: 'Script Coordination · Full Script',
                hintZh: '展示/编辑优化后剧本的完整内容：各场场景头、主环境/未落环境实体清单/衍生环境、观察视角与空间建置、Beats 等（不含修改说明与全局风格信息）。',
                hintEn: 'View/edit the full optimized script: per-scene headers, main/derived environments, spatial setup, beats, etc. (excludes revision notes and global-style info).',
                content,
                editing: false,
                saving: false,
                sceneId: '',
                scenes: [],
                headers: [],
                fields: {},
            });
            return;
        }
        if (stableKind === 'subject_index') {
            const content = resolveSubjectIndexEditContent();
            if (!content) {
                reportAnalysisPanelNotice(t('暂无资产清单内容可查看。', 'No asset inventory content available yet.'), 'warning');
                return;
            }
            setStageArtifactEditModal({
                open: true,
                kind: 'subject_index',
                titleZh: '资产清单',
                titleEn: 'Asset Inventory',
                hintZh: '可预览与编辑本集角色、道具、封面清单；环境由环境规划与场景分析直接生成，不再写入本表。',
                hintEn: 'Preview and edit this episode’s characters, props, and covers. Environments come from environment planning + scene analysis, not this table.',
                content,
                editing: false,
                saving: false,
                sceneId: '',
                scenes: [],
                headers: [],
                fields: {},
            });
            return;
        }
        if (stableKind === 'scene_beats') {
            const scenes = buildSceneBeatsEditScenes();
            if (!scenes.length) {
                reportAnalysisPanelNotice(t('暂无场景编排内容可编辑。', 'No scene orchestration content available to edit.'), 'warning');
                return;
            }
            const first = (
                requestedSceneId
                    ? scenes.find((item) => sceneUnitIdsMatch(
                        item.sceneId,
                        requestedSceneId,
                        item.sceneOrder || deriveSceneOrderFromSceneId(requestedSceneId),
                        episodePrefix
                    ))
                    : null
            ) || scenes[0];
            const parsedFields = parseSceneBeatsFieldsFromMarkdown(first.markdown);
            setStageArtifactEditModal({
                open: true,
                kind: 'scene_beats',
                titleZh: '场景编排 · 分场分字段编辑',
                titleEn: 'Scene Orchestration · Per-scene Field Edit',
                hintZh: '按场景切换，按 Scenes Table 列字段查看/修改；保存仅更新当前场，并回写合并后的场景编排产物。',
                hintEn: 'Switch scenes and edit Scenes Table columns as fields; save updates the selected scene and writes back the merged orchestration artifact.',
                content: first.markdown,
                editing: false,
                saving: false,
                sceneId: first.sceneId,
                dbSceneId: null,
                scenes,
                headers: parsedFields.headers,
                fields: parsedFields.fields,
            });
        }
    }, [
        activeEpisode,
        adaptationText,
        buildSceneBeatsEditScenes,
        currentStageOutputs,
        parseSceneBeatsFieldsFromMarkdown,
        reportAnalysisPanelNotice,
        resolveScriptOptBeatsContent,
        resolveSubjectIndexEditContent,
        t,
    ]);

    useEffect(() => {
        if (!stageArtifactEditModal.open || stageArtifactEditModal.kind !== 'scene_beats') return;
        const scenes = buildSceneBeatsEditScenes();
        setStageArtifactEditModal((prev) => {
            if (!prev.open || prev.kind !== 'scene_beats' || prev.editing || prev.saving) return prev;
            const currentId = String(prev.sceneId || '').trim();
            const nextScene = scenes.find((item) => String(item?.sceneId || '').trim() === currentId) || scenes[0] || null;
            const nextMarkdown = String(nextScene?.markdown || '');
            const prevScenes = Array.isArray(prev.scenes) ? prev.scenes : [];
            const sameScenes = prevScenes.length === scenes.length
                && scenes.every((item, index) => {
                    const previous = prevScenes[index];
                    return previous
                        && String(previous.sceneId || '') === String(item.sceneId || '')
                        && String(previous.markdown || '') === String(item.markdown || '');
                });
            if (sameScenes && String(prev.content || '') === nextMarkdown) return prev;
            const parsed = parseSceneBeatsFieldsFromMarkdown(nextMarkdown);
            return {
                ...prev,
                scenes,
                sceneId: nextScene?.sceneId || '',
                content: nextMarkdown,
                headers: parsed.headers,
                fields: parsed.fields,
            };
        });
    }, [
        buildSceneBeatsEditScenes,
        liveSceneMarkdownByScene,
        parseSceneBeatsFieldsFromMarkdown,
        stageArtifactEditModal.kind,
        stageArtifactEditModal.open,
    ]);

    const saveStageArtifactEditModal = useCallback(async () => {
        const kind = String(stageArtifactEditModal.kind || '').trim();
        let content = String(stageArtifactEditModal.content || '');
        if (kind === 'scene_beats') {
            if (Array.isArray(stageArtifactEditModal.headers) && stageArtifactEditModal.headers.length > 0) {
                const currentScene = (stageArtifactEditModal.scenes || []).find(
                    (item) => String(item?.sceneId || '').trim() === String(stageArtifactEditModal.sceneId || '').trim()
                );
                content = buildSceneBeatsMarkdownFromFields(
                    stageArtifactEditModal.headers,
                    stageArtifactEditModal.fields,
                    { displayLabel: currentScene?.displayLabel || stageArtifactEditModal.sceneId }
                );
            }
            if (!content.trim()) {
                reportAnalysisPanelNotice(t('当前场内容为空，无法保存。', 'Current scene content is empty; cannot save.'), 'warning');
                return;
            }
        }
        if (kind !== 'storyboard') {
            abortIfPromptInjectionRisk(content);
        }
        setStageArtifactEditModal((prev) => ({ ...prev, saving: true }));
        try {
            if (kind === 'script_opt') {
                await persistAdaptedScriptEdit(content);
            } else if (kind === 'char_extract' || kind === 'prop_extract') {
                const tag = kind === 'char_extract' ? 'CHAR' : 'PROP';
                const base = String(
                    latestStage1NodeOutputsRef.current?.scene_split
                    || currentStageOutputs?.stages?.stage1?.outputs?.scene_split?.content
                    || activeEpisode?.ai_scene_analysis_result
                    || adaptationText
                    || content
                    || ''
                ).trim();
                const nextSceneSplit = replaceTaggedExtractBlock(
                    base,
                    tag,
                    normalizeExtractReplacementInner(content, tag)
                );
                await persistSceneSplitExtractSource(nextSceneSplit);
            } else if (['scene_split', 'environment_plan', 'scene_subskills'].includes(kind)) {
                const stageOutputs = parseStageOutputsObject(activeEpisode?.ai_stage_outputs || '');
                const stages = (
                    stageOutputs.stages
                    && typeof stageOutputs.stages === 'object'
                    && !Array.isArray(stageOutputs.stages)
                ) ? stageOutputs.stages : {};
                const stage1 = (
                    stages.stage1
                    && typeof stages.stage1 === 'object'
                    && !Array.isArray(stages.stage1)
                ) ? stages.stage1 : { key: 'stage1', outputs: {} };
                const outputs = (
                    stage1.outputs
                    && typeof stage1.outputs === 'object'
                    && !Array.isArray(stage1.outputs)
                ) ? stage1.outputs : {};
                outputs[kind] = {
                    ...(outputs[kind] && typeof outputs[kind] === 'object' ? outputs[kind] : {}),
                    key: kind,
                    kind: 'markdown',
                    content: content.trim(),
                };
                stage1.outputs = outputs;
                stages.stage1 = stage1;
                stageOutputs.stages = stages;
                latestStage1NodeOutputsRef.current = {
                    ...latestStage1NodeOutputsRef.current,
                    [kind]: content.trim(),
                };
                await onUpdateEpisodeInfo(activeEpisode.id, {
                    ai_scene_analysis_adaptation: content.trim(),
                    ai_stage_outputs: JSON.stringify(stageOutputs, null, 2),
                });
                setAdaptationText(content.trim());
                latestStage1RawTextRef.current = content.trim();
            } else if (kind === 'subject_index') {
                await persistSubjectIndexEdit(content);
            } else if (SCENE_SUBSKILL_EDIT_KINDS.has(kind)) {
                const sceneId = String(stageArtifactEditModal.sceneId || '').trim();
                if (!sceneId) {
                    throw new Error(t('请先选择要保存的场景。', 'Select a scene to save first.'));
                }
                const episodePrefix = resolveEpisodeSceneIdPrefix(activeEpisode);
                const fullScript = String(
                    latestStage1NodeOutputsRef.current?.scene_subskills
                    || resolveScriptOptBeatsContent()
                    || activeEpisode?.ai_scene_analysis_adaptation
                    || ''
                ).trim();
                const nextScript = replaceAdaptedSceneBlockInScript(fullScript, sceneId, content.trim(), episodePrefix);
                const stepKey = SCENE_SUBSKILL_RESULT_KEYS[kind];
                const stageOutputs = parseStageOutputsObject(activeEpisode?.ai_stage_outputs || '');
                const existingMap = parseSceneSubskillResultsMap(
                    latestStage1NodeOutputsRef.current?.scene_subskill_results
                    || stageOutputs?.stages?.stage1?.outputs?.scene_subskill_results?.content
                );
                const nextMap = { ...existingMap };
                const sceneMap = {
                    ...(nextMap[sceneId] && typeof nextMap[sceneId] === 'object' ? nextMap[sceneId] : {}),
                };
                const editedBody = content.trim();
                if (stepKey) sceneMap[stepKey] = editedBody;
                const latestExistingKey = SCENE_SUBSKILL_BODY_KEYS.find((key) => String(sceneMap[key] || '').trim());
                if (latestExistingKey) sceneMap[latestExistingKey] = editedBody;
                nextMap[sceneId] = sceneMap;
                latestStage1NodeOutputsRef.current = {
                    ...latestStage1NodeOutputsRef.current,
                    scene_subskills: nextScript,
                    scene_subskill_results: JSON.stringify(nextMap),
                };
                await persistAdaptedScriptEdit(nextScript);
            } else if (kind === 'storyboard') {
                const dbSceneId = Number(stageArtifactEditModal.dbSceneId || 0);
                if (!Number.isFinite(dbSceneId) || dbSceneId <= 0) {
                    throw new Error(t('未找到该场对应的工作区场景，无法保存分镜草稿。', 'No workspace scene found for this row; cannot save storyboard draft.'));
                }
                let parsed = content;
                const trimmed = String(content || '').trim();
                if (trimmed.startsWith('[') || trimmed.startsWith('{')) {
                    parsed = JSON.parse(trimmed);
                }
                const rows = Array.isArray(parsed) ? parsed : (Array.isArray(parsed?.content) ? parsed.content : null);
                if (!rows) {
                    throw new Error(t('分镜草稿需要是镜头数组 JSON。', 'Storyboard draft must be a JSON array of shots.'));
                }
                await updateSceneLatestAIResult(dbSceneId, rows);
            } else if (kind === 'scene_beats') {
                const sceneId = String(stageArtifactEditModal.sceneId || '').trim();
                if (!sceneId) {
                    throw new Error(t('请先选择要保存的场景。', 'Select a scene to save first.'));
                }
                const currentScene = (stageArtifactEditModal.scenes || []).find(
                    (item) => String(item?.sceneId || '').trim() === sceneId
                );
                await persistSceneMarkdownPatch({
                    [sceneId]: {
                        scene_id: sceneId,
                        scene_order: Number(currentScene?.sceneOrder) || 0,
                        display_label: String(currentScene?.displayLabel || sceneId).trim(),
                        markdown: content.trim(),
                    },
                }, { source: 'stage-artifact-edit-scene-beats' });
            }
            const nextContent = kind === 'subject_index'
                ? (extractPureSubjectIndexText(content.trim()) || content.trim())
                : content.trim();
            const nextParsed = kind === 'scene_beats'
                ? parseSceneBeatsFieldsFromMarkdown(nextContent)
                : { headers: [], fields: {} };
            setStageArtifactEditModal((prev) => ({
                ...prev,
                saving: false,
                editing: false,
                content: nextContent,
                headers: kind === 'scene_beats' ? nextParsed.headers : (prev.headers || []),
                fields: kind === 'scene_beats' ? nextParsed.fields : (prev.fields || {}),
                scenes: kind === 'scene_beats'
                    ? (prev.scenes || []).map((item) => (
                        String(item?.sceneId || '').trim() === String(prev.sceneId || '').trim()
                            ? { ...item, markdown: nextContent }
                            : item
                    ))
                    : (prev.scenes || []),
            }));
            reportAnalysisPanelNotice(t('已保存更改。', 'Changes saved.'), 'success', 2500);
        } catch (error) {
            setStageArtifactEditModal((prev) => ({ ...prev, saving: false }));
            reportAnalysisPanelNotice(t(
                `保存失败：${error?.message || error}`,
                `Save failed: ${error?.message || error}`
            ), 'error', 4200);
        }
    }, [
        abortIfPromptInjectionRisk,
        adaptationText,
        buildSceneBeatsMarkdownFromFields,
        activeEpisode?.ai_stage_outputs,
        activeEpisode?.id,
        currentStageOutputs,
        extractPureSubjectIndexText,
        parseSceneBeatsFieldsFromMarkdown,
        parseStageOutputsObject,
        persistAdaptedScriptEdit,
        persistSceneMarkdownPatch,
        persistSceneSplitExtractSource,
        persistSubjectIndexEdit,
        onUpdateEpisodeInfo,
        resolveScriptOptBeatsContent,
        stageArtifactEditModal.content,
        stageArtifactEditModal.dbSceneId,
        stageArtifactEditModal.fields,
        stageArtifactEditModal.headers,
        stageArtifactEditModal.kind,
        stageArtifactEditModal.sceneId,
        stageArtifactEditModal.scenes,
        t,
        reportAnalysisPanelNotice,
    ]);

    const ensurePersistedSubjectIndexForDownstream = useCallback(async (preferredText = '') => {
        const liveSi = String(
            preferredText
            || latestStage2_1TextRef.current
            || subjectIndexText
            || currentStageOutputs?.stages?.stage2?.outputs?.subject_index?.content
            || ''
        ).trim();
        const episodeSi = String(activeEpisode?.ai_scene_analysis_subject_index || '').trim();
        const resolvedLive = extractPureSubjectIndexText(liveSi).trim() || liveSi;
        const resolvedEpisode = extractPureSubjectIndexText(episodeSi).trim() || episodeSi;

        // Prefer the latest live/index text (session persist, Stage 2.1 edit, stage_outputs).
        // Do not keep a usable-but-stale episode field when a newer inventory is available.
        const canonical = hasUsableSubjectIndexRows(resolvedLive)
            ? resolvedLive
            : (hasUsableSubjectIndexRows(resolvedEpisode) ? resolvedEpisode : (resolvedLive || resolvedEpisode || ''));
        if (!hasUsableSubjectIndexRows(canonical)) {
            return canonical;
        }
        if (canonical === resolvedEpisode) {
            return resolvedEpisode;
        }

        try {
            await persistSubjectIndexEdit(canonical);
            onLog?.(
                t(
                    '已将资产清单同步到本集，便于继续场景重排。',
                    'Synced the asset inventory into this episode so scene re-orchestration can continue.'
                ),
                'info'
            );
        } catch (healErr) {
            onLog?.(
                t(
                    `资产清单同步警告：${healErr?.message || healErr}`,
                    `Asset index sync warning: ${healErr?.message || healErr}`
                ),
                'warning'
            );
        }
        return canonical;
    }, [
        activeEpisode?.ai_scene_analysis_subject_index,
        currentStageOutputs?.stages?.stage2?.outputs?.subject_index?.content,
        extractPureSubjectIndexText,
        hasUsableSubjectIndexRows,
        onLog,
        persistSubjectIndexEdit,
        subjectIndexText,
        t,
    ]);

    const clearSceneMarkdownPatchForScenes = useCallback(async (sceneIds, options = {}) => {
        if (!activeEpisode?.id || !onUpdateEpisodeInfo) return;
        const targetIds = (Array.isArray(sceneIds) ? sceneIds : [])
            .map((sceneId) => String(sceneId || '').trim())
            .filter(Boolean);
        if (!targetIds.length) return;

        try {
            const persistedStageOutputs = parseStageOutputsObject(activeEpisode?.ai_stage_outputs || '');
            const persistedStage1RawText = String(persistedStageOutputs?.stages?.stage1?.outputs?.raw_text?.content || '').trim();
            const persistedStage2_1Text = String(persistedStageOutputs?.stages?.stage2?.outputs?.subject_index?.content || '').trim();
            const rawJson = String(persistedStageOutputs?.stages?.stage2?.outputs?.scene_markdown_by_scene?.content || '').trim();
            const sessionMap = (
                liveSceneMarkdownByScene && typeof liveSceneMarkdownByScene === 'object'
                    ? liveSceneMarkdownByScene
                    : parseSceneMarkdownBySceneMap(rawJson)
            );
            const nextMap = { ...(sessionMap && typeof sessionMap === 'object' ? sessionMap : {}) };
            targetIds.forEach((sceneId) => {
                delete nextMap[sceneId];
            });
            const remainingMarkdown = Object.values(nextMap)
                .map((entry) => String(entry?.markdown || '').trim())
                .filter(Boolean)
                .slice(-1)[0] || '';
            const logSource = String(options?.source || 'scene-markdown-clear').trim() || 'scene-markdown-clear';
            const trustLiveDownstreamOnly = Boolean(analysisTrustLiveDownstreamOnlyRef.current);
            const liveAssetDesignText = String(latestAssetRawTextRef.current || '').trim()
                || (trustLiveDownstreamOnly ? '' : String(activeEpisode?.ai_entity_design_result || llmAssetRawResultContent || '').trim());
            const liveStage1RawText = String(options?.stage1RawText || latestStage1RawTextRef.current || '').trim()
                || (trustLiveDownstreamOnly ? '' : persistedStage1RawText);
            const liveSubjectIndexText = options?.stage2_1Text !== undefined
                ? extractPureSubjectIndexText(options.stage2_1Text)
                : extractPureSubjectIndexText(
                    String(latestStage2_1TextRef.current || '').trim()
                    || (trustLiveDownstreamOnly ? '' : (persistedStage2_1Text || activeEpisode?.ai_scene_analysis_subject_index || ''))
                );
            await onUpdateEpisodeInfo(activeEpisode.id, {
                ai_scene_analysis_scene_markdown: remainingMarkdown,
                ai_stage_outputs: JSON.stringify(buildStageOutputsObject({
                    analysisRawText: remainingMarkdown,
                    assetRawText: liveAssetDesignText,
                    stage1RawText: liveStage1RawText,
                    stage2RawText: remainingMarkdown,
                    stage2_1Text: liveSubjectIndexText,
                    sceneMarkdownByScene: nextMap,
                    replaceSceneMarkdownByScene: true,
                    replaceSubjectIndex: true,
                }), null, 2),
            });
            orchestrationPersistedSceneMarkdownRef.current = nextMap;
            setLiveSceneMarkdownByScene(nextMap);
            onLog?.(`[Analysis Writeback] cleared scene_markdown_by_scene source=${logSource} scenes=${targetIds.join(',')}`, 'info');
        } catch (error) {
            console.error('Failed to clear per-scene scene markdown', error);
            onLog?.(`Failed to clear per-scene scene markdown: ${error?.message || error}`, 'warning');
            throw error;
        }
    }, [
        activeEpisode?.ai_entity_design_result,
        activeEpisode?.ai_scene_analysis_subject_index,
        activeEpisode?.ai_stage_outputs,
        activeEpisode?.id,
        buildStageOutputsObject,
        extractPureSubjectIndexText,
        liveSceneMarkdownByScene,
        llmAssetRawResultContent,
        onLog,
        onUpdateEpisodeInfo,
        parseSceneMarkdownBySceneMap,
        parseStageOutputsObject,
    ]);

    // Keep the "LLM 返回结果" box in sync with DB-saved ai_scene_analysis_result.
    // Important: don't clobber local edits while user is typing.
    const llmRawAutoSaveTimerRef = useRef(null);
    const llmRawAutoSaveArmedRef = useRef(false);
    const analysisResumeInFlightRef = useRef(false);
    const phase2ResolverRef = useRef(null);
    const assetRerunHandledNonceRef = useRef(null);
    const superuserModalMutexRef = useRef(Promise.resolve());
    const phase2GenerationInFlightRef = useRef(false);
    const phase2InFlightCategoriesRef = useRef(new Set());
    /** Synchronous entry lock so two analyze clicks cannot both pass the in-flight check during setup awaits. */
    const analysisEntryLockRef = useRef(false);
    /** Module-level claim token for the current click/run (survives remount). */
    const analysisClaimTokenRef = useRef('');
    /**
     * Episode id whose automatic Stage 3 already completed successfully in this browser session.
     * Blocks a second full auto asset-design fan-out after the first batch succeeds.
     */
    const phase2AutoCompletedEpisodeRef = useRef(null);
    const sceneBeatsOnlyRerunInFlightRef = useRef(false);
    const orchestrationLiveImportedScenesRef = useRef(new Set());
    /** Canonical Scene IDs from this run's scene orchestration (unitsToProcess). */
    const orchestrationCanonicalSceneIdsRef = useRef(new Set());
    const orchestrationPersistedSceneMarkdownRef = useRef({});
    const storyboardKickoffByMarkerRef = useRef(new Set());
    const storyboardKickoffByIdentityRef = useRef(new Set());
    const storyboardKickoffByDbIdRef = useRef(new Set());
    const storyboardKickoffPromisesRef = useRef(new Map());
    /** Pending storyboard kickoffs waiting for environment visual assets. */
    const pendingStoryboardKickoffsRef = useRef([]);
    /** Short-lived cache of ENV entities for storyboard gate checks (rerun / kickoff). */
    const storyboardEnvEntityCacheRef = useRef({ projectId: 0, episodeId: 0, at: 0, entities: null });
    /** True once env asset design for this run/episode is ready (or gate skipped). */
    const environmentAssetReadyRef = useRef(false);
    /**
     * True while this run's asset_design_environment (env + poster/cover) is expected
     * or in flight. Blocks storyboard from treating stale episode JSON as ready.
     */
    const environmentAssetDesignPendingRef = useRef(false);
    const stage3AutoStartCacheRef = useRef(null);
    /** Absolute epoch ms when the full analysis pipeline must stop (0 = inactive). */
    const analysisPipelineDeadlineRef = useRef(0);
    /** When true, Auto Zero Report Rerun must not dual-track persistence retries. */
    const analysisPipelineSupervisorActiveRef = useRef(false);
    /** Late-bound persistence supervisor (defined after asset/scene helpers). */
    const ensureEpisodeAnalysisCompleteByPersistenceRef = useRef(null);
    const activeAnalysisTaskIdsRef = useRef(new Set());
    const analysisRunInFlightRef = useRef(false);
    const analysisResumeCoordinatorRef = useRef({ running: false, episodeId: null });
    /** Late-bound continue helper (Stage 1 done / incomplete artifacts) — avoids TDZ with resume callbacks. */
    const resumeIncompleteAnalysisPipelineRef = useRef(null);
    const ensureUnfinishedAnalysisNodesRef = useRef(null);
    /** Staging imported but storyboard not started — keep analyzing so poll can kick off shots. */
    const analysisAwaitingStoryboardRef = useRef(false);
    const detachedAnalysisRunEpisodeRef = useRef(null);
    const mountResumeReadyRef = useRef(false);
    const forceRegenerateRef = useRef(false);
    const autoImportRunningRef = useRef(false);

    useEffect(() => {
        captureAnalysisLogRef.current = () => {
            if (analysisProgressDismissedRef.current) return false;
            if (analysisRunInFlightRef.current) return true;
            if (latestIsAnalyzingRef.current) return true;
            if (phase2GenerationInFlightRef.current) return true;
            if (analysisResumeInFlightRef.current) return true;
            const ui = latestAnalysisProgressUiRef.current;
            const phase = String(ui?.flowStatus?.phase || '').trim().toLowerCase();
            if (phase && !['idle', ''].includes(phase)) return true;
            if (Array.isArray(ui?.flowHistory) && ui.flowHistory.length > 0) return true;
            if (ui?.uiReport && typeof ui.uiReport === 'object') return true;
            return false;
        };
    });
    const lastScriptLeaveNoticeAtRef = useRef(0);
    const lastTryResumePendingAnalysisAtRef = useRef(0);
    const lastAutoSubjectsImportRef = useRef({ signature: '', result: null });
    const lastSubjectsImportIncompleteAlertRef = useRef('');
    const lastPersistPayloadSignatureRef = useRef({});
    const ANALYSIS_TASK_MAX_AGE_MS = 60 * 60 * 1000;
    const ANALYSIS_TASK_MARKER_TTL_MS = 120 * 60 * 1000;
    const AI_SHOTS_TASK_MARKER_TTL_MS = 45 * 60 * 1000;

    const resetAnalysisFallbackRetryCounts = useCallback((episodeId) => {
        const id = Number(episodeId || 0);
        if (!id) return;
        autoZeroReportHandledRef.current = { key: '', handledAt: 0 };
        analysisFallbackRetryRef.current = {
            episodeId: id,
            sceneBeatsAttempts: 0,
            assetAttempts: 0,
            sceneRegenAttempts: 0,
            running: false,
        };
    }, []);

    const ensureAnalysisFallbackState = useCallback((episodeId) => {
        const id = Number(episodeId || 0);
        if (!id) return null;
        if (analysisFallbackRetryRef.current.episodeId !== id) {
            const snapshot = loadAnalysisSessionSnapshot(id);
            if (snapshot?.fallbackRetry?.episodeId === id) {
                analysisFallbackRetryRef.current = {
                    ...snapshot.fallbackRetry,
                    episodeId: id,
                    running: false,
                };
                if (snapshot?.autoZeroReportHandledKey) {
                    autoZeroReportHandledRef.current = {
                        key: String(snapshot.autoZeroReportHandledKey || ''),
                        handledAt: Number(snapshot.savedAt || Date.now()),
                    };
                }
            } else {
                resetAnalysisFallbackRetryCounts(id);
            }
        }
        return analysisFallbackRetryRef.current;
    }, [resetAnalysisFallbackRetryCounts]);

    const canAttemptAnalysisFallback = useCallback((episodeId, kind) => {
        const state = ensureAnalysisFallbackState(episodeId);
        if (!state) return false;
        const fieldByKind = {
            scene_beats: 'sceneBeatsAttempts',
            asset_gen: 'assetAttempts',
            scene_regen: 'sceneRegenAttempts',
        };
        const field = fieldByKind[kind];
        if (!field) return false;
        return Number(state[field] || 0) < MAX_ANALYSIS_FALLBACK_ATTEMPTS;
    }, [ensureAnalysisFallbackState]);

    const recordAnalysisFallbackAttempt = useCallback((episodeId, kind) => {
        const state = ensureAnalysisFallbackState(episodeId);
        if (!state) return;
        const fieldByKind = {
            scene_beats: 'sceneBeatsAttempts',
            asset_gen: 'assetAttempts',
            scene_regen: 'sceneRegenAttempts',
        };
        const field = fieldByKind[kind];
        if (field) state[field] = Number(state[field] || 0) + 1;
    }, [ensureAnalysisFallbackState]);

    const getAnalysisFallbackRemaining = useCallback((episodeId, kind) => {
        const state = ensureAnalysisFallbackState(episodeId);
        if (!state) return 0;
        const fieldByKind = {
            scene_beats: 'sceneBeatsAttempts',
            asset_gen: 'assetAttempts',
            scene_regen: 'sceneRegenAttempts',
        };
        const field = fieldByKind[kind];
        if (!field) return 0;
        return Math.max(0, MAX_ANALYSIS_FALLBACK_ATTEMPTS - Number(state[field] || 0));
    }, [ensureAnalysisFallbackState]);

    const isTaskCanceledError = useCallback((error) => {
        if (!error) return false;
        if (error?.isCanceled || error?.isPipelineTimeout) return true;
        const code = Number(error?.errorCode || error?.response?.status || 0);
        if (code === 499) return true;
        const text = String(error?.message || error?.response?.data?.detail || '').toLowerCase();
        if (text.includes('cancel') || text.includes('取消')) return true;
        // Only treat the full-pipeline wall-clock stop as a soft cancel (not generic LLM timeouts).
        return text.includes('60-minute pipeline')
            || text.includes('60 分钟全流程')
            || text.includes('pipeline limit');
    }, []);

    const createAnalysisCanceledError = useCallback(() => {
        const error = new Error(t('用户已中断剧本分析任务。', 'Script analysis was stopped by the user.'));
        error.isCanceled = true;
        error.errorCode = 499;
        return error;
    }, [t]);

    const createAnalysisPipelineTimeoutError = useCallback(() => {
        const error = new Error(t(
            '剧本分析已超过 60 分钟全流程时限，任务已自动停止。',
            'Script analysis exceeded the 60-minute pipeline limit and was stopped automatically.'
        ));
        error.isCanceled = true;
        error.isPipelineTimeout = true;
        error.errorCode = 408;
        return error;
    }, [t]);

    const getAnalysisPipelineRemainingMs = useCallback(() => {
        const episodeId = Number(activeEpisode?.id || latestActiveEpisodeIdRef.current || 0);
        if (episodeId) {
            return getEpisodeAnalysisPipelineRemainingMs(episodeId);
        }
        const deadline = Number(analysisPipelineDeadlineRef.current || 0);
        if (!Number.isFinite(deadline) || deadline <= 0) return Number.POSITIVE_INFINITY;
        return Math.max(0, deadline - Date.now());
    }, [activeEpisode?.id]);

    const armAnalysisPipelineDeadline = useCallback((startedAt = Date.now()) => {
        const start = Number(startedAt || Date.now());
        const episodeId = Number(activeEpisode?.id || latestActiveEpisodeIdRef.current || 0);
        analysisPipelineDeadlineRef.current = (
            Number.isFinite(start) && start > 0 ? start : Date.now()
        ) + ANALYSIS_PIPELINE_MAX_MS;
        analysisPipelineSupervisorActiveRef.current = true;
        analysisStopRequestedRef.current = false;
        analysisStopReasonRef.current = '';
        if (episodeId) {
            armEpisodeAnalysisPipelineControl(episodeId, {
                startedAt: start,
                maxMs: ANALYSIS_PIPELINE_MAX_MS,
            });
        }
    }, [activeEpisode?.id]);

    const clearAnalysisPipelineDeadline = useCallback(() => {
        // Local UI refs only. Module control (stop/deadline) must survive remount and
        // stay readable by the original run closure until the tracked promise settles.
        analysisPipelineDeadlineRef.current = 0;
        analysisPipelineSupervisorActiveRef.current = false;
    }, []);

    const cancelActiveAnalysisTasksBestEffort = useCallback(async (reason = '') => {
        const taskIds = Array.from(new Set([
            ...Array.from(activeAnalysisTaskIdsRef.current || []),
            String(activeAnalysisTaskId || '').trim(),
        ].filter(Boolean)));
        if (taskIds.length <= 0) return;
        try {
            await Promise.allSettled(taskIds.map((taskId) => stopAsyncTask(taskId)));
            if (onLog) {
                onLog(
                    `Scene analysis stop/cancel tasks (${reason || 'unspecified'}): task_ids=${taskIds.join(',')}`,
                    'warning'
                );
            }
        } catch (_) {
            // best-effort
        }
    }, [activeAnalysisTaskId, onLog]);

    const throwIfAnalysisStopped = useCallback(() => {
        const episodeId = Number(activeEpisode?.id || latestActiveEpisodeIdRef.current || 0);
        const control = episodeId ? getEpisodeAnalysisPipelineControl(episodeId) : null;
        const stopRequested = Boolean(
            analysisStopRequestedRef.current
            || control?.stopRequested
        );
        const stopReason = String(
            analysisStopReasonRef.current
            || control?.stopReason
            || ''
        ).trim();

        if (stopRequested) {
            analysisStopRequestedRef.current = true;
            analysisStopReasonRef.current = stopReason || 'user';
            if (stopReason === 'timeout') {
                throw createAnalysisPipelineTimeoutError();
            }
            throw createAnalysisCanceledError();
        }

        const remainingMs = getAnalysisPipelineRemainingMs();
        if (Number.isFinite(remainingMs) && remainingMs <= 0) {
            analysisStopRequestedRef.current = true;
            analysisStopReasonRef.current = 'timeout';
            if (episodeId) {
                requestEpisodeAnalysisPipelineStop(episodeId, 'timeout');
            }
            void cancelActiveAnalysisTasksBestEffort('pipeline-timeout');
            throw createAnalysisPipelineTimeoutError();
        }
    }, [
        activeEpisode?.id,
        cancelActiveAnalysisTasksBestEffort,
        createAnalysisCanceledError,
        createAnalysisPipelineTimeoutError,
        getAnalysisPipelineRemainingMs,
    ]);

    const registerActiveAnalysisTask = useCallback((taskId) => {
        const stableTaskId = String(taskId || '').trim();
        if (!stableTaskId) return '';
        activeAnalysisTaskIdsRef.current.add(stableTaskId);
        setActiveAnalysisTaskId(stableTaskId);
        return stableTaskId;
    }, []);

    const persistAnalysisSessionSnapshot = useCallback((episodeId) => {
        const id = Number(episodeId || 0);
        if (!id) return;
        const prev = loadAnalysisSessionSnapshot(id) || {};
        const ui = latestAnalysisProgressUiRef.current;
        const dismissed = analysisProgressDismissedRef.current;
        const progressUi = dismissed
            ? {
                dismissed: true,
                flowStatus: { phase: 'idle', message: '' },
                flowHistory: [],
                detailLogs: [],
                uiReport: null,
            }
            : {
                dismissed: false,
                flowStatus: (ui.flowStatus && typeof ui.flowStatus === 'object')
                    ? ui.flowStatus
                    : { phase: 'idle', message: '' },
                flowHistory: Array.isArray(ui.flowHistory) ? ui.flowHistory.slice(-ANALYSIS_FLOW_HISTORY_CAP) : [],
                detailLogs: Array.isArray(ui.detailLogs) ? ui.detailLogs.slice(-ANALYSIS_DETAIL_LOG_CAP) : [],
                uiReport: slimAnalysisUiReportForSnapshot(ui.uiReport),
            };
        saveAnalysisSessionSnapshot(id, {
            ...prev,
            episodeId: id,
            autoZeroReportHandledKey: String(autoZeroReportHandledRef.current?.key || ''),
            fallbackRetry: {
                episodeId: id,
                sceneBeatsAttempts: Number(analysisFallbackRetryRef.current?.sceneBeatsAttempts || 0),
                assetAttempts: Number(analysisFallbackRetryRef.current?.assetAttempts || 0),
                sceneRegenAttempts: Number(analysisFallbackRetryRef.current?.sceneRegenAttempts || 0),
                running: false,
            },
            progressUi,
            savedAt: Date.now(),
        });
    }, []);

    const hasPersistableAnalysisProgress = useCallback((flowStatus, flowHistory, uiReport) => {
        if (Array.isArray(flowHistory) && flowHistory.length > 0) return true;
        if (uiReport && typeof uiReport === 'object') return true;
        const phase = String(flowStatus?.phase || '').trim().toLowerCase();
        return Boolean(phase && phase !== 'idle');
    }, []);

    const clearDiagnosticsPanelState = useCallback(() => {
        diagnosticsEpochRef.current += 1;
        diagnosticsNodeLogStateRef.current = {};
        latestStage1NodeOutputsRef.current = {};
        diagnosticsPipelineNodesRef.current = [];
        diagnosticsSceneUnitsRef.current = [];
        setDiagnosticsPipelineNodes([]);
        setDiagnosticsSceneUnits([]);
        setDiagnosticsEpisodeSceneCount(0);
        setDiagnosticsEpisodeScenes([]);
        setDiagnosticsEpisodeShotStats({ shotCount: 0, sceneCountWithShots: 0 });
        setDiagnosticsRefreshNonce((value) => value + 1);
    }, []);

    const resetEpisodeDiagnosticsProgress = useCallback(async () => {
        analysisTrustLiveDownstreamOnlyRef.current = true;
        // Clear leftover pipeline rows before publishing empty storyboard progress.
        // Otherwise resetStoryboardKickoffTracking republishes last-run
        // storyboard_generation success nodes into the live snapshot.
        diagnosticsPipelineNodesRef.current = [];
        diagnosticsSceneUnitsRef.current = [];
        resetStoryboardKickoffTracking();
        orchestrationCanonicalSceneIdsRef.current = new Set();
        orchestrationLiveImportedScenesRef.current = new Set();
        orchestrationPersistedSceneMarkdownRef.current = {};
        setLiveSceneMarkdownByScene({});
        clearDiagnosticsPanelState();
        publishLiveAnalysisProgressSnapshot({
            pipelineNodes: [],
            sceneUnits: [],
            uiReport: {
                ...(analysisUiReportRef.current && typeof analysisUiReportRef.current === 'object'
                    ? analysisUiReportRef.current
                    : {}),
                storyboardTaskProgress: EMPTY_STORYBOARD_TASK_PROGRESS,
            },
        });
        const episodeId = Number(activeEpisode?.id || 0);
        const pid = Number(projectId || 0);
        if (!episodeId || !pid) return;
        try {
            await resetEpisodeAnalysisProgress({
                project_id: pid,
                episode_id: episodeId,
            });
        } catch (resetErr) {
            onLog?.(`Diagnosis panel reset warning: ${resetErr?.message || resetErr}`, 'warning');
        } finally {
            // Invalidate polls that started during reset-episode and still hold the old snapshot.
            diagnosticsEpochRef.current += 1;
            diagnosticsPipelineNodesRef.current = [];
            diagnosticsSceneUnitsRef.current = [];
            setDiagnosticsPipelineNodes([]);
            setDiagnosticsSceneUnits([]);
            setDiagnosticsRefreshNonce((value) => value + 1);
            publishLiveAnalysisProgressSnapshot({
                pipelineNodes: [],
                sceneUnits: [],
            });
        }
    }, [
        activeEpisode?.id,
        clearDiagnosticsPanelState,
        onLog,
        projectId,
        publishLiveAnalysisProgressSnapshot,
        resetStoryboardKickoffTracking,
    ]);

    const clearAnalysisProgressUiState = useCallback((episodeId, { persist = true } = {}) => {
        const id = Number(episodeId || activeEpisode?.id || 0);
        analysisTimerStartedAtRef.current = 0;
        latestIsAnalyzingRef.current = false;
        setIsAnalyzing(false);
        setActiveAnalysisTaskId('');
        setAnalysisFlowStatus({ phase: 'idle', message: '' });
        setAnalysisFlowStatusHistory([]);
        setAnalysisDetailLogs([]);
        setAnalysisUiReport(null);
        setAnalysisReviewIssues([]);
        resetStoryboardKickoffTracking();
        if (id) {
            clearEpisodeAnalysisProgress(id);
            clearEpisodeAnalysisDetached(id);
        }
        if (persist && id) {
            clearAnalysisSessionProgressSnapshot(id);
        }
    }, [activeEpisode?.id, resetStoryboardKickoffTracking, setAnalysisDetailLogs, setAnalysisFlowStatus, setAnalysisFlowStatusHistory, setAnalysisUiReport]);

    const applyLiveAnalysisProgressSnapshot = useCallback((snapshot) => {
        if (!snapshot || typeof snapshot !== 'object') return false;
        applyingRemoteProgressRef.current = true;
        try {
            const flowStatus = (snapshot.flowStatus && typeof snapshot.flowStatus === 'object')
                ? snapshot.flowStatus
                : { phase: 'idle', message: '' };
            const flowHistory = Array.isArray(snapshot.flowHistory) ? snapshot.flowHistory : [];
            const detailLogs = Array.isArray(snapshot.detailLogs) ? snapshot.detailLogs : [];
            const uiReport = (snapshot.uiReport && typeof snapshot.uiReport === 'object') ? snapshot.uiReport : null;

            analysisFlowStatusRef.current = flowStatus;
            analysisFlowHistoryRef.current = flowHistory;
            analysisDetailLogsRef.current = detailLogs.slice(-ANALYSIS_DETAIL_LOG_CAP);
            analysisUiReportRef.current = uiReport;
            latestAnalysisProgressUiRef.current = {
                flowStatus,
                flowHistory,
                uiReport,
                detailLogs: analysisDetailLogsRef.current,
            };

            setAnalysisFlowStatusState(flowStatus);
            setAnalysisFlowStatusHistoryState(flowHistory);
            setAnalysisDetailLogsState([...analysisDetailLogsRef.current]);
            if (uiReport) {
                setAnalysisUiReportState(uiReport);
                setAnalysisReviewIssues(Array.isArray(uiReport.reviewIssues) ? uiReport.reviewIssues : []);
                const restoredStoryboard = normalizeStoryboardTaskProgress(uiReport.storyboardTaskProgress);
                const localStoryboard = normalizeStoryboardTaskProgress(storyboardTaskProgressRef.current);
                const livePhase = String(
                    snapshot.flowStatus?.phase || analysisFlowStatusRef.current?.phase || ''
                ).trim().toLowerCase();
                const beforeStoryboardPhase = !['storyboard', 'completed', 'warning', 'failed'].includes(livePhase);
                const localInFlight = isStoryboardProgressUnresolved(localStoryboard)
                    || Object.values(localStoryboard.items || {}).some(storyboardItemIsInFlight);
                const restoredInFlight = isStoryboardProgressUnresolved(restoredStoryboard)
                    || Object.values(restoredStoryboard.items || {}).some(storyboardItemIsInFlight);
                const restoredOnlySettled = Number(restoredStoryboard.started || 0) > 0 && !restoredInFlight;
                const keepClearedStoryboard = Boolean(
                    analysisTrustLiveDownstreamOnlyRef.current
                    && (
                        (beforeStoryboardPhase && Number(localStoryboard.started || 0) <= 0 && !localInFlight)
                        || (localInFlight && restoredOnlySettled)
                        || (restoredOnlySettled && Number(localStoryboard.started || 0) <= 0)
                    )
                );
                if (
                    !keepClearedStoryboard
                    && (
                        Number(restoredStoryboard.started || 0) > 0
                        || Object.keys(restoredStoryboard.items || {}).length > 0
                    )
                ) {
                    if (analysisTrustLiveDownstreamOnlyRef.current && localInFlight) {
                        const mergedItems = { ...(restoredStoryboard.items || {}) };
                        Object.entries(localStoryboard.items || {}).forEach(([key, item]) => {
                            const identity = storyboardProgressIdentityKey(key, item);
                            const matchKey = Object.keys(mergedItems).find((candidate) => (
                                storyboardProgressIdentityKey(candidate, mergedItems[candidate]) === identity
                            ));
                            if (!matchKey) {
                                mergedItems[key] = item;
                                return;
                            }
                            if (storyboardStatusRank(item?.status) >= storyboardStatusRank(mergedItems[matchKey]?.status)) {
                                const kept = { ...mergedItems[matchKey], ...item };
                                if (matchKey !== key) delete mergedItems[matchKey];
                                mergedItems[key] = kept;
                            }
                        });
                        const merged = normalizeStoryboardTaskProgress({ items: mergedItems });
                        storyboardTaskProgressRef.current = merged;
                        setStoryboardTaskProgressState(merged);
                    } else {
                        storyboardTaskProgressRef.current = restoredStoryboard;
                        setStoryboardTaskProgressState(restoredStoryboard);
                    }
                }
                if (String(uiReport?.status || '').trim().toLowerCase() === 'running') {
                    beginAnalysisTimer(Number(uiReport?.startedAt || Date.now()));
                }
            }
            if (Object.prototype.hasOwnProperty.call(snapshot, 'isAnalyzing')) {
                const nextAnalyzing = Boolean(snapshot.isAnalyzing);
                const episodeId = Number(latestActiveEpisodeIdRef.current || 0);
                const userStopped = isEpisodeAnalysisUserStopRequested(episodeId, {
                    localStopRequested: analysisStopRequestedRef.current,
                    localStopReason: analysisStopReasonRef.current,
                });
                const keepLive = !userStopped && !nextAnalyzing && episodeId > 0 && (
                    isEpisodeAnalysisClaimed(episodeId)
                    || Boolean(getEpisodeAnalysisRun(episodeId)?.promise)
                );
                if (!keepLive) {
                    latestIsAnalyzingRef.current = nextAnalyzing;
                    setIsAnalyzing(nextAnalyzing);
                }
            }
            const hasThisRunStage1 = Boolean(
                String(latestStage1NodeOutputsRef.current?.scene_split || '').trim()
                || String(latestStage1RawTextRef.current || '').trim()
            );
            const skipLeftoverProgressRows = Boolean(
                analysisTrustLiveDownstreamOnlyRef.current && !hasThisRunStage1
            );
            if (Array.isArray(snapshot.pipelineNodes) && !skipLeftoverProgressRows) {
                const nextNodes = analysisTrustLiveDownstreamOnlyRef.current
                    ? filterLeftoverStoryboardPipelineNodes(
                        snapshot.pipelineNodes,
                        storyboardTaskProgressRef.current,
                    )
                    : snapshot.pipelineNodes;
                diagnosticsPipelineNodesRef.current = nextNodes;
                setDiagnosticsPipelineNodes(nextNodes);
            }
            if (Array.isArray(snapshot.sceneUnits) && !skipLeftoverProgressRows) {
                diagnosticsSceneUnitsRef.current = snapshot.sceneUnits;
                setDiagnosticsSceneUnits(snapshot.sceneUnits);
            }
            return true;
        } finally {
            applyingRemoteProgressRef.current = false;
        }
    }, [beginAnalysisTimer]);

    const restoreAnalysisProgressFromSession = useCallback((episodeId) => {
        const id = Number(episodeId || 0);
        if (!id) return false;
        const live = getEpisodeAnalysisProgress(id);
        if (live && Number(live.updatedAt || 0) > 0) {
            analysisProgressDismissedRef.current = false;
            applyLiveAnalysisProgressSnapshot(live);
            const liveRunning = Boolean(live.isAnalyzing) || isPersistedAnalysisProgressRunning({
                flowStatus: live.flowStatus,
                flowHistory: live.flowHistory,
                uiReport: live.uiReport,
            });
            if (liveRunning) {
                setIsAnalyzing(true);
                latestIsAnalyzingRef.current = true;
            } else {
                const display = resolveAnalysisProgressDisplayState({
                    isAnalyzing: false,
                    isRetryingPhase2: false,
                    phase: live.flowStatus?.phase,
                    reportStatus: live.uiReport?.status,
                    storyboardProgress: live.uiReport?.storyboardTaskProgress,
                });
                if (['completed', 'warning', 'failed'].includes(display.displayPhase)
                    && (
                        !['completed', 'warning', 'failed', 'idle'].includes(String(live.flowStatus?.phase || '').trim().toLowerCase())
                        || String(live.uiReport?.status || '').trim().toLowerCase() === 'running'
                    )
                ) {
                    const startedAt = Number(live.uiReport?.startedAt || 0);
                    setAnalysisFlowStatus({
                        phase: display.displayPhase,
                        message: String(live.flowStatus?.message || '').trim()
                            || t('分镜生成已结束', 'Storyboard generation finished'),
                        highlightHint: live.flowStatus?.highlightHint || '',
                    });
                    if (live.uiReport) {
                        setAnalysisUiReport({
                            ...live.uiReport,
                            status: String(live.uiReport.status || '').trim().toLowerCase() === 'failed'
                                ? live.uiReport.status
                                : display.displayPhase,
                            durationMs: Number(live.uiReport.durationMs || 0) > 0
                                ? Number(live.uiReport.durationMs)
                                : (startedAt > 0 ? Math.max(0, Date.now() - startedAt) : 0),
                        });
                    }
                }
                setIsAnalyzing(false);
                latestIsAnalyzingRef.current = false;
            }
            return true;
        }
        const snapshot = loadAnalysisSessionSnapshot(id);
        const progressUi = snapshot?.progressUi;
        if (!progressUi || progressUi.dismissed === true) {
            analysisProgressDismissedRef.current = Boolean(progressUi?.dismissed);
            return false;
        }
        const isRunning = isPersistedAnalysisProgressRunning(progressUi);
        analysisProgressDismissedRef.current = false;
        const flowStatus = (progressUi.flowStatus && typeof progressUi.flowStatus === 'object')
            ? progressUi.flowStatus
            : { phase: 'idle', message: '' };
        const flowHistory = Array.isArray(progressUi.flowHistory) ? progressUi.flowHistory : [];
        const detailLogs = Array.isArray(progressUi.detailLogs) ? progressUi.detailLogs : [];
        const uiReport = (progressUi.uiReport && typeof progressUi.uiReport === 'object') ? progressUi.uiReport : null;
        if (!isRunning && !hasPersistableAnalysisProgress(flowStatus, flowHistory, uiReport)) return false;
        applyLiveAnalysisProgressSnapshot({
            flowStatus,
            flowHistory,
            detailLogs,
            uiReport,
            isAnalyzing: isRunning,
        });
        if (isRunning) {
            setIsAnalyzing(true);
            try {
                const markerKey = id > 0 ? `aistory:scene-analysis-task:${id}` : '';
                const rawMarker = markerKey && window?.localStorage?.getItem(markerKey);
                if (rawMarker) {
                    const parsedMarker = JSON.parse(rawMarker);
                    const taskId = String(parsedMarker?.taskId || '').trim();
                    if (taskId) setActiveAnalysisTaskId(taskId);
                }
            } catch (_) {
                // Ignore marker parse failures during restore.
            }
        } else {
            // Stale intermediate phase / status=running after the run flag cleared — align to shared display.
            const display = resolveAnalysisProgressDisplayState({
                isAnalyzing: false,
                isRetryingPhase2: false,
                phase: flowStatus?.phase,
                reportStatus: uiReport?.status,
                storyboardProgress: uiReport?.storyboardTaskProgress,
            });
            if (['completed', 'warning', 'failed'].includes(display.displayPhase)
                && (
                    !['completed', 'warning', 'failed', 'idle'].includes(String(flowStatus?.phase || '').trim().toLowerCase())
                    || String(uiReport?.status || '').trim().toLowerCase() === 'running'
                )
            ) {
                const startedAt = Number(uiReport?.startedAt || 0);
                setAnalysisFlowStatus({
                    phase: display.displayPhase,
                    message: String(flowStatus?.message || '').trim()
                        || t('分镜生成已结束', 'Storyboard generation finished'),
                    highlightHint: flowStatus?.highlightHint || '',
                });
                if (uiReport) {
                    setAnalysisUiReport({
                        ...uiReport,
                        status: String(uiReport.status || '').trim().toLowerCase() === 'failed'
                            ? uiReport.status
                            : display.displayPhase,
                        durationMs: Number(uiReport.durationMs || 0) > 0
                            ? Number(uiReport.durationMs)
                            : (startedAt > 0 ? Math.max(0, Date.now() - startedAt) : 0),
                    });
                }
            }
            setIsAnalyzing(false);
        }
        return true;
    }, [applyLiveAnalysisProgressSnapshot, beginAnalysisTimer, hasPersistableAnalysisProgress, setAnalysisFlowStatus, setAnalysisUiReport, t]);

    const dismissAnalysisProgressPanel = useCallback(() => {
        analysisProgressDismissedRef.current = true;
        latestIsAnalyzingRef.current = false;
        setIsAnalyzing(false);
        setIsRetryingPhase2(false);
        setActiveAnalysisTaskId('');
        setAnalysisFlowStatus({ phase: 'idle', message: '' });
        setAnalysisFlowStatusHistory([]);
        setAnalysisDetailLogs([]);
        setAnalysisUiReport(null);
        setAnalysisReviewIssues([]);
        if (activeEpisode?.id) {
            clearEpisodeAnalysisProgress(activeEpisode.id);
            clearEpisodeAnalysisDetached(activeEpisode.id);
            persistAnalysisSessionSnapshot(activeEpisode.id);
        }
    }, [activeEpisode?.id, persistAnalysisSessionSnapshot, setAnalysisDetailLogs, setAnalysisFlowStatus, setAnalysisFlowStatusHistory, setAnalysisUiReport]);

    useEffect(() => {
        if (!activeEpisode?.id || analysisProgressDismissedRef.current) return;
        if (!hasPersistableAnalysisProgress(analysisFlowStatus, analysisFlowStatusHistory, analysisUiReport)) return;
        const timer = setTimeout(() => {
            persistAnalysisSessionSnapshot(activeEpisode.id);
        }, 400);
        return () => clearTimeout(timer);
    }, [
        activeEpisode?.id,
        analysisFlowStatus,
        analysisFlowStatusHistory,
        analysisDetailLogs,
        analysisUiReport,
        hasPersistableAnalysisProgress,
        persistAnalysisSessionSnapshot,
    ]);

    const getAnalysisTaskStorageKey = useCallback((episodeId) => {
        if (!episodeId) return '';
        return `aistory:scene-analysis-task:${episodeId}`;
    }, []);

    const normalizeAnalysisTaskMarkerPhase = useCallback((phase) => {
        const raw = phase;
        if (raw === 'scene_beats' || raw === 'script_opt' || raw === 'assets_gen') return raw;
        const asText = String(raw ?? '').trim().toLowerCase();
        if (asText === 'scene_beats' || asText === 'script_opt' || asText === 'assets_gen') return asText;
        const asNum = Number(raw);
        if (Number.isFinite(asNum) && asNum > 0) return asNum;
        return 1;
    }, []);

    const loadAnalysisTaskMarker = useCallback((episodeId) => {
        try {
            const key = getAnalysisTaskStorageKey(episodeId);
            if (!key || !window?.localStorage) return null;
            const raw = window.localStorage.getItem(key);
            if (!raw) return null;
            const parsed = JSON.parse(raw);
            const taskId = String(parsed?.taskId || '').trim();
            const taskIds = Array.isArray(parsed?.taskIds)
                ? Array.from(new Set(parsed.taskIds.map((item) => String(item || '').trim()).filter(Boolean)))
                : [];
            const startedAt = Number(parsed?.startedAt || 0);
            const phase = normalizeAnalysisTaskMarkerPhase(parsed?.phase);
            if (!taskId) return null;
            if (!Number.isFinite(startedAt) || startedAt <= 0) return { taskId, taskIds: taskIds.length ? taskIds : [taskId], startedAt: Date.now(), phase };
            // Align marker TTL with task polling timeout to avoid endless resume loops after reload.
            if ((Date.now() - startedAt) > ANALYSIS_TASK_MARKER_TTL_MS) {
                window.localStorage.removeItem(key);
                return null;
            }
            return { taskId, taskIds: taskIds.length ? taskIds : [taskId], startedAt, phase };
        } catch (_) {
            return null;
        }
    }, [ANALYSIS_TASK_MARKER_TTL_MS, getAnalysisTaskStorageKey, normalizeAnalysisTaskMarkerPhase]);

    const saveAnalysisTaskMarker = useCallback((episodeId, marker) => {
        try {
            const key = getAnalysisTaskStorageKey(episodeId);
            if (!key || !window?.localStorage) return;
            const taskId = String(marker?.taskId || '').trim();
            if (!taskId) return;
            let existingTaskIds = [];
            try {
                const existing = JSON.parse(window.localStorage.getItem(key) || '{}');
                existingTaskIds = Array.isArray(existing?.taskIds)
                    ? existing.taskIds.map((item) => String(item || '').trim()).filter(Boolean)
                    : [];
                if (existing?.taskId) existingTaskIds.push(String(existing.taskId || '').trim());
            } catch (_) {
                existingTaskIds = [];
            }
            const taskIds = Array.from(new Set([
                ...existingTaskIds,
                ...Array.from(activeAnalysisTaskIdsRef.current || []),
                taskId,
            ].filter(Boolean)));
            const payload = {
                taskId,
                taskIds,
                startedAt: Number(marker?.startedAt || Date.now()),
                // Preserve string phases like scene_beats (Number('scene_beats') === NaN → null in JSON).
                phase: normalizeAnalysisTaskMarkerPhase(marker?.phase),
            };
            window.localStorage.setItem(key, JSON.stringify(payload));
            registerActiveAnalysisTask(taskId);
        } catch (_) {
            // Ignore localStorage failures.
        }
    }, [getAnalysisTaskStorageKey, normalizeAnalysisTaskMarkerPhase, registerActiveAnalysisTask]);

    const clearAnalysisTaskMarker = useCallback((episodeId) => {
        try {
            const key = getAnalysisTaskStorageKey(episodeId);
            if (!key || !window?.localStorage) return;
            window.localStorage.removeItem(key);
            activeAnalysisTaskIdsRef.current.clear();
            setActiveAnalysisTaskId('');
        } catch (_) {
            // Ignore localStorage failures.
        }
    }, [getAnalysisTaskStorageKey]);

    const clearStalePhase2AssetMarkerIfDesignExists = useCallback((episodeId, reason = '') => {
        const id = Number(episodeId || 0);
        if (!id) return false;
        const marker = loadAnalysisTaskMarker(id);
        if (!marker?.taskId || Number(marker?.phase) !== 2) return false;

        const designText = String(
            llmAssetRawResultContent
            || activeEpisode?.ai_entity_design_result
            || ''
        ).trim();
        if (!hasPersistedEntityDesignPayload(designText)) return false;

        clearAnalysisTaskMarker(id);
        if (reason && onLog) {
            onLog?.(`[Stage 3 Asset Design] Cleared stale phase-2 marker (${reason}); entity design result already present.`, 'info');
        }
        return true;
    }, [activeEpisode?.ai_entity_design_result, clearAnalysisTaskMarker, llmAssetRawResultContent, loadAnalysisTaskMarker, onLog]);

    const clearStaleAnalysisMarkerIfEpisodeComplete = useCallback(async (episodeId, episode, reason = '') => {
        const id = Number(episodeId || 0);
        if (!id) return false;
        const marker = loadAnalysisTaskMarker(id);
        if (!marker?.taskId) return false;

        const phaseRaw = marker?.phase;
        const phaseKey = String(phaseRaw ?? '1').trim().toLowerCase();
        const episodeRow = episode || (Number(activeEpisode?.id) === id ? activeEpisode : null);

        if (Number(phaseRaw) === 2 || phaseKey === '2') {
            return clearStalePhase2AssetMarkerIfDesignExists(id, reason);
        }

        const scenes = await fetchScenes(id).catch(() => []);
        const sceneCount = Array.isArray(scenes) ? scenes.length : 0;
        const hasSceneMarkdownByScene = (() => {
            try {
                const stageOutputs = JSON.parse(String(episodeRow?.ai_stage_outputs || '').trim() || '{}');
                const raw = String(stageOutputs?.stages?.stage2?.outputs?.scene_markdown_by_scene?.content || '').trim();
                if (!raw) return false;
                const parsed = JSON.parse(raw);
                return parsed && typeof parsed === 'object'
                    && Object.values(parsed).some((entry) => String(entry?.markdown || '').trim());
            } catch (_) {
                return false;
            }
        })();
        const hasSceneMarkdown = Boolean(
            hasSceneMarkdownByScene || String(episodeRow?.ai_scene_analysis_scene_markdown || '').trim()
        );
        const hasSceneResult = Boolean(
            hasSceneMarkdown || String(episodeRow?.ai_scene_analysis_result || '').trim()
        );
        const hasSubjectIndex = Boolean(String(episodeRow?.ai_scene_analysis_subject_index || '').trim());
        const hasEntityDesign = hasPersistedEntityDesignPayload(episodeRow?.ai_entity_design_result);

        if (phaseKey === 'scene_beats') {
            if (hasSceneMarkdown && sceneCount > 0) {
                clearAnalysisTaskMarker(id);
                if (reason && onLog) {
                    onLog?.(`[Analysis Resume] Cleared stale scene_beats marker (${reason}); scene markdown and DB scenes already present.`, 'info');
                }
                return true;
            }
            return false;
        }

        if (sceneCount > 0 && hasSceneResult && (hasSubjectIndex || hasEntityDesign)) {
            clearAnalysisTaskMarker(id);
            if (reason && onLog) {
                onLog?.(`[Analysis Resume] Cleared stale analysis marker (${reason}); episode already has ${sceneCount} imported scene(s).`, 'info');
            }
            return true;
        }

        return false;
    }, [activeEpisode, clearAnalysisTaskMarker, clearStalePhase2AssetMarkerIfDesignExists, fetchScenes, loadAnalysisTaskMarker, onLog]);

    const bootstrapPendingAnalysisUi = useCallback(() => {
        if (!activeEpisode?.id) return false;

        const activeRun = getEpisodeAnalysisRun(activeEpisode.id);
        const marker = loadAnalysisTaskMarker(activeEpisode.id);
        if (!activeRun?.promise && !marker?.taskId) return false;

        // Never re-arm the analyzing CTA when the restored/current panel is already terminal.
        if (isEpisodeAnalysisUserStopRequested(activeEpisode.id, {
            localStopRequested: analysisStopRequestedRef.current,
            localStopReason: analysisStopReasonRef.current,
        })) {
            return false;
        }
        const ui = latestAnalysisProgressUiRef.current || {};
        const uiPhase = String(ui?.flowStatus?.phase || '').trim().toLowerCase();
        const uiReportStatus = String(ui?.uiReport?.status || '').trim().toLowerCase();
        if (
            ['completed', 'warning', 'failed'].includes(uiPhase)
            || ['completed', 'warning', 'failed', 'error'].includes(uiReportStatus)
        ) {
            return false;
        }

        const phase = activeRun?.phase ?? marker?.phase ?? 1;
        const startedAt = Number(activeRun?.startedAt || marker?.startedAt || Date.now());
        const elapsedMs = Math.max(0, Date.now() - startedAt);
        const taskId = String(activeRun?.taskId || marker?.taskId || '').trim();
        const resolvedPhase = phase === 2 ? 'assets_gen' : (phase === 'scene_beats' ? 'scene_beats' : 'script_opt');

        beginAnalysisTimer(startedAt);
        setIsAnalyzing(true);
        if (taskId) setActiveAnalysisTaskId(taskId);
        setAnalysisFlowStatus((prev) => {
            const prevPhase = String(prev?.phase || '').trim().toLowerCase();
            if (prevPhase && prevPhase !== 'idle') return prev;
            return {
                phase: resolvedPhase,
                message: t('后台分析任务进行中，正在恢复进度监控...', 'Background analysis task in progress; restoring progress monitoring...'),
            };
        });
        setAnalysisUiReport((prev) => {
            if (prev?.status === 'running') {
                return { ...prev, durationMs: elapsedMs, warning: '', error: '' };
            }
            return {
                status: 'running',
                startedAt,
                durationMs: elapsedMs,
                phaseTimings: null,
                importReport: null,
                runtimeMeta: null,
                warning: '',
                error: '',
            };
        });
        return true;
    }, [activeEpisode?.id, beginAnalysisTimer, loadAnalysisTaskMarker, t]);

    const isRecoverableAnalysisError = useCallback((error) => {
        if (!error || isTaskCanceledError(error)) return false;
        const code = String(error?.code || '').toUpperCase();
        const msg = String(error?.message || '').toLowerCase();
        if (code === 'ECONNABORTED') return true;
        if (!error?.response) return true;
        return (
            msg.includes('network error')
            || msg.includes('no response')
            || msg.includes('submit/poll no response')
            || msg.includes('timed out while waiting')
            || msg.includes('task polling timed out')
            || msg.includes('llm task polling timed out')
        );
    }, [isTaskCanceledError]);

    const shouldRetainAnalysisTaskMarker = useCallback(({ pipelineFinished = false, canceled = false, error = null, mounted = true } = {}) => {
        if (pipelineFinished || canceled) return false;
        if (!mounted) return true;
        return isRecoverableAnalysisError(error);
    }, [isRecoverableAnalysisError]);

    const canStopAnalysisTask = useMemo(() => {
        if (isStoppingAnalysisTask) return true;
        const userStopped = isEpisodeAnalysisUserStopRequested(activeEpisode?.id, {
            localStopRequested: analysisStopRequestedRef.current,
            localStopReason: analysisStopReasonRef.current,
        });
        if (userStopped) return false;
        if (isAnalyzing || isRetryingPhase2 || isRerunningStoryboard) return true;
        if (analysisProgressDisplay.isLive) return true;
        if (String(activeAnalysisTaskId || '').trim()) return true;
        if (loadAnalysisTaskMarker(activeEpisode?.id)?.taskId) return true;
        if (hasInFlightPipelineNodes(diagnosticsPipelineNodes)) return true;
        return isEpisodeAnalysisTaskLive(activeEpisode?.id, {
            loadAnalysisTaskMarker,
            isAnalyzing,
            isRetryingPhase2,
            analysisRunInFlight: analysisRunInFlightRef.current,
            analysisResumeInFlight: analysisResumeInFlightRef.current,
            phase2GenerationInFlight: phase2GenerationInFlightRef.current,
            analysisEntryLock: analysisEntryLockRef.current,
        });
    }, [
        activeAnalysisTaskId,
        activeEpisode?.id,
        analysisProgressDisplay.isLive,
        diagnosticsPipelineNodes,
        isAnalyzing,
        isRetryingPhase2,
        isRerunningStoryboard,
        isStoppingAnalysisTask,
        loadAnalysisTaskMarker,
    ]);

    const clearLocalAnalysisRunningStateAfterUserStop = useCallback((episodeId, {
        message = '',
    } = {}) => {
        const id = Number(episodeId || activeEpisode?.id || 0);
        const stopMessage = String(message || '').trim()
            || t('已请求停止当前剧本分析任务。', 'Stop requested for the current scene analysis task.');

        analysisStopRequestedRef.current = true;
        analysisStopReasonRef.current = 'user';
        analysisAwaitingStoryboardRef.current = false;
        analysisPipelineSupervisorActiveRef.current = false;
        analysisRunInFlightRef.current = false;
        analysisResumeInFlightRef.current = false;
        analysisEntryLockRef.current = false;
        phase2GenerationInFlightRef.current = false;
        sceneBeatsOnlyRerunInFlightRef.current = false;
        latestIsAnalyzingRef.current = false;
        analysisResumeCoordinatorRef.current = { running: false, episodeId: null };
        phase2InFlightCategoriesRef.current = new Set();
        activeAnalysisTaskIdsRef.current = new Set();
        storyboardKickoffByMarkerRef.current = new Set();
        storyboardKickoffByIdentityRef.current = new Set();
        storyboardKickoffByDbIdRef.current = new Set();
        storyboardKickoffPromisesRef.current = new Map();
        pendingStoryboardKickoffsRef.current = [];
        storyboardTaskProgressRef.current = EMPTY_STORYBOARD_TASK_PROGRESS;
        clearAnalysisPipelineDeadline();

        if (id) {
            requestEpisodeAnalysisPipelineStop(id, 'user');
            releaseEpisodeAnalysisClaim(id);
            releaseEpisodeAnalysisRun(id);
            analysisClaimTokenRef.current = '';
            clearAnalysisTaskMarker(id);
            clearEpisodeAnalysisDetached(id);
        }

        setIsAnalyzing(false);
        setIsRetryingPhase2(false);
        setRetryingAssetCategoryKeys([]);
        setIsRerunningStoryboard(false);
        setActiveAnalysisTaskId('');
        setAnalysisFlowStatus({
            phase: 'warning',
            message: stopMessage,
        });
        const startedAt = Number(
            analysisUiReportRef.current?.startedAt
            || analysisTimerStartedAtRef.current
            || 0
        );
        const nextReport = {
            ...(analysisUiReportRef.current && typeof analysisUiReportRef.current === 'object'
                ? analysisUiReportRef.current
                : {}),
            status: 'warning',
            warning: stopMessage,
            error: '',
            durationMs: startedAt > 0
                ? Math.max(0, Date.now() - startedAt)
                : Number(analysisUiReportRef.current?.durationMs || 0) || 0,
            storyboardTaskProgress: EMPTY_STORYBOARD_TASK_PROGRESS,
        };
        setStoryboardTaskProgress(EMPTY_STORYBOARD_TASK_PROGRESS);
        setAnalysisUiReport(nextReport);
        setAnalysisFlowStatusHistory((prev) => {
            if (!Array.isArray(prev) || prev.length === 0) return prev;
            const now = Date.now();
            return prev.map((item) => (
                hasAnalysisHistoryEndedAt(item) ? item : { ...item, endedAt: now }
            ));
        });

        const canceledNodes = markPipelineNodesCanceledLocally(diagnosticsPipelineNodesRef.current);
        diagnosticsPipelineNodesRef.current = canceledNodes;
        setDiagnosticsPipelineNodes(canceledNodes);

        if (id) {
            publishEpisodeAnalysisProgress(id, {
                isAnalyzing: false,
                flowStatus: { phase: 'warning', message: stopMessage },
                uiReport: nextReport,
                pipelineNodes: canceledNodes,
            });
        }
    }, [
        activeEpisode?.id,
        clearAnalysisPipelineDeadline,
        clearAnalysisTaskMarker,
        setAnalysisFlowStatus,
        setAnalysisFlowStatusHistory,
        setAnalysisUiReport,
        setIsRerunningStoryboard,
        setStoryboardTaskProgress,
        t,
    ]);

    const handleStopAnalysisTask = useCallback(async () => {
        if (!activeEpisode?.id) return;
        const marker = loadAnalysisTaskMarker(activeEpisode.id);
        const taskIds = Array.from(new Set([
            ...Array.from(activeAnalysisTaskIdsRef.current || []),
            String(activeAnalysisTaskId || '').trim(),
            String(marker?.taskId || '').trim(),
            ...(Array.isArray(marker?.taskIds) ? marker.taskIds.map((item) => String(item || '').trim()) : []),
        ].filter(Boolean)));
        const hasLocalRun = Boolean(
            isAnalyzing
            || isRetryingPhase2
            || isRerunningStoryboard
            || analysisProgressDisplay.isLive
            || phase2GenerationInFlightRef.current
            || analysisRunInFlightRef.current
            || analysisResumeInFlightRef.current
            || analysisEntryLockRef.current
            || sceneBeatsOnlyRerunInFlightRef.current
            || (storyboardKickoffPromisesRef.current?.size || 0) > 0
            || getEpisodeAnalysisRun(activeEpisode.id)?.promise
            || isEpisodeAnalysisClaimed(activeEpisode.id)
        );
        if (taskIds.length <= 0 && !hasLocalRun) {
            setAnalysisFlowStatus({
                phase: 'warning',
                message: t('当前没有正在运行的场景推演任务需要被终止。', 'No running analysis task found to stop.'),
            });
            return;
        }

        setIsStoppingAnalysisTask(true);
        const stopMessage = taskIds.length <= 0
            ? t('已请求停止当前剧本分析流程。', 'Stop requested for the current script analysis flow.')
            : t('已请求停止当前剧本分析任务。', 'Stop requested for the current scene analysis task.');
        clearLocalAnalysisRunningStateAfterUserStop(activeEpisode.id, { message: stopMessage });
        if (taskIds.length <= 0) {
            if (onLog) onLog('Scene analysis stop requested before backend task id was available.', 'warning');
            setIsStoppingAnalysisTask(false);
            return;
        }
        try {
            const stopResults = await Promise.allSettled(taskIds.map((taskId) => stopAsyncTask(taskId)));
            const failedStops = stopResults.filter((item) => item.status === 'rejected');
            const confirmedMessage = failedStops.length > 0
                ? t(`已请求停止当前剧本分析任务；${failedStops.length} 个子任务停止请求未确认。`, `Stop requested for the current script analysis task; ${failedStops.length} subtask stop request(s) were not confirmed.`)
                : stopMessage;
            setAnalysisFlowStatus({
                phase: 'warning',
                message: confirmedMessage,
            });
            if (onLog) onLog(`Scene analysis stop requested: task_ids=${taskIds.join(',')}`, failedStops.length > 0 ? 'warning' : 'info');
        } catch (e) {
            setAnalysisFlowStatus({
                phase: 'warning',
                message: t(`停止任务失败：${e?.message || e}`, `Failed to stop task: ${e?.message || e}`),
            });
            if (onLog) onLog(`Failed to stop scene analysis task: ${e?.message || e}`, 'error');
        } finally {
            setIsStoppingAnalysisTask(false);
            latestIsAnalyzingRef.current = false;
            setIsAnalyzing(false);
            setIsRetryingPhase2(false);
            setIsRerunningStoryboard(false);
        }
    }, [
        activeAnalysisTaskId,
        activeEpisode?.id,
        analysisProgressDisplay.isLive,
        clearLocalAnalysisRunningStateAfterUserStop,
        isAnalyzing,
        isRetryingPhase2,
        isRerunningStoryboard,
        loadAnalysisTaskMarker,
        onLog,
        t,
    ]);
    const refreshAnalysisFromDB = useCallback(async ({ resultField = 'ai_scene_analysis_result' } = {}) => {
        const episodeId = Number(activeEpisode?.id || 0);
        if (!episodeId) return;
        try {
            const fresh = await fetchEpisode(episodeId);
            const dbText = String((fresh && fresh[resultField]) || '');

            // Only update if user hasn't diverged from last loaded content.
            if (resultField === 'ai_entity_design_result') {
                const current = llmAssetRawResultContent || '';
                if (dbText && dbText !== current) {
                    setLlmAssetRawResultContent(dbText);
                }
            } else {
                const current = llmRawResultContent || '';
                const lastLoaded = lastLoadedAnalysisRef.current;
                const userHasEdited = lastLoaded !== null && current !== lastLoaded;

                if (!userHasEdited) {
                    if (dbText && dbText !== current) {
                        setLlmRawResultContent(dbText);
                        setLlmResultContent(normalizeLlmMarkdownTable(dbText));
                    }
                    lastLoadedAnalysisRef.current = dbText;
                }
            }
        } catch (e) {
            // non-fatal
            console.warn('[ScriptEditor] Failed to refresh analysis from DB', e);
        }
    }, [activeEpisode?.id, llmAssetRawResultContent, llmRawResultContent, normalizeLlmMarkdownTable]);

    const refreshAnalysisFromDBRef = useRef(refreshAnalysisFromDB);
    refreshAnalysisFromDBRef.current = refreshAnalysisFromDB;

    const waitForEpisodeAnalysisResultUpdate = useCallback(async ({ baselineText = '', timeoutMs = 600000, intervalMs = 3500, resultField = 'ai_scene_analysis_result', expectedResultKind = '' } = {}) => {
        const sleepMs = Math.max(5000, Number(intervalMs || 3500));
        const episodeId = Number(activeEpisode?.id || 0);
        if (!episodeId) {
            await new Promise(r => setTimeout(r, sleepMs));
            return '';
        }
        if (resultField === 'none') {
            await new Promise(r => setTimeout(r, sleepMs));
            return '';
        }
        const base = String(baselineText || '').trim();
        const deadline = Date.now() + Math.max(30000, Number(timeoutMs || 600000));

        while (Date.now() < deadline) {
            try {
                const fresh = await fetchEpisode(episodeId);
                const dbText = String((fresh && fresh[resultField]) || '').trim();
                
                const expectedKind = String(expectedResultKind || '').trim().toLowerCase();
                const hasSceneBeatsMarker = Boolean(normalizeLlmMarkdownTable(dbText));
                const hasSubjectIndexMarker = /###?\s*Subject\s*Index/i.test(dbText) || /subject_no\s*=\s*/i.test(dbText) || /\|\s*subject_no\s*\|\s*subject_type\s*\|/i.test(dbText);
                const hasAssetDesignMarker = /"characters"\s*:/i.test(dbText) || /"props"\s*:/i.test(dbText) || /"environments"\s*:/i.test(dbText) || /"posters"\s*:/i.test(dbText) || /"covers"\s*:/i.test(dbText);
                const hasValidMarker = resultField === 'ai_scene_analysis_result'
                    ? (expectedKind === 'scene_beats' ? hasSceneBeatsMarker : (hasSceneBeatsMarker || hasSubjectIndexMarker))
                    : (resultField === 'ai_entity_design_result' ? hasAssetDesignMarker : Boolean(dbText));

                if (dbText && dbText !== base && hasValidMarker) {
                    return dbText;
                }
            } catch (_) {
                // Non-fatal polling fallback; keep waiting.
            }
            await new Promise(resolve => setTimeout(resolve, sleepMs));
        }
        return '';
    }, [activeEpisode?.id, normalizeLlmMarkdownTable]);

    const ANALYSIS_EPISODE_RECOVERY_PROBE_MS = 30000;

    const awaitAnalyzeSceneWithRecovery = useCallback(async (invokeAnalyze, { startedAt = Date.now(), baselineText = '', resultField = 'ai_scene_analysis_result', expectedResultKind = '', disableEpisodeRecovery = false } = {}) => {
        throwIfAnalysisStopped();
        if (disableEpisodeRecovery) {
            const value = await invokeAnalyze();
            throwIfAnalysisStopped();
            return value;
        }
        let settled = false;
        let resolvedValue = null;
        let resolvedError = null;

        const analyzePromise = Promise.resolve()
            .then(() => invokeAnalyze())
            .then((value) => {
                settled = true;
                resolvedValue = value;
            })
            .catch((err) => {
                settled = true;
                resolvedError = err;
            });

        const deadline = Date.now() + 60 * 60 * 1000;
        while (!settled && Date.now() < deadline) {
            throwIfAnalysisStopped();
            // Wake immediately when the request settles. The recovery timer is only a
            // fallback probe interval; it must not add up to 30 seconds between DAG nodes.
            await Promise.race([
                analyzePromise,
                new Promise((resolve) => setTimeout(resolve, ANALYSIS_EPISODE_RECOVERY_PROBE_MS)),
            ]);
            if (settled) break;
            const recoveredText = await waitForEpisodeAnalysisResultUpdate({
                baselineText,
                timeoutMs: 15000,
                intervalMs: 6000,
                resultField,
                expectedResultKind,
            });
            if (recoveredText) {
                if (onLog) {
                    onLog('Recovered AI Script Analysis result from episode storage while async task polling was delayed.', 'warning');
                }
                return {
                    success: true,
                    result: recoveredText,
                    meta: {
                        saved_to_episode: true,
                        recovered_from_episode_poll: true,
                    },
                    warnings: [t('后端任务轮询延迟，已从分集已保存结果继续流程。', 'Task polling lag detected; continued using episode-saved analysis result.')],
                    warning_codes: ['ANALYSIS_TASK_POLLING_LAG_RECOVERED'],
                };
            }
        }

        if (!settled) {
            throw new Error('AI Script Analysis timed out while waiting for async task result (resume deadline reached).');
        }
        await analyzePromise;
        throwIfAnalysisStopped();
        if (resolvedError) throw resolvedError;
        if (settled) return resolvedValue;
        throw new Error('AI Script Analysis timed out while waiting for async task result.');
    }, [onLog, t, throwIfAnalysisStopped, waitForEpisodeAnalysisResultUpdate]);

    const selectedReuseSubjectAssets = useMemo(() => {
        if (!Array.isArray(availableSubjectAssets) || availableSubjectAssets.length === 0) return [];
        const selected = new Set((selectedReuseSubjectIds || []).map(v => String(v)));
        return availableSubjectAssets
            .filter((asset) => {
                if (!selected.has(String(asset.id))) return false;
                if (isEnvironmentAssetType(asset?.type) && !isReusableMainEnvironmentAsset(asset)) {
                    return false;
                }
                return true;
            })
            .map(asset => ({
                id: asset.id,
                name: asset.name || '',
                type: asset.type || '',
                description: asset.description || asset.narrative_description || '',
                anchor_description: asset.anchor_description || '',
            }));
    }, [activeEpisode?.id, availableSubjectAssets, selectedReuseSubjectIds]);

    const runScriptOptimizationNode = useCallback(async ({
        scriptText,
        systemPrompt,
        metadata = null,
        startedAt = Date.now(),
        baselineText = '',
        disableEpisodeRecovery = false,
        includeEnvironmentPlan = true,
        onTaskCreated,
    } = {}) => {
        const cutPromptRes = await fetchPrompt(
            'skills/scene_analysis_feature_stack/scene_planning_1_subskill_cut_transition.md'
        );
        const cutResult = await awaitAnalyzeSceneWithRecovery(
            () => runScriptAnalysisFlowAnalyzeNode(
                'scene_split',
                scriptText,
                cutPromptRes?.content || systemPrompt,
                metadata,
                activeEpisode?.id || null,
                analysisAttentionNotes,
                selectedReuseSubjectAssets,
                {
                    onTaskCreated,
                },
                projectId,
                'script_analysis',
                resolveSelectedScriptAnalysisApiId()
            ),
            { startedAt, baselineText, disableEpisodeRecovery: true }
        );
        const cutText = String(extractAnalysisTextFromResult(cutResult) || '').trim();
        if (!cutText) {
            throw new Error(t(
                '全局统筹子技能未返回内容。',
                'The global-orchestration subskill returned no content.'
            ));
        }

        if (!includeEnvironmentPlan) {
            return cutResult;
        }

        const environmentPromptRes = await fetchPrompt(
            'skills/scene_analysis_feature_stack/scene_planning_1_subskill_environment.md'
        );
        return awaitAnalyzeSceneWithRecovery(
            () => runScriptAnalysisFlowAnalyzeNode(
                'environment_plan',
                cutText,
                environmentPromptRes?.content || '',
                metadata,
                activeEpisode?.id || null,
                analysisAttentionNotes,
                selectedReuseSubjectAssets,
                {
                    onTaskCreated,
                },
                projectId,
                'script_analysis',
                resolveSelectedScriptAnalysisApiId()
            ),
            { startedAt, baselineText: cutText, disableEpisodeRecovery }
        );
    }, [
        activeEpisode?.id,
        analysisAttentionNotes,
        awaitAnalyzeSceneWithRecovery,
        projectId,
        resolveSelectedScriptAnalysisApiId,
        selectedReuseSubjectAssets,
    ]);

    const runStage2_2WithValidationRetry = useCallback(async ({
        label = 'Stage 2.2',
        logPhasePrefix = 'advanced',
        finalStage2_2UserInput,
        stage2_2UserInputBody = '',
        stage2_1SubjectIndexText = '',
        stage1SourceText = '',
        startedAt,
        baselineText = '',
        functionName = 'script_analysis',
        sceneAnalysisModePayload = null,
        targetSceneUnits = null,
        // Full pipeline: skip LLM for scenes already present in workspace.
        // Manual scene-beats rerun must pass false.
        skipExistingScenes = true,
        maxValidationRetries = MAX_ANALYSIS_FALLBACK_ATTEMPTS,
        onTaskCreated,
    }) => {
        const stage2_2PromptRes = await fetchPrompt('skills/scene_analysis_feature_stack/_archive/2026-09-05-retired/scene_planning_2_2_beats_generation.md');
        const finalStage2_2Prompt = stage2_2PromptRes?.content || '';
        const scriptAnalysisApiId = resolveSelectedScriptAnalysisApiId();
        if (scriptAnalysisApiId) {
            onLog?.(`[${label}] 使用剧本分析 API 选择：system_api_id=${scriptAnalysisApiId}`, 'info');
        }
        let lastError = '';
        const validationRetryLimit = Math.max(
            0,
            Math.min(MAX_ANALYSIS_FALLBACK_ATTEMPTS, Number(maxValidationRetries) || 0)
        );

        const adaptedScriptForSplit = extractAdaptedScriptFromStage2_2UserInputBody(stage2_2UserInputBody || finalStage2_2UserInput);
        if (!String(adaptedScriptForSplit || '').trim()) {
            throw new Error(t(
                '缺少优化后剧本，无法执行场景编排。请确认第一阶段已生成改编剧本后再重试。',
                'Missing adapted script for scene beats orchestration. Complete Stage 1 script optimization first.'
            ));
        }
        const subjectIndexForStage2_2 = String(
            extractPureSubjectIndexText(latestStage2_1TextRef.current || stage2_1SubjectIndexText || '')
            || latestStage2_1TextRef.current
            || stage2_1SubjectIndexText
            || ''
        ).trim();
        if (!subjectIndexForStage2_2 || !hasSubjectIndexStructure(subjectIndexForStage2_2)) {
            throw new Error(t(
                '缺少资产清单，无法执行场景编排。请先完成资产清单后再重试。',
                'Asset inventory is missing. Finish the asset inventory step before scene orchestration.'
            ));
        }
        let sceneUnits = [];
        try {
            sceneUnits = parseSceneUnitsFromScriptMarkers(adaptedScriptForSplit);
        } catch (parseErr) {
            // Do not collapse multi-scene scripts into a single fallback scene.
            throw new Error(t(
                `场景分割符解析失败，无法执行场景编排：${parseErr?.message || parseErr}`,
                `Scene marker parse failed; cannot run scene orchestration: ${parseErr?.message || parseErr}`
            ));
        }
        if (!sceneUnits.length) {
            throw new Error(t(
                '场景分割结果为空，请检查优化后剧本中的 [SCENE_START:ID]/[SCENE_END:ID] 配对。',
                'Scene split returned no units. Check [SCENE_START:ID]/[SCENE_END:ID] pairs in the adapted script.'
            ));
        }
        const episodePrefix = resolveEpisodeSceneIdPrefix(
            activeEpisode,
            adaptedScriptForSplit || extractStage1AdaptedScriptBody(stage1SourceText)
        );
        sceneUnits = applyCanonicalSceneIdsToUnits(sceneUnits, episodePrefix);

        const subjectIndexSection = buildStage2_2SubjectIndexSection(subjectIndexForStage2_2);
        const attachSubjectIndex = (text) => {
            const body = String(text || '');
            if (!subjectIndexSection) return body;
            if (!body) return subjectIndexSection;
            if (body.includes('[Subject Index开始]') || /\[Stage\s*2[\-_]\s*1\s+Subject\s*Index/i.test(body)) {
                return body;
            }
            return `${subjectIndexSection}\n\n${body}`;
        };

        const runSingleStage2_2Attempt = async ({
            attemptLabel,
            attemptUserInputBody,
            attemptFinalUserInput,
            fallbackAttempt = 0,
            disableEpisodeRecovery = false,
            targetSceneIds = null,
        }) => {
            const attachedUserInputBody = attachSubjectIndex(attemptUserInputBody);
            const attachedFinalUserInput = attachSubjectIndex(attemptFinalUserInput);
            const normalizedTargetSceneIds = (
                Array.isArray(targetSceneIds) ? targetSceneIds : []
            )
                .map((sceneId) => String(sceneId || '').trim())
                .filter(Boolean);
            logStage2_2Diagnostics({
                phase: `${logPhasePrefix}-stage2_2-submit`,
                subjectIndexText: subjectIndexForStage2_2,
                sceneInputText: attachedUserInputBody,
                finalInputText: attachedFinalUserInput,
            });

            const stage2_2ResultObj = await awaitAnalyzeSceneWithRecovery(
                () => runScriptAnalysisFlowAnalyzeNode(
                    'scene_markdown',
                    attachedFinalUserInput,
                    finalStage2_2Prompt,
                    null,
                    activeEpisode?.id || null,
                    analysisAttentionNotes,
                    selectedReuseSubjectAssets,
                    {
                        subjectIndexText: subjectIndexForStage2_2,
                        targetSceneIds: normalizedTargetSceneIds,
                        onTaskCreated: (taskId) => {
                            const stableTaskId = String(taskId || '').trim();
                            if (stableTaskId) {
                                onLog?.(
                                    t(
                                        `[${attemptLabel}] 异步任务已创建 task_id=${stableTaskId}`,
                                        `[${attemptLabel}] Async task created task_id=${stableTaskId}`
                                    ),
                                    'info'
                                );
                            }
                            onTaskCreated?.(taskId);
                        },
                    },
                    projectId,
                    functionName,
                    scriptAnalysisApiId,
                    sceneAnalysisModePayload
                ),
                {
                    startedAt,
                    baselineText,
                    resultField: 'ai_scene_analysis_scene_markdown',
                    expectedResultKind: 'scene_beats',
                    disableEpisodeRecovery,
                }
            );

            if (disableEpisodeRecovery && stage2_2ResultObj?.meta?.recovered_from_episode_poll) {
                throw new Error(t(
                    '场景编排仍在进行中，拒绝使用分集缓存结果。',
                    'Scene beats orchestration is still running; refused to use cached episode result.'
                ));
            }

            const text2_2 = extractAnalysisTextFromResult(stage2_2ResultObj) || '';
            let isUpstreamError2 = false;
            let errMsg2 = '';
            const matchObjStr2 = text2_2.trim().replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '');
            if (matchObjStr2.startsWith('{')) {
                try {
                    const parseObj = JSON.parse(matchObjStr2);
                    if (parseObj.code === 500 || parseObj.error || parseObj.msg) {
                        isUpstreamError2 = true;
                        errMsg2 = `上游接口异常 (${attemptLabel})：${parseObj.msg || parseObj.error?.message || matchObjStr2}`;
                    }
                } catch (_) {}
            }
            if (!isUpstreamError2 && /服务器错误|maintained|too many requests|rate limit/i.test(text2_2)) {
                isUpstreamError2 = true;
                errMsg2 = `上游接口熔断或系统维护 (${attemptLabel})：${text2_2.slice(0, 100)}`;
            }
            if (isUpstreamError2) {
                throw new Error(errMsg2);
            }

            const validationLabel = fallbackAttempt > 0 ? `${attemptLabel} retry ${fallbackAttempt}` : attemptLabel;
            const stage2_2Check = validateStage2_2BeatsOutput(text2_2, validationLabel);
            logStage2_2Diagnostics({
                phase: `${logPhasePrefix}-stage2_2-result`,
                subjectIndexText: subjectIndexForStage2_2,
                sceneInputText: attachedUserInputBody,
                finalInputText: attachedFinalUserInput,
                rawOutputText: text2_2,
                normalizedText: stage2_2Check?.normalizedText || '',
            });
            return { stage2_2Text: text2_2, stage2_2Result: stage2_2ResultObj, stage2_2Check };
        };

        const explicitSceneUnits = Array.isArray(targetSceneUnits)
            ? applyCanonicalSceneIdsToUnits(
                targetSceneUnits.filter((unit) => unit && String(unit.sceneId || '').trim()),
                episodePrefix
            )
            : [];
        let unitsToProcess = explicitSceneUnits.length > 0 ? explicitSceneUnits : sceneUnits;
        const incomingSceneIds = (unitsToProcess || [])
            .map((unit) => String(unit?.sceneId || '').trim())
            .filter(Boolean);
        // Streaming per-scene 2.2 wraps one scene, so explicit.length === parsed.length === 1.
        // That must MERGE into the run allowlist — replacing would drop sibling scenes and
        // skip their storyboard kickoff ("不在场景编排场次列表中").
        // Also treat a 1-scene launch as partial when siblings are already on the
        // allowlist / live-imported (parse-empty target list used to wipe them).
        const incomingDistinct = countDistinctScenesInAllowlist(
            expandSceneIdAllowlist(incomingSceneIds, episodePrefix)
        );
        const existingDistinct = countDistinctScenesInAllowlist(
            orchestrationCanonicalSceneIdsRef.current
        );
        const incomingAllowlist = expandSceneIdAllowlist(incomingSceneIds, episodePrefix);
        const liveImportedHasSiblings = [...(orchestrationLiveImportedScenesRef.current || [])]
            .some((id) => !isSceneIdInAllowlist(id, incomingAllowlist, episodePrefix));
        const isPartialLaunch = explicitSceneUnits.length > 0
            || (existingDistinct > incomingDistinct)
            || liveImportedHasSiblings;
        if (isPartialLaunch) {
            orchestrationCanonicalSceneIdsRef.current = mergeSceneIdAllowlist(
                orchestrationCanonicalSceneIdsRef.current,
                incomingSceneIds,
                episodePrefix
            );
        } else {
            orchestrationCanonicalSceneIdsRef.current = expandSceneIdAllowlist(
                incomingSceneIds,
                episodePrefix
            );
        }
        if (explicitSceneUnits.length > 0 && explicitSceneUnits.length !== sceneUnits.length) {
            onLog?.(
                t(
                    `[${label}] 使用显式场景列表 ${explicitSceneUnits.length} 场（从 Stage 2.2 输入解析到 ${sceneUnits.length} 场）`,
                    `[${label}] Using explicit scene list (${explicitSceneUnits.length} scenes; parsed ${sceneUnits.length} from Stage 2.2 input)`
                ),
                'info'
            );
        }

        // Reset kickoff/live-imported once BEFORE skipExisting may claim scenes + start storyboard.
        // Must not reset again after skipExisting kickoffs (would orphan in-flight LLM and allow purge).
        // Preserve env gate: scene orchestration runs in parallel with asset design, which may
        // already have marked environment/poster ready for this run.
        // Any explicit target list (streaming one-scene or subset rerun) must not wipe siblings.
        if (isPartialLaunch) {
            const targetMarkerSet = new Set(incomingSceneIds);
            const nextLiveImported = new Set();
            for (const sceneId of (orchestrationLiveImportedScenesRef.current || [])) {
                const stableId = String(sceneId || '').trim();
                if (stableId && !targetMarkerSet.has(stableId)) nextLiveImported.add(stableId);
            }
            orchestrationLiveImportedScenesRef.current = nextLiveImported;
            clearStoryboardTrackingForScenes([...targetMarkerSet]);
        } else {
            orchestrationLiveImportedScenesRef.current = new Set();
            resetStoryboardKickoffTracking({ preserveEnvGate: true });
        }

        // Full-pipeline precheck: do not re-orchestrate scenes already in the workspace DB.
        const shouldSkipExistingScenes = Boolean(skipExistingScenes)
            && String(sceneAnalysisModePayload || '').trim().toLowerCase() !== 'scene_beats_only';
        const skippedExistingSceneUnits = [];
        if (shouldSkipExistingScenes && activeEpisode?.id && unitsToProcess.length > 0) {
            const existingIds = await resolveExistingWorkspaceSceneIds({
                fetchScenesFn: fetchScenes,
                episodeId: activeEpisode.id,
                sceneIds: unitsToProcess.map((unit) => unit?.sceneId),
            });
            if (existingIds.size > 0) {
                const pending = [];
                for (const unit of unitsToProcess) {
                    const sceneId = String(unit?.sceneId || '').trim();
                    if (sceneId && existingIds.has(sceneId)) {
                        skippedExistingSceneUnits.push(unit);
                    } else {
                        pending.push(unit);
                    }
                }
                if (skippedExistingSceneUnits.length > 0) {
                    const skippedLabels = skippedExistingSceneUnits
                        .map((unit) => String(unit?.sceneId || '').trim())
                        .filter(Boolean);
                    onLog?.(
                        t(
                            `[${label}] 预查工作区：${skippedExistingSceneUnits.length} 场已入库，跳过场景编排 LLM（${skippedLabels.join('、')}）`,
                            `[${label}] Workspace precheck: skip orchestration LLM for ${skippedExistingSceneUnits.length} existing scene(s) (${skippedLabels.join(', ')})`
                        ),
                        'info'
                    );
                    beginSceneOrchestrationPanelTracking(
                        Math.max(unitsToProcess.length, skippedExistingSceneUnits.length + pending.length)
                    );
                    for (const unit of skippedExistingSceneUnits) {
                        const sceneId = String(unit?.sceneId || '').trim();
                        if (!sceneId) continue;
                        orchestrationLiveImportedScenesRef.current.add(sceneId);
                        publishSceneOrchestrationPanelStatus({
                            sceneId,
                            phase: 'imported',
                            sceneOrder: unit?.sceneOrder,
                            totalScenes: Math.max(unitsToProcess.length, skippedExistingSceneUnits.length + pending.length),
                        });
                        // Storyboard kickoff has its own per-scene shots precheck (!force).
                        await kickoffStoryboardForImportedScene({
                            markerSceneId: sceneId,
                            sceneOrder: unit?.sceneOrder || deriveSceneOrderFromSceneId(sceneId),
                            force: false,
                        });
                    }
                }
                unitsToProcess = pending;
            }
        }

        if (shouldSkipExistingScenes && skippedExistingSceneUnits.length > 0 && unitsToProcess.length <= 0) {
            onLog?.(
                t(
                    `[${label}] 全部场次已在工作区存在，跳过场景编排。`,
                    `[${label}] All scenes already exist in workspace; skipping scene orchestration.`
                ),
                'success'
            );
            let sceneMarkdownPatchMap = {};
            try {
                const rawJson = String(
                    parseStageOutputsObject(activeEpisode?.ai_stage_outputs || '')
                        ?.stages?.stage2?.outputs?.scene_markdown_by_scene?.content || ''
                ).trim();
                sceneMarkdownPatchMap = parseSceneMarkdownBySceneMap(rawJson) || {};
            } catch (_) {
                sceneMarkdownPatchMap = {};
            }
            return {
                perSceneParallel: true,
                sceneMarkdownPatchMap,
                stage2_2Text: '',
                stage2_2Result: null,
                stage2_2Check: { ok: true, normalizedText: '' },
                skippedExistingSceneCount: skippedExistingSceneUnits.length,
            };
        }

        // Preflight: no Beat marker → skip scene (invalid); continued numbering (Beat 11+) still runs.
        const missingBeat1Units = [];
        const beatsTooShortErrors = [];
        const unitsAfterBeat1Gate = [];
        for (const unit of unitsToProcess) {
            const sceneId = String(unit?.sceneId || '').trim() || 'unknown';
            const sceneText = stripBlockLevelMarkersFromSceneText(unit?.sceneText || unit?.sceneMarkdown || '');
            if (!sceneTextHasAnyBeat(sceneText)) {
                missingBeat1Units.push(unit);
                onLog?.(
                    t(
                        `[${label}] 场景 ${sceneId} 输入无 Beat 标记，跳过场景编排（场景不对）`,
                        `[${label}] Scene ${sceneId} has no Beat marker in input; skipping orchestration (invalid scene)`
                    ),
                    'error'
                );
                continue;
            }
            const firstBeat = sceneFirstBeatNumber(sceneText);
            if (firstBeat && !isCanonicalFirstBeatNumber(firstBeat)) {
                onLog?.(
                    t(
                        `[${label}] 场景 ${sceneId} 首拍为 Beat ${firstBeat}（跨场连编兼容），继续编排`,
                        `[${label}] Scene ${sceneId} starts at Beat ${firstBeat} (cross-scene numbering tolerated); continuing orchestration`
                    ),
                    'warning'
                );
            }
            try {
                const resolved = resolveSceneBeatsBodyForStage22(sceneText, sceneId);
                if (resolved.usedSceneFallback) {
                    onLog?.(
                        t(
                            `[${label}] 场景 ${sceneId} Beat 分割失败或过短（extracted=${resolved.extractedChars ?? 0}），已兜底使用整场正文（${resolved.bodyText.length} 字）`,
                            `[${label}] Scene ${sceneId} beat split failed/too short (extracted=${resolved.extractedChars ?? 0}); falling back to full scene body (${resolved.bodyText.length} chars)`
                        ),
                        'warning'
                    );
                }
                unitsAfterBeat1Gate.push(unit);
            } catch (beatsErr) {
                const msg = String(beatsErr?.message || beatsErr || '');
                if (msg.startsWith('SCENE_MARKDOWN_MISSING_BEAT_1')) {
                    missingBeat1Units.push(unit);
                    onLog?.(
                        t(
                            `[${label}] 场景 ${sceneId} 输入无 Beat 标记，跳过场景编排（场景不对）`,
                            `[${label}] Scene ${sceneId} has no Beat marker in input; skipping orchestration (invalid scene)`
                        ),
                        'error'
                    );
                    continue;
                }
                beatsTooShortErrors.push(msg);
                onLog?.(
                    t(
                        `[${label}] 场景 ${sceneId} Beats/整场正文均不足 ${MIN_SCENE_BEATS_CHARS} 字：${msg}`,
                        `[${label}] Scene ${sceneId} Beats and full scene body both shorter than ${MIN_SCENE_BEATS_CHARS}: ${msg}`
                    ),
                    'error'
                );
            }
        }
        unitsToProcess = unitsAfterBeat1Gate;
        // Keep skipExisting markers in the allowlist so storyboard kickoffs for already-imported
        // scenes remain valid while remaining scenes continue orchestration.
        orchestrationCanonicalSceneIdsRef.current = expandSceneIdAllowlist(
            [
                ...(orchestrationCanonicalSceneIdsRef.current || []),
                ...(unitsToProcess || []).map((unit) => String(unit?.sceneId || '').trim()),
                ...(skippedExistingSceneUnits || []).map((unit) => String(unit?.sceneId || '').trim()),
            ].filter(Boolean),
            episodePrefix
        );
        const publishMissingBeat1Failures = (totalScenes) => {
            if (!missingBeat1Units.length) return;
            const totalForPanel = Math.max(Number(totalScenes) || 0, missingBeat1Units.length, 1);
            for (const unit of missingBeat1Units) {
                const sceneId = String(unit?.sceneId || '').trim();
                if (!sceneId) continue;
                publishSceneOrchestrationPanelStatus({
                    sceneId,
                    phase: 'failed',
                    sceneOrder: unit?.sceneOrder,
                    totalScenes: totalForPanel,
                    errorCode: `SCENE_MARKDOWN_MISSING_BEAT_1:${sceneId}`,
                });
            }
        };
        if (missingBeat1Units.length > 0 && unitsToProcess.length <= 0) {
            beginSceneOrchestrationPanelTracking(missingBeat1Units.length);
            publishMissingBeat1Failures(missingBeat1Units.length);
            throw new Error(
                t(
                    `场景编排跳过：全部 ${missingBeat1Units.length} 场输入均无 Beat 标记，场景不对。`,
                    `Scene orchestration skipped: all ${missingBeat1Units.length} scene(s) lack Beat markers (invalid scene).`
                )
            );
        }
        if (beatsTooShortErrors.length > 0) {
            throw new Error(
                t(
                    `场景编排失败：${beatsTooShortErrors.length} 场 Beats 分割失败且整场正文也少于 ${MIN_SCENE_BEATS_CHARS} 字。${beatsTooShortErrors.join('；')}`,
                    `Scene orchestration failed: ${beatsTooShortErrors.length} scene(s) have failed beat split and full scene body shorter than ${MIN_SCENE_BEATS_CHARS}. ${beatsTooShortErrors.join('; ')}`
                )
            );
        }
        const isSingleExplicitScene = explicitSceneUnits.length === 1;
        const orchestrationSceneCount = isSingleExplicitScene
            ? 1
            : Math.max(
                unitsToProcess.length + missingBeat1Units.length,
                sceneUnits.length,
                0
            );
        const useBackendSceneOrchestration = !isSingleExplicitScene && orchestrationSceneCount > 1;
        const shouldDisableEpisodeRecovery = Boolean(
            sceneAnalysisModePayload === 'scene_beats_only'
            || useBackendSceneOrchestration
            || isSingleExplicitScene
        );

        if (isSingleExplicitScene) {
            const unit = explicitSceneUnits[0];
            const sceneLabel = `${label} [${unit.sceneId}]`;
            setAnalysisFlowStatus({
                phase: 'scene_beats',
                message: t(
                    `正在生成单场场景编排：${unit.sceneId}...`,
                    `Generating scene beats for single scene: ${unit.sceneId}...`
                ),
            });
            const singleSceneBlock = wrapSceneUnitAsScriptBlock(unit);
            const singleSceneBody = [
                `【单场处理模式】本次仅处理 Scene ID \`${unit.sceneId}\`。输入剧本正文含该场 \`【场景名称】{短名}｜{日·内/外}\` 场景头 + \`[BEAT_START:…]\`…\`[BEAT_END:…]\` Beat 块（不含 Scene 级【主环境】块；可含【本场衍生环境名】，不得列入裸主环境名）。Environment Name 与 ENV:[] 只认【本场衍生环境名】，Beat 明文出现这些完整衍生名时必须套 ENV:[原样名]，禁止把主环境裸名列入或套 ENV:[]，禁止另起未列出衍生名。请将 \`【场景名称】\` 后的 \`{短名}｜{日·内/外}\` 原样落入 Scene Name 列，并对 Beat 做 Index 化落表，输出该场景对应的一行 Scenes Table（仅含表头、分隔行与本场一行数据；不要输出 Part 1: Scenes Table 标题），不要处理其他场景。Scenes Table 的 Scene ID 列必须精确填写 \`${unit.sceneId}\`，不得仅填场次序号或其他别名。`,
                buildStage2_2UserInputFromStage1(stage1SourceText, singleSceneBlock),
            ].join('\n\n');
            const singleFinalInput = singleSceneBody;

            for (let fallbackAttempt = 0; fallbackAttempt <= validationRetryLimit; fallbackAttempt += 1) {
                if (fallbackAttempt > 0) {
                    onLog?.(
                        `[${sceneLabel}] validation failed, auto retry ${fallbackAttempt}/${validationRetryLimit}...`,
                        'warning'
                    );
                }
                onLog?.(
                    t(`[${sceneLabel}] 正在提交 LLM...`, `[${sceneLabel}] submitting to LLM...`),
                    'process'
                );
                const attempt = await runSingleStage2_2Attempt({
                    attemptLabel: sceneLabel,
                    attemptUserInputBody: singleSceneBody,
                    attemptFinalUserInput: singleFinalInput,
                    fallbackAttempt,
                    disableEpisodeRecovery: shouldDisableEpisodeRecovery,
                    targetSceneIds: [String(unit.sceneId || '').trim()].filter(Boolean),
                });
                if (attempt.stage2_2Check?.ok) {
                    const normalizedText = attempt.stage2_2Check.normalizedText;
                    onLog?.(
                        t(`[${sceneLabel}] LLM 已返回，校验通过`, `[${sceneLabel}] LLM returned and passed validation`),
                        'success'
                    );
                    const sceneId = String(unit.sceneId || '').trim();
                    await importSingleSceneDuringOrchestration({
                        sceneId,
                        sceneOrder: unit?.sceneOrder,
                        markdown: normalizedText,
                        unit,
                        replaceExistingScenes: false,
                        source: `${logPhasePrefix}-single-scene-live-import`,
                    });
                    return {
                        stage2_2Text: normalizedText,
                        stage2_2Result: attempt.stage2_2Result,
                        stage2_2Check: attempt.stage2_2Check,
                        perSceneParallel: true,
                        sceneMarkdownPatchMap: buildSceneMarkdownPatchFromPerSceneOutputs(
                            [{
                                sceneId,
                                sceneOrder: unit?.sceneOrder,
                                markdown: normalizedText,
                            }],
                            [unit]
                        ),
                    };
                }
                lastError = attempt.stage2_2Check?.reason || t(
                    `${sceneLabel} 镜头节拍生成失败：未检测到有效的场景编排表。`,
                    `${sceneLabel} did not return a valid Scenes Table.`
                );
            }
            throw new Error(lastError || `${sceneLabel} failed after ${validationRetryLimit} automatic retries.`);
        }

        if (useBackendSceneOrchestration) {
            const adaptedForSync = String(
                extractAdaptedScriptFromStage2_2UserInputBody(stage2_2UserInputBody || finalStage2_2UserInput)
                || extractStage1AdaptedScriptBody(stage1SourceText)
                || adaptedScriptForSplit
                || ''
            ).trim();
            const orchestrationSceneIds = collectOrchestrationResetSceneIds(unitsToProcess, episodePrefix);
            // Preserve skipExisting live-imported markers so later batch import does NOT
            // replaceExistingScenes/purge while those scenes already have storyboard in flight.
            const preservedLiveImported = new Set(
                [...(orchestrationLiveImportedScenesRef.current || [])]
                    .map((id) => String(id || '').trim())
                    .filter(Boolean)
            );
            orchestrationLiveImportedScenesRef.current = preservedLiveImported;
            orchestrationCanonicalSceneIdsRef.current = expandSceneIdAllowlist([
                ...(orchestrationCanonicalSceneIdsRef.current || []),
                ...(orchestrationSceneIds || []),
                ...preservedLiveImported,
            ], episodePrefix);
            orchestrationPersistedSceneMarkdownRef.current = {};
            setLiveSceneMarkdownByScene({});
            // Do not resetStoryboardKickoffTracking here: skipExisting may already have
            // claimed markers / started generateSceneShots on existing workspace scenes.
            onLog?.(`[${label}] backend scene orchestration enabled: ${orchestrationSceneCount} scene(s).`, 'info');
            if (projectId && activeEpisode?.id) {
                try {
                    if (orchestrationSceneIds.length > 0) {
                        await resetSceneOrchestrationProgress({
                            project_id: Number(projectId),
                            episode_id: Number(activeEpisode.id),
                            scene_ids: orchestrationSceneIds,
                        });
                        await clearSceneMarkdownPatchForScenes(orchestrationSceneIds, {
                            source: `${logPhasePrefix}-orchestration-clear`,
                        });
                        onLog?.(`[${label}] cleared stale orchestration data for ${orchestrationSceneCount} scene(s).`, 'info');
                    }
                } catch (clearErr) {
                    onLog?.(`[${label}] orchestration pre-clear warning: ${clearErr?.message || clearErr}`, 'warning');
                }
            }
            if (projectId && activeEpisode?.id && adaptedForSync) {
                try {
                    await syncSceneUnitsProgress({
                        project_id: Number(projectId),
                        episode_id: Number(activeEpisode.id),
                        script_text: adaptedForSync,
                        prefer_markers: true,
                    });
                    onLog?.(`[${label}] synced ${orchestrationSceneCount} scene unit(s) before orchestration.`, 'info');
                } catch (syncErr) {
                    onLog?.(`[${label}] scene units sync warning: ${syncErr?.message || syncErr}`, 'warning');
                }
            }
            beginSceneOrchestrationPanelTracking(orchestrationSceneCount);
            publishMissingBeat1Failures(orchestrationSceneCount);
            setAnalysisFlowStatus({
                phase: 'scene_beats',
                message: t(
                    `已同步 ${orchestrationSceneCount} 场，正在由后端并行发起场景编排...`,
                    `Synced ${orchestrationSceneCount} scene(s); launching parallel scene beats on backend...`
                ),
            });

            const reportSceneOrchestrationPhase = ({ sceneId, phase, sceneOrder, totalScenes, errorCode }) => {
                publishSceneOrchestrationPanelStatus({
                    sceneId,
                    phase,
                    sceneOrder,
                    totalScenes: totalScenes || orchestrationSceneCount,
                    errorCode,
                });
            };

            const sceneUnitMatchesId = (unit, rawId) => {
                const sceneId = String(unit?.sceneId || '').trim();
                const candidate = String(rawId || '').trim();
                if (!sceneId || !candidate) return false;
                if (sceneId === candidate) return true;
                return sceneUnitIdsMatch(sceneId, candidate, unit?.sceneOrder, episodePrefix)
                    || isSceneIdInAllowlist(candidate, expandSceneIdAllowlist([sceneId], episodePrefix), episodePrefix);
            };
            const isSceneImportedThisRun = (sceneId) => {
                const live = orchestrationLiveImportedScenesRef.current;
                const stable = String(sceneId || '').trim();
                if (!stable || !(live instanceof Set) || live.size <= 0) return false;
                if (live.has(stable)) return true;
                return isSceneIdInAllowlist(stable, live, episodePrefix);
            };
            const importReadyScenesFromProgressSnapshot = async () => {
                if (!activeEpisode?.id || typeof getEpisodeProgressSnapshot !== 'function') return;
                try {
                    const snapshot = await getEpisodeProgressSnapshot(Number(activeEpisode.id));
                    const rows = Array.isArray(snapshot?.scene_units) ? snapshot.scene_units : [];
                    for (const unit of unitsToProcess || []) {
                        const sceneId = String(unit?.sceneId || '').trim();
                        if (!sceneId || isSceneImportedThisRun(sceneId)) continue;
                        const row = rows.find((candidate) => sceneUnitMatchesId(unit, candidate?.scene_id))
                            || rows.find((candidate) => String(candidate?.scene_id || '').trim() === sceneId);
                        const markdown = String(row?.scene_markdown || '').trim();
                        const phase = deriveSceneOrchestrationPhase(row);
                        if (!markdown || !['llm_returned', 'importing', 'imported'].includes(phase)) continue;
                        await importSingleSceneDuringOrchestration({
                            sceneId,
                            sceneOrder: row?.scene_order ?? unit?.sceneOrder,
                            markdown,
                            unit,
                            replaceExistingScenes: false,
                            source: `${logPhasePrefix}-orchestration-snapshot-import`,
                        });
                    }
                } catch (snapshotErr) {
                    onLog?.(`[${label}] snapshot import warning: ${snapshotErr?.message || snapshotErr}`, 'warning');
                }
            };

            const runSequentialSceneFallback = async (reason = '', retrySceneIds = null) => {
                await importReadyScenesFromProgressSnapshot();
                for (const rawId of fallbackSucceededSceneIds) {
                    const unit = (unitsToProcess || []).find((item) => sceneUnitMatchesId(item, rawId));
                    const sceneId = String(unit?.sceneId || rawId || '').trim();
                    if (!sceneId) continue;
                    void kickoffStoryboardForImportedScene({
                        markerSceneId: sceneId,
                        sceneOrder: unit?.sceneOrder,
                    });
                }
                const retrySet = Array.isArray(retrySceneIds) && retrySceneIds.length > 0
                    ? retrySceneIds.map((id) => String(id || '').trim()).filter(Boolean)
                    : null;
                const fallbackUnits = (unitsToProcess || []).filter((unit) => {
                    const sceneId = String(unit?.sceneId || '').trim();
                    if (!sceneId) return false;
                    if (isSceneImportedThisRun(sceneId)) {
                        onLog?.(
                            t(
                                `[${label}] ${sceneId} 本轮已入库，跳过场景编排重跑`,
                                `[${label}] ${sceneId} already imported this run; skip orchestration rerun`
                            ),
                            'info'
                        );
                        return false;
                    }
                    if (retrySet && !retrySet.some((id) => sceneUnitMatchesId(unit, id))) {
                        return false;
                    }
                    return true;
                });
                if (reason) {
                    onLog?.(`[${label}] ${reason}`, 'warning');
                }
                if (fallbackUnits.length <= 0) {
                    onLog?.(
                        t(
                            `[${label}] 失败场次已全部入库或无需重跑，跳过逐场重试。`,
                            `[${label}] No remaining scenes need per-scene retry.`
                        ),
                        'info'
                    );
                    return {
                        perSceneParallel: true,
                        sceneMarkdownPatchMap: {},
                        stage2_2Text: '',
                        stage2_2Result: null,
                        stage2_2Check: { ok: true, normalizedText: '' },
                    };
                }
                onLog?.(
                    `[${label}] falling back to parallel per-scene orchestration for ${fallbackUnits.length}/${orchestrationSceneCount} scene(s): ${fallbackUnits.map((unit) => unit.sceneId).join(', ')}.`,
                    'warning'
                );
                setAnalysisFlowStatus({
                    phase: 'scene_beats',
                    message: t(
                        `并行编排未全部成功，正在重试失败场次（${fallbackUnits.length}/${orchestrationSceneCount} 场）...`,
                        `Parallel orchestration was incomplete; retrying failed scene beats (${fallbackUnits.length}/${orchestrationSceneCount} scenes)...`
                    ),
                });

                const fallbackOutcomes = await Promise.allSettled(fallbackUnits.map(async (unit) => {
                    const sceneId = String(unit?.sceneId || '').trim();
                    const sceneLabel = `${label} [${sceneId}]`;
                    const singleSceneBlock = wrapSceneUnitAsScriptBlock(unit);
                    const singleSceneBody = [
                        `【单场处理模式】本次仅处理 Scene ID \`${sceneId}\`。输入剧本正文含该场 \`【场景名称】{短名}｜{日·内/外}\` 场景头 + \`[BEAT_START:…]\`…\`[BEAT_END:…]\` Beat 块（不含 Scene 级【主环境】块；可含【本场衍生环境名】，不得列入裸主环境名）。Environment Name 与 ENV:[] 只认【本场衍生环境名】，Beat 明文出现这些完整衍生名时必须套 ENV:[原样名]，禁止把主环境裸名列入或套 ENV:[]，禁止另起未列出衍生名。请将 \`【场景名称】\` 后的 \`{短名}｜{日·内/外}\` 原样落入 Scene Name 列，并对 Beat 做 Index 化落表，输出该场景对应的一行 Scenes Table（仅含表头、分隔行与本场一行数据；不要输出 Part 1: Scenes Table 标题），不要处理其他场景。Scenes Table 的 Scene ID 列必须精确填写 \`${sceneId}\`，不得仅填场次序号或其他别名。`,
                        buildStage2_2UserInputFromStage1(stage1SourceText, singleSceneBlock),
                    ].join('\n\n');
                    let sceneAttempt = null;
                    let sceneLastError = '';
                    for (let fallbackAttempt = 0; fallbackAttempt <= validationRetryLimit; fallbackAttempt += 1) {
                        if (fallbackAttempt > 0) {
                            onLog?.(
                                `[${sceneLabel}] validation failed, auto retry ${fallbackAttempt}/${validationRetryLimit}...`,
                                'warning'
                            );
                        }
                        publishSceneOrchestrationPanelStatus({
                            sceneId,
                            phase: 'llm_submit',
                            sceneOrder: unit?.sceneOrder,
                            totalScenes: orchestrationSceneCount,
                        });
                        const attempt = await runSingleStage2_2Attempt({
                            attemptLabel: sceneLabel,
                            attemptUserInputBody: singleSceneBody,
                            attemptFinalUserInput: singleSceneBody,
                            fallbackAttempt,
                            disableEpisodeRecovery: shouldDisableEpisodeRecovery,
                            targetSceneIds: [sceneId],
                        });
                        if (attempt.stage2_2Check?.ok) {
                            sceneAttempt = attempt;
                            publishSceneOrchestrationPanelStatus({
                                sceneId,
                                phase: 'llm_returned',
                                sceneOrder: unit?.sceneOrder,
                                totalScenes: orchestrationSceneCount,
                            });
                            break;
                        }
                        sceneLastError = attempt.stage2_2Check?.reason || sceneLastError;
                    }
                    if (!sceneAttempt?.stage2_2Check?.ok) {
                        throw new Error(sceneLastError || `${sceneLabel} failed during parallel fallback.`);
                    }
                    await importSingleSceneDuringOrchestration({
                        sceneId,
                        sceneOrder: unit?.sceneOrder,
                        markdown: sceneAttempt.stage2_2Check.normalizedText,
                        unit,
                        replaceExistingScenes: false,
                        source: `${logPhasePrefix}-parallel-fallback-import`,
                    });
                    return {
                        sceneId,
                        sceneOrder: unit?.sceneOrder,
                        markdown: sceneAttempt.stage2_2Check.normalizedText,
                        result: sceneAttempt.stage2_2Result,
                    };
                }));

                const validatedOutputs = [];
                const fallbackFailures = [];
                let sequentialLastResult = null;
                fallbackOutcomes.forEach((outcome) => {
                    if (outcome.status === 'fulfilled' && outcome.value) {
                        validatedOutputs.push({
                            sceneId: outcome.value.sceneId,
                            sceneOrder: outcome.value.sceneOrder,
                            markdown: outcome.value.markdown,
                        });
                        sequentialLastResult = outcome.value.result;
                    } else if (outcome.status === 'rejected') {
                        fallbackFailures.push(outcome.reason);
                    }
                });
                if (fallbackFailures.length > 0 || validatedOutputs.length < fallbackUnits.length) {
                    const firstFailure = fallbackFailures[0];
                    throw new Error(
                        firstFailure?.message || firstFailure || lastError || `${label} failed during parallel per-scene fallback.`
                    );
                }

                const sceneMarkdownPatchMap = buildSceneMarkdownPatchFromPerSceneOutputs(
                    validatedOutputs,
                    unitsToProcess
                );
                return {
                    perSceneParallel: true,
                    sceneMarkdownPatchMap,
                    stage2_2Text: '',
                    stage2_2Result: sequentialLastResult,
                    stage2_2Check: { ok: true, normalizedText: '' },
                };
            };

            let parallelOrchestrationFailed = false;
            let fallbackRetrySceneIds = null;
            let fallbackSucceededSceneIds = [];
            let stopSceneOrchestrationPolling = null;
            const unitsBySceneId = Object.fromEntries(
                (unitsToProcess || [])
                    .map((unit) => [String(unit?.sceneId || '').trim(), unit])
                    .filter(([sceneId]) => sceneId)
            );
            if (activeEpisode?.id) {
                stopSceneOrchestrationPolling = createSceneOrchestrationProgressPoller({
                    getSnapshot: getEpisodeProgressSnapshot,
                    episodeId: Number(activeEpisode.id),
                    sceneUnits: unitsToProcess,
                    episodePrefix,
                    onPhase: reportSceneOrchestrationPhase,
                    onSceneReady: async ({ sceneId, sceneOrder, markdown }) => {
                        await importSingleSceneDuringOrchestration({
                            sceneId,
                            sceneOrder,
                            markdown,
                            unit: unitsBySceneId[String(sceneId || '').trim()],
                            replaceExistingScenes: false,
                            source: `${logPhasePrefix}-orchestration-live-import`,
                        });
                    },
                });
            }
            const orchestrationSceneLabels = unitsToProcess
                .map((unit) => String(unit?.sceneId || '').trim())
                .filter(Boolean);
            try {
            for (let fallbackAttempt = 0; fallbackAttempt <= validationRetryLimit; fallbackAttempt += 1) {
                if (fallbackAttempt > 0) {
                    onLog?.(
                        `[${label}] validation failed, auto retry ${fallbackAttempt}/${validationRetryLimit}...`,
                        'warning'
                    );
                    setAnalysisFlowStatus({
                        phase: 'scene_beats',
                        message: t(
                            `场景编排校验失败，正在自动重试 (${fallbackAttempt}/${validationRetryLimit})...`,
                            `Scene beats validation failed. Auto-retrying (${fallbackAttempt}/${validationRetryLimit})...`
                        ),
                    });
                }
                onLog?.(
                    t(
                        `[${label}] 已提交 LLM 并行编排请求（${orchestrationSceneCount} 场）${orchestrationSceneLabels.length ? `：${orchestrationSceneLabels.join(', ')}` : ''}`,
                        `[${label}] Submitted parallel scene-beats LLM request (${orchestrationSceneCount} scene(s))${orchestrationSceneLabels.length ? `: ${orchestrationSceneLabels.join(', ')}` : ''}`
                    ),
                    'process'
                );
                unitsToProcess.forEach((unit, index) => {
                    const sceneId = String(unit?.sceneId || '').trim();
                    if (!sceneId) return;
                    reportSceneOrchestrationPhase({
                        sceneId,
                        phase: 'queued',
                        sceneOrder: unit?.sceneOrder ?? index + 1,
                        totalScenes: orchestrationSceneCount,
                    });
                });
                let attempt;
                try {
                    attempt = await runSingleStage2_2Attempt({
                        attemptLabel: `${label} (sync-orchestration)`,
                        attemptUserInputBody: stage2_2UserInputBody,
                        attemptFinalUserInput: finalStage2_2UserInput,
                        fallbackAttempt,
                        disableEpisodeRecovery: true,
                        targetSceneIds: orchestrationSceneLabels,
                    });
                } catch (orchErr) {
                    parallelOrchestrationFailed = true;
                    lastError = orchErr?.message || String(orchErr || '');
                    const partial = parseSceneMarkdownPartialFailureDetail(
                        orchErr?.response?.data?.detail ?? lastError
                    );
                    if (partial?.failedSceneIds?.length) {
                        fallbackRetrySceneIds = partial.failedSceneIds;
                    }
                    if (partial?.succeededSceneIds?.length) {
                        fallbackSucceededSceneIds = partial.succeededSceneIds;
                    }
                    break;
                }
                const perSceneOutputs = extractPerSceneOutputsFromResult(attempt.stage2_2Result);
                if (attempt.stage2_2Result?.meta?.recovered_from_episode_poll) {
                    lastError = t(
                        '并行场景编排未完成，拒绝使用分集缓存结果。',
                        'Parallel scene orchestration is not finished; refused cached episode result.'
                    );
                    continue;
                }
                if (perSceneOutputs.length > 0) {
                    const validatedOutputs = [];
                    const invalidSceneIds = [];
                    for (const item of perSceneOutputs) {
                        const sceneCheck = validateStage2_2BeatsOutput(
                            item.markdown,
                            `${label} [${item.sceneId}]`
                        );
                        if (!sceneCheck.ok) {
                            invalidSceneIds.push(String(item.sceneId || '').trim());
                            lastError = sceneCheck.reason || lastError;
                            continue;
                        }
                        validatedOutputs.push({
                            ...item,
                            markdown: sceneCheck.normalizedText,
                        });
                    }
                    if (validatedOutputs.length > 0) {
                        const sceneMarkdownPatchMap = buildSceneMarkdownPatchFromPerSceneOutputs(
                            validatedOutputs,
                            unitsToProcess
                        );
                        await ensureOrchestrationScenesInWorkspace({
                            patchMap: sceneMarkdownPatchMap,
                            unitsBySceneId,
                            source: `${logPhasePrefix}-sync-orchestration-import`,
                            totalScenes: orchestrationSceneCount,
                        });
                        if (invalidSceneIds.length <= 0 && validatedOutputs.length >= orchestrationSceneCount) {
                            stopSceneOrchestrationPolling?.();
                            stopSceneOrchestrationPolling = null;
                            return {
                                perSceneParallel: true,
                                sceneMarkdownPatchMap,
                                stage2_2Text: '',
                                stage2_2Result: attempt.stage2_2Result,
                                stage2_2Check: { ok: true, normalizedText: '' },
                            };
                        }
                    }
                    const validatedIds = new Set(
                        validatedOutputs
                            .map((item) => String(item.sceneId || '').trim())
                            .filter(Boolean)
                    );
                    const missingSceneIds = (unitsToProcess || [])
                        .filter((unit) => {
                            const sceneId = String(unit?.sceneId || '').trim();
                            if (!sceneId || isSceneImportedThisRun(sceneId)) return false;
                            if (validatedIds.has(sceneId)) return false;
                            return ![...validatedIds].some((id) => sceneUnitMatchesId(unit, id));
                        })
                        .map((unit) => String(unit?.sceneId || '').trim());
                    fallbackRetrySceneIds = [...new Set([...invalidSceneIds, ...missingSceneIds].filter(Boolean))];
                    lastError = t(
                        `并行场景编排返回 ${validatedOutputs.length}/${orchestrationSceneCount} 场，仅重试未完成场次。`,
                        `Parallel orchestration returned ${validatedOutputs.length}/${orchestrationSceneCount} scenes; retrying only unfinished scenes.`
                    );
                    break;
                }
                lastError = attempt.stage2_2Check?.reason || lastError || t(
                    `${label} 镜头节拍生成失败：未检测到有效的分场景编排结果。`,
                    `${label} did not return valid per-scene orchestration outputs.`
                );
                fallbackRetrySceneIds = (unitsToProcess || [])
                    .map((unit) => String(unit?.sceneId || '').trim())
                    .filter((sceneId) => sceneId && !isSceneImportedThisRun(sceneId));
                break;
            }
            } finally {
                stopSceneOrchestrationPolling?.();
            }
            return runSequentialSceneFallback(
                parallelOrchestrationFailed
                    ? t('后端并行编排未全部成功，正在仅重试失败场次。', 'Backend parallel orchestration did not finish all scenes; retrying only failed scenes.')
                    : t('后端并行编排校验未通过，正在仅重试未完成场次。', 'Backend parallel orchestration validation failed; retrying only unfinished scenes.'),
                fallbackRetrySceneIds
            );
        }

        for (let fallbackAttempt = 0; fallbackAttempt <= validationRetryLimit; fallbackAttempt += 1) {
            if (fallbackAttempt > 0) {
                onLog?.(
                    `[${label}] validation failed, auto retry ${fallbackAttempt}/${validationRetryLimit}...`,
                    'warning'
                );
                setAnalysisFlowStatus({
                    phase: 'scene_beats',
                    message: t(
                        `场景编排校验失败，正在自动重试 (${fallbackAttempt}/${validationRetryLimit})...`,
                        `Scene beats validation failed. Auto-retrying (${fallbackAttempt}/${validationRetryLimit})...`
                    ),
                });
            }

            onLog?.(
                t(`[${label}] 已提交 LLM（整表模式，${orchestrationSceneCount || 1} 场）...`, `[${label}] Submitted to LLM (full-table mode, ${orchestrationSceneCount || 1} scene(s))...`),
                'process'
            );
            const attempt = await runSingleStage2_2Attempt({
                attemptLabel: label,
                attemptUserInputBody: stage2_2UserInputBody,
                attemptFinalUserInput: finalStage2_2UserInput,
                fallbackAttempt,
                disableEpisodeRecovery: shouldDisableEpisodeRecovery,
            });
            if (attempt.stage2_2Check?.ok) {
                const normalizedTableText = String(attempt.stage2_2Check.normalizedText || '').trim();
                const importCheck = validateAutoSceneTableImport(normalizedTableText);
                const tableRowCount = importCheck?.ok
                    ? (Array.isArray(parseMarkdownTable(importCheck.tableText || '')?.rows)
                        ? parseMarkdownTable(importCheck.tableText || '').rows.length
                        : 0)
                    : 0;
                if (orchestrationSceneCount > 1 && tableRowCount < orchestrationSceneCount) {
                    lastError = t(
                        `整表模式仅返回 ${tableRowCount}/${orchestrationSceneCount} 场，无法作为全部场景重排结果。`,
                        `Full-table mode returned only ${tableRowCount}/${orchestrationSceneCount} scene(s); cannot use as all-scene rerun result.`
                    );
                    onLog?.(`[${label}] ${lastError}`, 'warning');
                    continue;
                }
                onLog?.(
                    t(`[${label}] LLM 已返回，校验通过`, `[${label}] LLM returned and passed validation`),
                    'success'
                );
                return {
                    stage2_2Text: attempt.stage2_2Check.normalizedText,
                    stage2_2Result: attempt.stage2_2Result,
                    stage2_2Check: attempt.stage2_2Check,
                };
            }
            lastError = attempt.stage2_2Check?.reason || t(`${label} 镜头节拍生成失败：未检测到有效的场景编排表。`, `${label} did not return a valid Scenes Table.`);
        }

        throw new Error(lastError || `${label} failed after ${validationRetryLimit} automatic retries.`);
    }, [
        activeEpisode?.ai_stage_outputs,
        activeEpisode?.id,
        analysisAttentionNotes,
        awaitAnalyzeSceneWithRecovery,
        beginSceneOrchestrationPanelTracking,
        buildSceneMarkdownPatchFromPerSceneOutputs,
        buildStage2_2SubjectIndexSection,
        buildStage2_2UserInputFromStage1,
        clearSceneMarkdownPatchForScenes,
        clearStoryboardTrackingForScenes,
        ensureOrchestrationScenesInWorkspace,
        extractAdaptedScriptFromStage2_2UserInputBody,
        extractAnalysisTextFromResult,
        extractPerSceneOutputsFromResult,
        extractPureSubjectIndexText,
        extractStage1AdaptedScriptBody,
        fetchPrompt,
        fetchScenes,
        getEpisodeProgressSnapshot,
        hasSubjectIndexStructure,
        importSingleSceneDuringOrchestration,
        kickoffStoryboardForImportedScene,
        logStage2_2Diagnostics,
        onLog,
        parseSceneMarkdownBySceneMap,
        parseSceneUnitsFromScriptMarkers,
        parseStageOutputsObject,
        projectId,
        publishSceneOrchestrationPanelStatus,
        resetSceneOrchestrationProgress,
        resetStoryboardKickoffTracking,
        selectedReuseSubjectAssets,
        resolveSelectedScriptAnalysisApiId,
        setAnalysisFlowStatus,
        syncSceneUnitsProgress,
        t,
        validateStage2_2BeatsOutput,
        wrapSceneUnitAsScriptBlock,
    ]);

    const runPostImportSceneSubjectPipeline = useCallback(async (importReport, explicitText = null, options = {}) => {
        const importedSceneRows = Array.isArray(importReport?.importedSceneRows) ? importReport.importedSceneRows : [];
        const emptyReport = {
            checkedSceneCount: importedSceneRows.length,
            missingSceneCount: 0,
            missingItemCount: 0,
            missingSceneReports: [],
            supplementReport: {
                createdItems: [], skippedItems: [], failedItems: [], sceneReports: [],
                countsByType: { character: 0, prop: 0, environment: 0 },
            },
            importedSubjectCounts: { character: 0, prop: 0, environment: 0 },
        };

        if (sceneBeatsOnlyRerunInFlightRef.current && !options?.forceAssetDesign) {
            onLog?.('仅场景重排期间，资产设计流程已按保护策略暂停。', 'info');
            return {
                ...emptyReport,
                checkedSceneCount: importedSceneRows.length,
            };
        }

        const incomingAssetCategoryKeys = resolveAssetCategoryKeysFromTargets(options.targetEntityTypes);
        const freeAssetCategoryKeys = incomingAssetCategoryKeys.filter(
            (key) => !phase2InFlightCategoriesRef.current.has(key)
        );
        if (freeAssetCategoryKeys.length === 0) {
            onLog?.('Skipped duplicate Stage 3 asset-design trigger while one is already running.', 'warning');
            return emptyReport;
        }
        const syncRetryingAssetCategoryUi = () => {
            const keys = Array.from(phase2InFlightCategoriesRef.current);
            phase2GenerationInFlightRef.current = keys.length > 0;
            setRetryingAssetCategoryKeys(keys);
            setIsRetryingPhase2(keys.length > 0);
        };
        const releaseIncomingAssetLock = () => {
            freeAssetCategoryKeys.forEach((key) => phase2InFlightCategoriesRef.current.delete(key));
            syncRetryingAssetCategoryUi();
        };
        const claimIncomingAssetLock = () => {
            freeAssetCategoryKeys.forEach((key) => phase2InFlightCategoriesRef.current.add(key));
            syncRetryingAssetCategoryUi();
        };

        const episodeIdForPhase2 = Number(activeEpisode?.id || 0) || 0;
        const allowRepeatAutoStage3 = Boolean(options?.isRetryPhase2 || options?.forceAssetDesign);
        // Explicit skipExistingAssets:true always wins (pipeline supervisor / resume / ENV co-start).
        // isRetryPhase2 alone used to force a full regenerate and ignored that flag, so a successful
        // environment design was billed again as soon as the supervisor probed any leftover poster row.
        const skipExistingAssets = options?.skipExistingAssets === true
            ? true
            : (options?.skipExistingAssets === false
                ? false
                : !options?.isRetryPhase2);
        const overwriteExistingSubjects = options?.overwriteExistingSubjects === true
            ? true
            : (options?.overwriteExistingSubjects === false
                ? false
                : Boolean(options?.isRetryPhase2) && !skipExistingAssets);
        if (
            !allowRepeatAutoStage3
            && episodeIdForPhase2 > 0
            && phase2AutoCompletedEpisodeRef.current === episodeIdForPhase2
        ) {
            onLog?.(
                'Skipped duplicate Stage 3 asset-design trigger; automatic asset design already completed successfully for this episode run.',
                'warning'
            );
            return {
                ...emptyReport,
                skippedDuplicateCompleted: true,
            };
        }

        // Claim Stage 3 lock + env gate BEFORE any await so concurrent callers cannot
        // both pass the in-flight check and fan out the same category twice.
        claimIncomingAssetLock();
        if (freeAssetCategoryKeys.includes('environments')) {
            environmentAssetDesignPendingRef.current = true;
        }

        onLog?.(`[Stage 3 Debug] checking early return condition: projectId=${projectId}, importedSceneRows count=${importedSceneRows.length}`);

        if (!projectId) {
            if (freeAssetCategoryKeys.includes('environments')) {
                environmentAssetDesignPendingRef.current = false;
            }
            releaseIncomingAssetLock();
            onLog?.(`[Stage 3 Debug] aborting because projectId is empty.`);
            return emptyReport;
        }

                const authoritativeSubjectText = explicitText || llmRawResultContent || llmResultContent || activeEpisode?.ai_scene_analysis_result || '';
                const persistedSubjectIndexText = String(activeEpisode?.ai_scene_analysis_subject_index || '').trim();
                const extractedSections = extractAnalysisSections(authoritativeSubjectText);
                let subjectIndexText = extractPureSubjectIndexText(options.explicitSubjectIndexText || persistedSubjectIndexText || (extractedSections.hasStructuredSubjectIndex ? (extractedSections.subjectIndexText || "") : ""));
                let adaptationBodyText = String(adaptationText || activeEpisode?.ai_scene_analysis_adaptation || '').trim();
                if (!adaptationBodyText && /(?:###?\s*第二部分[:：]?\s*修改后的剧本|###?\s*Second\s*Part[:：]?\s*Adapted\s*Script|【场景\s*|Scene\s*\d+)/i.test(authoritativeSubjectText)) {
                    adaptationBodyText = String(extractStage1AdaptedScriptBody(authoritativeSubjectText) || '').trim();
                }

                if (adaptationBodyText) {
                    onLog?.(`[Stage 2 Scene Analysis] Extracted optimized script (length: ${adaptationBodyText.length})`);
                }

          onLog?.(`[Stage 3 Asset Design] Initial authoritative text length: ${authoritativeSubjectText.length}`);

        // Try to match the block wrapped by at least 5 dashes: ---------
        if (options?.isRetryPhase2) {
            onLog?.(`[Stage 3 Asset Design] Retry mode enabled. Bypassing asset-index structural check.`);
            // Retry may receive a manually edited Subject Index block without the original Stage 2 wrapper.
            if (!subjectIndexText.trim() && explicitText) {
                const explicitSections = extractAnalysisSections(explicitText);
                subjectIndexText = extractPureSubjectIndexText(explicitSections?.hasStructuredSubjectIndex
                    ? String(explicitSections.subjectIndexText || '').trim()
                    : '');
            }
        } else if (
            String(options.explicitSubjectIndexText || '').trim()
            || subjectIndexText.trim()
            || extractedSections.hasStructuredSubjectIndex
        ) {
            onLog?.(`[Stage 2 Asset Index] Using asset index for Stage 3 (length: ${subjectIndexText.length})`);
        } else if (
            options?.allowWithoutSubjectIndex
            || (
                freeAssetCategoryKeys.every((key) => ['environments', 'props', 'characters'].includes(key))
                && (hasEnvironmentsToDesign() || hasPropExtractForAssetDesign() || hasCharExtractForAssetDesign())
            )
        ) {
            onLog?.('[Stage 3 Asset Design] Subject Index not ready; continuing character / prop / environment design from scene-split extracts.', 'info');
        } else {
            if (freeAssetCategoryKeys.includes('environments')) {
                environmentAssetDesignPendingRef.current = false;
            }
            releaseIncomingAssetLock();
            onLog?.(`[Stage 3 Asset Design] Error: Failed to find the Stage 2 asset index block. Aborting asset design.`, 'error');
            throw new Error(SUBJECT_INDEX_PARSE_ERROR);
        }

        // Persist authoritative Stage 2 outputs so Stage 3 uses the optimized script and asset index as inputs.
        // Asset reruns must treat the Subject Index as read-only input: category/single reruns often pass a filtered
        // index, and writing that back would shrink the persisted Stage 2 asset manifest.
          if (subjectIndexText.trim() || adaptationBodyText.trim()) {
              if (options?.isRetryPhase2) {
                  onLog?.(`[Stage 2 Outputs] Asset rerun uses read-only asset index; skipped Stage 2 writeback (asset_index_len=${subjectIndexText.length}, optimized_script_len=${adaptationBodyText.length})`, 'info');
              } else {
                  if (subjectIndexText.trim()) setSubjectIndexText(extractPureSubjectIndexText(subjectIndexText));
                  if (adaptationBodyText.trim()) setAdaptationText(adaptationBodyText);
                  const updatePayload = {};
                  if (subjectIndexText.trim()) updatePayload.ai_scene_analysis_subject_index = extractPureSubjectIndexText(subjectIndexText).trim();
                  if (adaptationBodyText.trim()) updatePayload.ai_scene_analysis_adaptation = adaptationBodyText.trim();
                  
                  try {
                      await updateEpisode(activeEpisode.id, updatePayload);
                      onLog?.(`[Stage 2 Outputs] Saved asset index and optimized script (asset_index_len=${subjectIndexText.length}, optimized_script_len=${adaptationBodyText.length})`);
                  } catch (error) {
                      onLog?.(`[Stage 2 Outputs] Warning: Failed to save asset index / optimized script: ${error.message}`);
                  }
              }
          }

        if (!subjectIndexText.trim() || !hasSubjectIndexStructure(subjectIndexText)) {
            if (
                options?.allowWithoutSubjectIndex
                || (
                    freeAssetCategoryKeys.every((key) => ['environments', 'props', 'characters'].includes(key))
                    && (hasEnvironmentsToDesign() || hasPropExtractForAssetDesign() || hasCharExtractForAssetDesign())
                )
            ) {
                onLog?.('[Stage 3 Asset Design] Missing Subject Index; character / prop / environment design uses scene-split extracts.', 'info');
            } else {
                if (freeAssetCategoryKeys.includes('environments')) {
                    environmentAssetDesignPendingRef.current = false;
                }
                releaseIncomingAssetLock();
                onLog?.('[Stage 3 Asset Design] Error: Missing usable Subject Index. Aborting asset design.', 'error');
                throw new Error(t(
                    '缺少资产清单（Subject Index），无法继续资产生成。请先完成第二阶段资产提取后再重试。',
                    'Missing Subject Index asset inventory. Complete Stage 2.1 asset extraction before asset generation.'
                ));
            }
        }

        // Full pipeline and supervisor repair: drop Subject Index rows already in the entity table.
        // Manual category rerun passes skipExistingAssets:false (or omits it with isRetryPhase2).
        if (options?.envScope) {
            subjectIndexText = filterSubjectIndexTextByEnvironmentScope(subjectIndexText, options.envScope);
        }
        let subjectIndexTextForDesign = subjectIndexText;
        if (skipExistingAssets && projectId && activeEpisode?.id && typeof fetchEntities === 'function') {
            if (options?.isRetryPhase2) {
                onLog?.(
                    '[Stage 3 Asset Design] Repair pass keeps skipExistingAssets=true; already-imported environments will not be redesigned.',
                    'info'
                );
            }
            try {
                const existingEntities = await fetchEntities(projectId, {
                    episode_id: Number(activeEpisode.id) || undefined,
                }).catch(() => []);
                const existingNames = buildExistingEntityNameSet(existingEntities);
                const filteredExisting = filterSubjectIndexExcludingExistingEntities(
                    subjectIndexTextForDesign,
                    existingNames
                );
                if (filteredExisting.skippedRows > 0) {
                    onLog?.(
                        t(
                            `[Stage 3 Asset Design] 预查实体表：已跳过 ${filteredExisting.skippedRows}/${filteredExisting.totalRows} 条已存在资产，保留 ${filteredExisting.keptRows} 条待设计`,
                            `[Stage 3 Asset Design] Entity precheck: skipped ${filteredExisting.skippedRows}/${filteredExisting.totalRows} existing asset row(s); ${filteredExisting.keptRows} remain for design`
                        ),
                        'info'
                    );
                    subjectIndexTextForDesign = filteredExisting.text;
                }
                const requestedTypes = Array.isArray(options?.targetEntityTypes)
                    ? options.targetEntityTypes.map((item) => String(item || '').trim().toLowerCase()).filter(Boolean)
                    : [];
                const extractSourceCandidates = [
                    options?.extractSourceText,
                    explicitText,
                    latestStage1NodeOutputsRef.current?.scene_split,
                    typeof getStageOutputContent === 'function' ? getStageOutputContent('stage1', 'scene_split') : '',
                    latestStage1RawTextRef.current,
                    adaptationText,
                    activeEpisode?.ai_scene_analysis_adaptation,
                    activeEpisode?.ai_scene_analysis_result,
                    ...collectStage1SlotTexts(activeEpisode?.ai_stage_outputs),
                ];
                const extractSourceText = (
                    (requestedTypes.includes('characters') && resolveCategoryAssetSourceText(extractSourceCandidates, 'characters'))
                    || (requestedTypes.includes('props') && resolveCategoryAssetSourceText(extractSourceCandidates, 'props'))
                    || (requestedTypes.some((item) => ['environments', 'posters', 'covers'].includes(String(item || '').trim().toLowerCase()))
                        && resolveCategoryAssetSourceText(extractSourceCandidates, 'environments'))
                    || resolveCategoryAssetSourceText(extractSourceCandidates, '')
                    || String(options?.extractSourceText || explicitText || latestStage1NodeOutputsRef.current?.scene_split || '').trim()
                );
                const wantsCharacters = requestedTypes.length === 0 || requestedTypes.includes('characters');
                const wantsProps = requestedTypes.length === 0 || requestedTypes.includes('props');
                const wantsEnvironments = requestedTypes.length === 0
                    || requestedTypes.includes('environments')
                    || Boolean(options?.deferEnvironmentDesign);
                const envStillNeededFromPlan = (
                    wantsEnvironments
                    && hasEnvironmentPlanForAssetDesign(extractSourceText)
                    && !(
                        skipExistingAssets
                        && !options?.forceAssetDesign
                        && hasPersistedEnvironmentAssetDesign(existingEntities)
                    )
                );
                const charStillNeededFromExtract = (
                    wantsCharacters
                    && hasCharExtractForAssetDesign(extractSourceText)
                    && !(skipExistingAssets && !options?.forceAssetDesign && hasPersistedCharacterAssetDesign(existingEntities))
                );
                const propStillNeededFromExtract = (
                    wantsProps
                    && hasPropExtractForAssetDesign(extractSourceText)
                    && !(skipExistingAssets && !options?.forceAssetDesign && hasPersistedPropAssetDesign(existingEntities))
                );
                if (
                    filteredExisting.totalRows > 0
                    && filteredExisting.keptRows <= 0
                    && (envStillNeededFromPlan || charStillNeededFromExtract || propStillNeededFromExtract)
                ) {
                    onLog?.(
                        t(
                            '[Stage 3 Asset Design] 旧资产清单行均已入库，仍按全局统筹提取 / 环境规划继续本轮资产设计。',
                            '[Stage 3 Asset Design] Leftover Subject Index rows already exist; continuing this-run design from scene-split extracts / environment plan.'
                        ),
                        'info'
                    );
                } else if (filteredExisting.totalRows > 0 && filteredExisting.keptRows <= 0) {
                    onLog?.(
                        t(
                            '[Stage 3 Asset Design] 本集资产均已存在于实体表，跳过资产设计 LLM。',
                            '[Stage 3 Asset Design] All episode assets already exist in entities table; skipping asset-design LLM.'
                        ),
                        'success'
                    );
                    if (freeAssetCategoryKeys.includes('environments') && !envStillNeededFromPlan) {
                        markEnvironmentAssetDesignReady('assets-all-existing');
                    }
                    if (!allowRepeatAutoStage3 && episodeIdForPhase2 > 0 && !options?.deferEnvironmentDesign) {
                        phase2AutoCompletedEpisodeRef.current = episodeIdForPhase2;
                    }
                    releaseIncomingAssetLock();
                    return {
                        ...emptyReport,
                        skippedExistingAssets: true,
                        skippedExistingAssetRows: filteredExisting.skippedRows,
                    };
                }
            } catch (precheckErr) {
                onLog?.(
                    t(
                        `[Stage 3 Asset Design] 实体预查失败，继续完整资产设计：${precheckErr?.message || precheckErr}`,
                        `[Stage 3 Asset Design] Entity precheck failed; continuing full asset design: ${precheckErr?.message || precheckErr}`
                    ),
                    'warning'
                );
            }
        }

        if (options?.isRetryPhase2) {
            setIsRetryingPhase2(true);
        }



        const getAssetDesignTaskLabel = (key) => {
            const labels = {
                characters: t('角色', 'Characters'),
                props: t('道具', 'Props'),
                environments: t('环境/封面', 'Environments / Cover'),
                posters: t('环境/封面', 'Environments / Cover'),
            };
            return labels[key] || String(key || '');
        };

        const describeAssetFailureReason = (rawReason) => {
            const reason = String(rawReason || '').trim();
            if (!reason) return t('原因未知', 'unknown reason');
            const map = [
                [/llm_json_not_parsed/i, t('AI已返回但未解析到可入库JSON', 'AI returned but no importable JSON parsed')],
                [/truncated_result_missing_subjects_json/i, t('结果被截断且缺少结构化资产', 'result truncated without structured assets')],
                [/truncated_result_empty_subjects/i, t('结果被截断且资产为空', 'result truncated with empty assets')],
                [/import produced zero created\/skipped rows/i, t('导入结果为0条', 'import produced 0 rows')],
                [/import returned non-object result/i, t('导入未返回有效结果', 'import returned invalid result')],
                [/No supported format detected/i, t('未识别到可导入的资产格式', 'no importable asset format detected')],
                [/missing_result/i, t('未收到分类结果', 'missing category result')],
                [/not_persisted/i, t('未写入实体库', 'not persisted to entity library')],
                [/llm_failed/i, t('AI任务失败', 'AI task failed')],
            ];
            for (const [pattern, label] of map) {
                if (pattern.test(reason)) return label;
            }
            // "characters:some detail" → keep detail, drop english key prefix when possible
            const stripped = reason.replace(/^(characters|props|environments|posters)\s*[:：]\s*/i, '');
            return stripped || reason;
        };

        const formatAssetCategoryFailureLine = (key, settled) => {
            const label = getAssetDesignTaskLabel(key);
            if (!settled) return t(`${label}：未收到结果`, `${label}: no result`);
            if (settled.status === 'rejected') {
                const detail = describeAssetFailureReason(settled.reason?.message || settled.reason || 'llm_failed');
                return t(`${label}：${detail}`, `${label}: ${detail}`);
            }
            const value = settled.value || {};
            if (value.skippedExisting) return '';
            const err = String(value.subtaskImportError || '').trim();
            if (err) return t(`${label}：${describeAssetFailureReason(err)}`, `${label}: ${describeAssetFailureReason(err)}`);
            if (!value.hasImportableSubjects) {
                return t(`${label}：AI已返回但未解析到可入库JSON`, `${label}: AI returned but no importable JSON parsed`);
            }
            return t(`${label}：未写入实体库`, `${label}: not persisted`);
        };

        const logAssetImportFailureDiagnostic = (key, {
            traceId = '',
            importReport = null,
            importError = '',
            subjectsPayload = null,
            phase = 'import',
        } = {}) => {
            const label = getAssetDesignTaskLabel(key);
            const counts = importReport?.importedSubjectCounts || {};
            const created = Number(importReport?.createdSubjectItems?.length || 0);
            const skipped = Number(importReport?.skippedSubjectItems?.length || 0);
            const failedItems = Array.isArray(importReport?.failedSubjectItems) ? importReport.failedSubjectItems : [];
            const planned = {
                characters: Array.isArray(subjectsPayload?.characters) ? subjectsPayload.characters.length : 0,
                props: Array.isArray(subjectsPayload?.props) ? subjectsPayload.props.length : 0,
                environments: Array.isArray(subjectsPayload?.environments) ? subjectsPayload.environments.length : 0,
                posters: (Array.isArray(subjectsPayload?.posters) ? subjectsPayload.posters.length : 0)
                    + (Array.isArray(subjectsPayload?.covers) ? subjectsPayload.covers.length : 0),
            };
            const failPreview = failedItems
                .slice(0, 8)
                .map((item) => `${item?.type || '?'}:${item?.name || '(unnamed)'}=${item?.reason || '?'}`)
                .join('；');
            const reason = String(
                importError
                || importReport?.reason
                || (failedItems.length ? `create_failed:${failedItems.length}` : '')
                || 'import produced zero created/skipped rows'
            ).trim();
            onLog?.(
                t(
                    `[资产入库失败] ${label} phase=${phase}`
                    + ` reason=${describeAssetFailureReason(reason)}`
                    + ` planned=角色${planned.characters}/道具${planned.props}/环境${planned.environments}/海报${planned.posters}`
                    + ` created=${created} skipped=${skipped} failed=${failedItems.length}`
                    + ` counts=c${Number(counts.character || 0)}/p${Number(counts.prop || 0)}/e${Number(counts.environment || 0)}/po${Number(counts.poster || 0)}`
                    + ` source=${String(importReport?.importDiagnostics?.entitiesPayloadSource || 'n/a')}`
                    + (traceId ? ` trace=${traceId}` : '')
                    + (failPreview ? ` detail=${failPreview}` : ''),
                    `[Asset Import Failure] ${label} phase=${phase}`
                    + ` reason=${describeAssetFailureReason(reason)}`
                    + ` planned=char${planned.characters}/prop${planned.props}/env${planned.environments}/poster${planned.posters}`
                    + ` created=${created} skipped=${skipped} failed=${failedItems.length}`
                    + ` source=${String(importReport?.importDiagnostics?.entitiesPayloadSource || 'n/a')}`
                    + (traceId ? ` trace=${traceId}` : '')
                    + (failPreview ? ` detail=${failPreview}` : '')
                ),
                'error'
            );
        };

        const buildAssetReadyHint = (taskKey) => {
            const label = getAssetDesignTaskLabel(taskKey);
            if (!label) return '';
            return t(
                `「${label}」已入库，可前往资产库开始生成`,
                `"${label}" is ready — open the Assets library to start generation`
            );
        };

        const buildAssetProgressMessage = ({
            persistedKeys = [],
            llmDoneKeys = [],
            pendingKeys = [],
            failureLines = [],
            retryRound = 0,
            stopped = false,
        } = {}) => {
            const persistedLabels = persistedKeys.map(getAssetDesignTaskLabel).filter(Boolean);
            const pendingLabels = pendingKeys.map(getAssetDesignTaskLabel).filter(Boolean);
            const llmOnlyKeys = llmDoneKeys.filter((key) => !persistedKeys.includes(key) && pendingKeys.includes(key));
            const llmOnlyLabels = llmOnlyKeys.map(getAssetDesignTaskLabel).filter(Boolean);
            const parts = [];
            if (persistedLabels.length) {
                parts.push(t(`已入库：${persistedLabels.join('、')}`, `Imported: ${persistedLabels.join(', ')}`));
            }
            // Prefer concrete failure lines over the softer "awaiting import" wording.
            if (llmOnlyLabels.length && failureLines.length === 0) {
                parts.push(t(`已交稿待入库：${llmOnlyLabels.join('、')}`, `LLM done, awaiting import: ${llmOnlyLabels.join(', ')}`));
            }
            const stillRunning = pendingKeys.filter((key) => !llmDoneKeys.includes(key) && !persistedKeys.includes(key));
            const runningLabels = stillRunning.map(getAssetDesignTaskLabel).filter(Boolean);
            if (runningLabels.length && retryRound <= 1 && !stopped && failureLines.length === 0) {
                parts.push(t(`推演中：${runningLabels.join('、')}`, `Generating: ${runningLabels.join(', ')}`));
            }
            if (failureLines.length) {
                parts.push(failureLines.join('；'));
            } else if (pendingLabels.length && retryRound > 1) {
                parts.push(t(`待重试：${pendingLabels.join('、')}`, `Retrying: ${pendingLabels.join(', ')}`));
            }
            const head = stopped
                ? t('资产设计入库未完成，已停止自动重试', 'Asset design import incomplete; auto-retry stopped')
                : (retryRound > 1
                    ? t(`资产设计按类重试入库（第 ${retryRound} 轮）`, `Asset design category import retry (round ${retryRound})`)
                    : t('资产设计进行中', 'Asset design in progress'));
            return `${head}${parts.length ? ` — ${parts.join('；')}` : ''}`;
        };

        const promptFilesRaw = [


            { key: 'characters', nodeKey: 'asset_design_character', path: 'skills/scene_analysis_feature_stack/entity_design_character.md' },


            { key: 'environments', nodeKey: 'asset_design_environment', path: 'skills/scene_analysis_feature_stack/entity_design_environment_and_poster.md' },


            { key: 'props', nodeKey: 'asset_design_prop', path: 'skills/scene_analysis_feature_stack/entity_design_prop.md' }


        ];



        const normalizeTargetEntityTypeKey = (value) => {
            const key = String(value || '').trim().toLowerCase();
            if (!key) return '';
            if (['character', 'characters', 'role', 'roles', '人物', '角色'].includes(key)) return 'characters';
            if (['prop', 'props', 'item', 'items', '道具', '物件'].includes(key)) return 'props';
            if (['environment', 'environments', 'env', 'scene', 'scenes', '场景', '环境'].includes(key)) return 'environments';
            if (['poster', 'posters', 'cover', 'covers', 'cover_poster', '海报', '封面'].includes(key)) return key === 'covers' ? 'covers' : 'posters';
            return key;
        };

        let targetFilters = Array.isArray(options.targetEntityTypes)
            ? Array.from(new Set(options.targetEntityTypes.map(normalizeTargetEntityTypeKey).filter(Boolean)))
            : null;
        if (targetFilters && targetFilters.some(isEnvPosterTargetKey)) {
            targetFilters = coupleEnvPosterTargetFilters(targetFilters);
        }
        const requestedTargetFilters = targetFilters ? [...targetFilters] : null;



        let stage3AutoStart = {
            asset_design_character: true,
            asset_design_prop: true,
            asset_design_environment: true,
        };
        if (!targetFilters) {
            try {
                const flowRegistry = await getSceneAnalysisFlowRegistry();
                const configured = flowRegistry?.stage3_auto_start || flowRegistry?.config?.stage3_auto_start || {};
                // Prefer explicit false from config; missing keys stay on (defaults above).
                stage3AutoStart = {
                    asset_design_character: configured?.asset_design_character !== false,
                    asset_design_prop: configured?.asset_design_prop !== false,
                    asset_design_environment: configured?.asset_design_environment !== false,
                };
                onLog?.(`[Stage 3 Asset Design] Loaded auto-start config: character=${stage3AutoStart.asset_design_character ? 'on' : 'off'}, prop=${stage3AutoStart.asset_design_prop ? 'on' : 'off'}, environment=${stage3AutoStart.asset_design_environment ? 'on' : 'off'}`, 'info');
            } catch (flowErr) {
                onLog?.(`[Stage 3 Asset Design] Failed to load flow auto-start config; using defaults. ${flowErr?.message || flowErr}`, 'warning');
            }
        }

        // Character / prop design start from scene_split extracts.
        // Main-environment design starts from the environment plan.
        const promptFiles = promptFilesRaw.filter(p => {
            if (!freeAssetCategoryKeys.includes(p.key)) return false;
            if (targetFilters) return targetFilters.includes(p.key);
            return stage3AutoStart[p.nodeKey] !== false;
        });

        if (!targetFilters && promptFiles.length === 0) {
            onLog?.('[Stage 3 Asset Design] All Stage 3 auto-start switches are disabled; skipping automatic asset design.', 'info');
            markEnvironmentAssetDesignReady('stage3-auto-start-all-off');
            if (!allowRepeatAutoStage3 && episodeIdForPhase2 > 0) {
                phase2AutoCompletedEpisodeRef.current = episodeIdForPhase2;
            }
            releaseIncomingAssetLock();
            return emptyReport;
        }
        if (!promptFiles.some((p) => p.key === 'environments')) {
            if (phase2InFlightCategoriesRef.current.has('environments') || environmentAssetDesignPendingRef.current) {
                onLog?.(
                    t(
                        '[Stage 3 Asset Design] 本批不含环境；主环境设计已在环境规划完成后启动，门闩保持锁定。',
                        '[Stage 3 Asset Design] This batch excludes environments; main-environment design already started after planning, ENV gate stays armed.'
                    ),
                    'info'
                );
            } else if (!targetFilters) {
                markEnvironmentAssetDesignReady('env-auto-start-off');
            }
        }


        const targetAssetsCount = promptFiles.length;
        const runningAssetTaskLabels = promptFiles.map((p) => getAssetDesignTaskLabel(p.key)).filter(Boolean).join('、');
        const promptKeyToLiveAssetKey = (key) => (
            key === 'characters' ? 'character' : (key === 'props' ? 'prop' : (key === 'environments' ? 'environment' : ''))
        );
        // Merge, do not replace: character/prop and environment start in separate
        // invocations. Replacing (or finally-clearing all keys) hides the other
        // category's processing / completion node.
        const launchedLiveKeys = promptFiles
            .map((item) => promptKeyToLiveAssetKey(item.key))
            .filter(Boolean);
        setLiveAssetDesignTaskKeys((prev) => {
            const next = new Set(Array.isArray(prev) ? prev : []);
            launchedLiveKeys.forEach((key) => next.add(key));
            return [...next];
        });



        setAnalysisFlowStatus({
            phase: "assets_gen",
            assetsGenSettled: false,
            message: t(
                `✨ 正在执行第四阶段资产设计 (共 ${targetAssetsCount} 项并发推演${runningAssetTaskLabels ? `：${runningAssetTaskLabels}` : ''})...`,
                `Running Stage 4 asset design (${targetAssetsCount} tasks${runningAssetTaskLabels ? `: ${runningAssetTaskLabels.replace(/、/g, ', ')}` : ''})...`
            ),
        });



        let assetsGenCompletedCount = 0;
        const assetsGenCompletedKeys = []; // persisted / skipped-existing only
        const assetsLlmDoneKeys = [];
        let assetRetryRound = 0;
        let assetPromptKeysSnapshot = [];



        try {
            throwIfAnalysisStopped();


            onLog?.(`[Stage 3 Asset Design] Preparing to fetch ${targetAssetsCount} entity_design prompts`);



            const commonPromptRes = await fetchPrompt("skills/scene_analysis_feature_stack/entity_design_common.md").catch(() => null);
            const commonPromptContent = commonPromptRes?.content || "";

            const promptsData = await Promise.all(
                promptFiles.map(async p => ({
                    ...p,
                    content: commonPromptContent + "\n\n" + ((await fetchPrompt(p.path).catch(() => null))?.content || "")
                }))
            );
            assetPromptKeysSnapshot = promptsData.map((item) => item?.key).filter(Boolean);

            const refreshAssetDesignProgressStatus = ({
                pendingKeys = null,
                failureLines = null,
                stopped = false,
                highlightHint = '',
            } = {}) => {
                const pending = Array.isArray(pendingKeys)
                    ? pendingKeys.filter(Boolean)
                    : assetPromptKeysSnapshot.filter((key) => !assetsGenCompletedKeys.includes(key));
                const allPersisted = assetPromptKeysSnapshot.length > 0
                    && assetPromptKeysSnapshot.every((key) => assetsGenCompletedKeys.includes(key));
                const progressMessage = buildAssetProgressMessage({
                    persistedKeys: [...assetsGenCompletedKeys],
                    llmDoneKeys: [...assetsLlmDoneKeys],
                    pendingKeys: pending,
                    failureLines: Array.isArray(failureLines) ? failureLines.filter(Boolean) : [],
                    retryRound: assetRetryRound,
                    stopped,
                });
                setAnalysisFlowStatus((prev) => {
                    const prevPhase = String(prev?.phase || '').trim().toLowerCase();
                    const preserveLivePhase = Boolean(options?.isRetryPhase2 && analysisRunInFlightRef.current)
                        && prevPhase
                        && !['idle', 'failed', 'assets_gen'].includes(prevPhase);
                    return {
                        ...(prev && typeof prev === 'object' ? prev : {}),
                        phase: preserveLivePhase ? prevPhase : 'assets_gen',
                        assetsGenSettled: allPersisted && !stopped,
                        message: preserveLivePhase ? (String(prev?.message || '').trim() || progressMessage) : progressMessage,
                        highlightHint: highlightHint || (preserveLivePhase ? progressMessage : String(prev?.highlightHint || '')),
                    };
                });
            };

            const markAssetCategoryPersisted = (key, { highlightHint = '' } = {}) => {
                const stableKey = String(key || '').trim();
                if (!stableKey) return;
                if (!assetsGenCompletedKeys.includes(stableKey)) {
                    assetsGenCompletedKeys.push(stableKey);
                }
                assetsGenCompletedCount = assetsGenCompletedKeys.length;
                refreshAssetDesignProgressStatus({
                    pendingKeys: assetPromptKeysSnapshot.filter((k) => !assetsGenCompletedKeys.includes(k)),
                    highlightHint,
                });
                void refreshEpisodeOwnedEntities();
            };

            const pureSubjectIndexText = extractPureSubjectIndexText(subjectIndexTextForDesign);
            
            const designProjectContextSection = buildStage1ProjectContextSection()
                .replace('Project Context (prepend and treat as high-priority constraints):', 'Project Context (prepend and treat as high-priority constraints for generating design assets):')
                .replace('Use this project context as first-class constraints before analyzing the script.', 'Use this project context as first-class constraints before generating the subjects.');

            const subjectIndexNameLockSection = [
                '[Subject Index Name Lock - ABSOLUTE]',
                'Output name / name_en / base_name_en and every CHAR:/ENV:/PROP: name inside visual_dependencies MUST be character-identical to Subject Index subject_name_zh / subject_name_en.',
                'Forbidden: any rename, polish, normalize, translate, abbreviate, synonym, punctuation/space/case fix, merge, split, or invent. Mismatch = discard and rewrite the entity.',
            ].join('\n');

            const finalSubjectIndexText = [
                designProjectContextSection || null,
                subjectIndexNameLockSection,
                wrapInjectionSection('Subject Index', pureSubjectIndexText),
            ].filter(Boolean).join('\n\n');

            onLog?.(`[Stage 3 Asset Design] Launching ${targetAssetsCount} concurrent asset-design LLM call(s): ${promptFiles.map((p) => `${p.key}→${p.nodeKey}`).join(', ') || 'none'}.`);

            const scriptAnalysisApiId = resolveSelectedScriptAnalysisApiId();
            if (scriptAnalysisApiId) {
                onLog?.(`[Stage 3 Asset Design] Using script analysis API dropdown system_api_id=${scriptAnalysisApiId}.`, 'info');
            } else {
                onLog?.('[Stage 3 Asset Design] Script analysis API dropdown is empty; fallback routing may select a different API.', 'warning');
            }

            const phase2StartedAt = Date.now();
            const phase2BatchTraceId = `phase2-assets-${activeEpisode?.id || 'noep'}-${phase2StartedAt}`;

            const hasAnySubjects = (payload) => {
                if (!payload || typeof payload !== 'object') return false;
                return (
                    (Array.isArray(payload.characters) && payload.characters.length > 0)
                    || (Array.isArray(payload.props) && payload.props.length > 0)
                    || (Array.isArray(payload.environments) && payload.environments.length > 0)
                    || (Array.isArray(payload.posters) && payload.posters.length > 0)
                    || (Array.isArray(payload.covers) && payload.covers.length > 0)
                );
            };

            const buildSubtaskSubjectsPayload = (key, sourcePayload) => {
                const input = normalizePosterBucketsInSubjectsPayload(
                    (sourcePayload && typeof sourcePayload === 'object') ? sourcePayload : {}
                );
                const payload = { characters: [], environments: [], props: [], posters: [], covers: [] };
                if (key === 'characters') {
                    payload.characters = Array.isArray(input.characters) ? input.characters : [];
                } else if (key === 'props') {
                    payload.props = Array.isArray(input.props) ? input.props : [];
                } else if (key === 'environments') {
                    payload.environments = Array.isArray(input.environments) ? input.environments : [];
                    payload.posters = Array.isArray(input.posters) ? input.posters : [];
                    payload.covers = Array.isArray(input.covers) ? input.covers : [];
                } else if (key === 'posters') {
                    payload.posters = Array.isArray(input.posters) ? input.posters : [];
                    payload.covers = Array.isArray(input.covers) ? input.covers : [];
                } else {
                    payload.characters = Array.isArray(input.characters) ? input.characters : [];
                    payload.props = Array.isArray(input.props) ? input.props : [];
                    payload.environments = Array.isArray(input.environments) ? input.environments : [];
                    payload.posters = Array.isArray(input.posters) ? input.posters : [];
                    payload.covers = Array.isArray(input.covers) ? input.covers : [];
                }

                const payloadTargetFilters = coupleEnvPosterTargetFilters(
                    Array.isArray(requestedTargetFilters) && requestedTargetFilters.length > 0
                        ? requestedTargetFilters
                        : targetFilters
                );
                if (Array.isArray(payloadTargetFilters) && payloadTargetFilters.length > 0) {
                    const filtered = { characters: [], environments: [], props: [], posters: [], covers: [] };
                    if (payloadTargetFilters.includes('characters')) filtered.characters = payload.characters;
                    if (payloadTargetFilters.includes('props')) filtered.props = payload.props;
                    if (payloadTargetFilters.includes('environments') || payloadTargetFilters.some(isEnvPosterTargetKey)) {
                        filtered.environments = payload.environments;
                    }
                    if (payloadTargetFilters.some(isEnvPosterTargetKey)) {
                        filtered.posters = payload.posters;
                        filtered.covers = payload.covers;
                    }
                    return filtered;
                }
                return payload;
            };

                        // Run character / prop / environment concurrently (Promise.allSettled).
            // Each category binds episode_id so pipeline status + subject-index gates work for all three;
            // skip_episode_persist avoids concurrent overwrite of ai_entity_design_result (frontend merges).
            // Failed / incomplete categories auto-retry until DB coverage, user stop, or pipeline timeout.
            const episodeIdForAssetSubtasks = activeEpisode?.id || null;
            const runOneAssetSubtask = async (pData, index, roundTag = '') => {
                    throwIfAnalysisStopped();
                    const subtaskTraceId = `${phase2BatchTraceId}-${pData.key || `slot${index + 1}`}${roundTag}`;
                    const subtaskImportSessionId = `import-${subtaskTraceId}`;
                    onLog?.(`[Stage 3 Asset Design] Subtask submit key=${pData.key || `slot${index + 1}`} trace_id=${subtaskTraceId}`, 'info');

                    let specificSubjectIndexText = finalSubjectIndexText;

                    const filteredSubjectIndex = filterSubjectIndexTextForAssetTask(specificSubjectIndexText, pData.key, requestedTargetFilters);
                    specificSubjectIndexText = filteredSubjectIndex.text;
                    if (filteredSubjectIndex.totalRows > 0) {
                        onLog?.(`[Stage 3 Asset Design] Subject Index filtered key=${pData.key || `slot${index + 1}`} kept=${filteredSubjectIndex.keptRows}/${filteredSubjectIndex.totalRows}`, 'info');
                    }
                    // Skip empty category (no rows of this type, or all already in DB).
                    // Environment design no longer requires Index ENV rows — the environment plan is enough.
                    const extractSourceCandidates = [
                        options?.extractSourceText,
                        explicitText,
                        latestStage1NodeOutputsRef.current?.scene_split,
                        typeof getStageOutputContent === 'function' ? getStageOutputContent('stage1', 'scene_split') : '',
                        latestStage1RawTextRef.current,
                        adaptationText,
                        activeEpisode?.ai_scene_analysis_adaptation,
                        activeEpisode?.ai_scene_analysis_result,
                        ...collectStage1SlotTexts(activeEpisode?.ai_stage_outputs),
                    ];
                    const extractSourceText = resolveCategoryAssetSourceText(extractSourceCandidates, pData.key)
                        || String(
                            options?.extractSourceText
                            || explicitText
                            || latestStage1NodeOutputsRef.current?.scene_split
                            || ''
                        ).trim();
                    const categoryBriefText = resolveCategoryAssetBriefText(extractSourceText, pData.key);
                    const nodeInputText = String(
                        categoryBriefText
                        || ((pData.key === 'characters' || pData.key === 'props')
                            ? ''
                            : (extractSourceText || specificSubjectIndexText))
                        || ''
                    ).trim();
                    if ((pData.key === 'characters' || pData.key === 'props') && nodeInputText) {
                        onLog?.(
                            `[Stage 3 Asset Design] ${pData.key} extract brief chars=${nodeInputText.length} start=${/\[(?:CHAR|PROP)_EXTRACT_START/i.test(nodeInputText)}`,
                            'info'
                        );
                    }
                    const envDesignHasPlanSource = pData.key === 'environments'
                        && hasEnvironmentPlanForAssetDesign(extractSourceText)
                        && !(skipExistingAssets && !options?.forceAssetDesign && hasPersistedEnvironmentAssetDesign());
                    const propDesignHasPlanSource = pData.key === 'props'
                        && hasPropExtractForAssetDesign(extractSourceText)
                        && !(skipExistingAssets && !options?.forceAssetDesign && hasPersistedPropAssetDesign());
                    const charDesignHasPlanSource = pData.key === 'characters'
                        && hasCharExtractForAssetDesign(extractSourceText)
                        && !(skipExistingAssets && !options?.forceAssetDesign && hasPersistedCharacterAssetDesign());
                    if (filteredSubjectIndex.keptRows <= 0 && !envDesignHasPlanSource && !propDesignHasPlanSource && !charDesignHasPlanSource) {
                        if (pData.key === 'environments' && hasUnimportedDesignedCoverPoster()) {
                            const persistedPayload = getAnalysisEntitiesPayloadFromJsonText(
                                activeEpisode?.ai_entity_design_result || llmAssetRawResultContent || ''
                            ) || {};
                            const posterPayload = buildSubtaskSubjectsPayload('environments', persistedPayload);
                            if (countDesignedCoverPosterItems(posterPayload) > 0) {
                                onLog?.(
                                    t(
                                        '[Stage 3 Asset Design] 主环境已入库，正在补导入已生成的封面海报。',
                                        '[Stage 3 Asset Design] Main environment already exists; importing the designed cover poster.'
                                    ),
                                    'info'
                                );
                                try {
                                    const posterImportReport = await importSubjectsJsonWithDedupe(
                                        JSON.stringify(posterPayload, null, 2),
                                        {
                                            reason: `phase2-subtask-environments-poster-backfill`,
                                            subjectsJson: posterPayload,
                                            forceRetry: true,
                                            importOptions: {
                                                onLog,
                                                projectId,
                                                episodeId: activeEpisode?.id,
                                                importSessionId: `${subtaskImportSessionId}-poster-backfill`,
                                                targetEntityTypes: [...ENV_POSTER_TARGET_KEYS],
                                                overwriteExistingSubjects,
                                                suppressAlerts: true,
                                                forceRetry: true,
                                            },
                                        }
                                    );
                                    if (reportImportedPosterCount(posterImportReport) > 0) {
                                        if (pData.key && !assetsLlmDoneKeys.includes(pData.key)) {
                                            assetsLlmDoneKeys.push(pData.key);
                                        }
                                        markAssetCategoryPersisted(pData.key, {
                                            highlightHint: buildAssetReadyHint(pData.key),
                                        });
                                        markEnvironmentAssetDesignReady(`env-poster-backfill:${subtaskTraceId}`);
                                        return {
                                            key: pData.key,
                                            traceId: subtaskTraceId,
                                            importSessionId: subtaskImportSessionId,
                                            result: null,
                                            analysisText: '',
                                            subjectsJson: posterPayload,
                                            hasImportableSubjects: true,
                                            subtaskImportReport: posterImportReport,
                                            subtaskImportError: '',
                                            skippedExisting: false,
                                        };
                                    }
                                } catch (posterBackfillErr) {
                                    onLog?.(
                                        `[Stage 3 Asset Design] Cover poster backfill failed: ${posterBackfillErr?.message || posterBackfillErr}`,
                                        'warning'
                                    );
                                }
                            }
                        }
                        const skippedLiveKey = promptKeyToLiveAssetKey(pData.key);
                        if (skippedLiveKey) {
                            setLiveAssetDesignTaskKeys((prev) => prev.filter((item) => item !== skippedLiveKey));
                        }
                        onLog?.(
                            t(
                                `[Stage 3 Asset Design] ${getAssetDesignTaskLabel(pData.key)} 无需生成（索引无待设计行或均已存在），跳过 LLM`,
                                `[Stage 3 Asset Design] ${getAssetDesignTaskLabel(pData.key)} has no pending rows; skipping LLM`
                            ),
                            'info'
                        );
                        const envSkipHasMain = pData.key !== 'environments'
                            || hasPersistedEnvironmentAssetDesign();
                        if (envSkipHasMain && pData.key && !assetsLlmDoneKeys.includes(pData.key)) {
                            assetsLlmDoneKeys.push(pData.key);
                        }
                        if (envSkipHasMain) {
                            markAssetCategoryPersisted(pData.key, {
                                highlightHint: buildAssetReadyHint(pData.key),
                            });
                        }
                        if (pData.key === 'environments' && envSkipHasMain) {
                            markEnvironmentAssetDesignReady(`env-skip-existing:${subtaskTraceId}`);
                        } else if (pData.key === 'environments') {
                            onLog?.(
                                t(
                                    '[Stage 3 Asset Design] 库中只有衍生环境、没有主环境，不能把环境设计标为完成。',
                                    '[Stage 3 Asset Design] Only derived environments exist; main-environment design is not complete.'
                                ),
                                'warning'
                            );
                        }
                        return {
                            key: pData.key,
                            traceId: subtaskTraceId,
                            importSessionId: subtaskImportSessionId,
                            result: null,
                            analysisText: '',
                            subjectsJson: null,
                            hasImportableSubjects: false,
                            subtaskImportReport: null,
                            subtaskImportError: '',
                            skippedExisting: true,
                        };
                    }
                    const subtaskRequestedTargets = pData.key === 'characters'
                        ? ['characters']
                        : (pData.key === 'props'
                            ? ['props']
                            : (pData.key === 'environments' ? ['environments', 'posters', 'covers'] : []));
                    const sceneAnalysisModeForSubtask = `2_pass_generate_assets_${pData.key}${subtaskRequestedTargets.length ? `__targets_${subtaskRequestedTargets.join('_')}` : ''}`;
                    const assetNodeKey = pData.nodeKey
                        || (pData.key === 'characters'
                            ? 'asset_design_character'
                            : (pData.key === 'props' ? 'asset_design_prop' : 'asset_design_environment'));
                    const liveKey = promptKeyToLiveAssetKey(pData.key);
                    if (liveKey) {
                        setLiveAssetDesignTaskKeys((prev) => (prev.includes(liveKey) ? prev : [...prev, liveKey]));
                    }
                    const extractTag = pData.key === 'characters' ? 'CHAR' : (pData.key === 'props' ? 'PROP' : '');
                    const extractIsEmpty = Boolean(extractTag) && (
                        !nodeInputText
                        || taggedExtractIsExplicitNone(nodeInputText, extractTag)
                        || !textHasTaggedExtractItems(nodeInputText, extractTag)
                    );
                    if ((pData.key === 'characters' || pData.key === 'props') && extractIsEmpty) {
                        onLog?.(
                            t(
                                `[Stage 3 Asset Design] ${getAssetDesignTaskLabel(pData.key)} 本次提取为「无」，已跳过 LLM`,
                                `[Stage 3 Asset Design] ${getAssetDesignTaskLabel(pData.key)} extract is none; skipping LLM`
                            ),
                            'info'
                        );
                        return {
                            key: pData.key,
                            traceId: subtaskTraceId,
                            importSessionId: subtaskImportSessionId,
                            result: null,
                            analysisText: '',
                            subjectsJson: null,
                            hasImportableSubjects: false,
                            subtaskImportReport: null,
                            subtaskImportError: 'empty extract',
                            skippedExisting: false,
                        };
                    }

                    return awaitAnalyzeSceneWithRecovery(
                        () => runScriptAnalysisFlowAnalyzeNode(
                            assetNodeKey,
                            nodeInputText,
                            pData.content,
                            null,
                            episodeIdForAssetSubtasks,
                            analysisAttentionNotes,
                            selectedReuseSubjectAssets,
                            {
                                subjectIndexText: specificSubjectIndexText,
                                // All categories skip episode field write; merged persist happens below.
                                skipEpisodePersist: true,
                                onTaskCreated: (taskId) => {
                                    const stableTaskId = String(taskId || '').trim();
                                    onLog?.(`[Stage 3 Asset Design] Subtask task created key=${pData.key || `slot${index + 1}`} trace_id=${subtaskTraceId} task_id=${stableTaskId} node=${assetNodeKey}`, 'info');
                                    registerActiveAnalysisTask(stableTaskId);
                                    if (activeEpisode?.id && stableTaskId) {
                                        saveAnalysisTaskMarker(activeEpisode.id, {
                                            taskId: stableTaskId,
                                            startedAt: phase2StartedAt,
                                            phase: 2,
                                        });
                                        updateEpisodeAnalysisRun(activeEpisode.id, {
                                            taskId: stableTaskId,
                                            phase: 2,
                                        });
                                    }
                                },
                                analysisTraceId: subtaskTraceId,
                                analysisFeatures: {
                                    target_entity_types: subtaskRequestedTargets,
                                    asset_task_key: pData.key || `slot${index + 1}`,
                                },
                            }, 
                            projectId,
                            "script_analysis",
                            scriptAnalysisApiId,
                            sceneAnalysisModeForSubtask
                        ),
                        { startedAt: phase2StartedAt, baselineText: '', resultField: 'none' } // prevent persistence internally by passing no conflict
                    ).then(async (res) => {
                        const responseTraceId = String(res?.meta?.analysis_trace_id || res?.analysis_trace_id || '').trim();
                        throwIfAnalysisStopped();
                        const aText = extractAnalysisTextFromResult(res);
                        const bJson = resolveSubjectsJsonFromAnalyzeResult(res, aText);

                        if (pData.key && !assetsLlmDoneKeys.includes(pData.key)) {
                            assetsLlmDoneKeys.push(pData.key);
                        }
                        onLog?.(`[Stage 3 Asset Design] Subtask completed key=${pData.key || `slot${index + 1}`} trace_id=${subtaskTraceId}${responseTraceId ? ` response_trace_id=${responseTraceId}` : ''}`, 'info');
                        refreshAssetDesignProgressStatus();

                        const subtaskPayload = buildSubtaskSubjectsPayload(pData.key, bJson || {});
                        let subtaskImportReport = null;
                        let subtaskImportError = '';
                        const subtaskHasImportableSubjects = hasAnySubjects(subtaskPayload);
                        if (subtaskHasImportableSubjects) {
                            throwIfAnalysisStopped();
                            const subtaskTargetTypes = (() => {
                                if (pData.key === 'characters') return ['characters'];
                                if (pData.key === 'props') return ['props'];
                                if (pData.key === 'environments' && Array.isArray(requestedTargetFilters) && requestedTargetFilters.length > 0) {
                                    return coupleEnvPosterTargetFilters(
                                        requestedTargetFilters.filter((item) => ENV_POSTER_TARGET_KEYS.includes(item))
                                    );
                                }
                                if (pData.key === 'environments') return [...ENV_POSTER_TARGET_KEYS];
                                if (pData.key === 'posters') return ['posters', 'covers'];
                                return undefined;
                            })();

                            try {
                                subtaskImportReport = await importSubjectsJsonWithDedupe(
                                    JSON.stringify(subtaskPayload, null, 2),
                                    {
                                        reason: `phase2-subtask-${pData.key || `slot${index + 1}`}`,
                                        subjectsJson: subtaskPayload,
                                        importOptions: {
                                            onLog,
                                            projectId,
                                            episodeId: activeEpisode?.id,
                                            importSessionId: subtaskImportSessionId,
                                            targetEntityTypes: subtaskTargetTypes,
                                            overwriteExistingSubjects,
                                            suppressAlerts: true,
                                        },
                                    }
                                );
                                if (!subtaskImportReport || typeof subtaskImportReport !== 'object') {
                                    subtaskImportError = 'import returned non-object result';
                                    logAssetImportFailureDiagnostic(pData.key, {
                                        traceId: subtaskTraceId,
                                        importError: subtaskImportError,
                                        subjectsPayload: subtaskPayload,
                                        phase: 'import',
                                    });
                                } else {
                                    const subCreated = Number(subtaskImportReport?.createdSubjectItems?.length || 0);
                                    const subSkipped = Number(subtaskImportReport?.skippedSubjectItems?.length || 0);
                                    const counts = subtaskImportReport?.importedSubjectCounts || {};
                                    const countedImported = (
                                        Number(counts.character || 0)
                                        + Number(counts.prop || 0)
                                        + Number(counts.environment || 0)
                                        + Number(counts.poster || 0)
                                    );
                                    const designedPosters = countDesignedCoverPosterItems(subtaskPayload);
                                    const importedPosters = reportImportedPosterCount(subtaskImportReport);
                                    if (subCreated <= 0 && subSkipped <= 0 && countedImported <= 0) {
                                        subtaskImportError = String(
                                            subtaskImportReport?.reason
                                            || 'import produced zero created/skipped rows'
                                        );
                                        logAssetImportFailureDiagnostic(pData.key, {
                                            traceId: subtaskTraceId,
                                            importReport: subtaskImportReport,
                                            importError: subtaskImportError,
                                            subjectsPayload: subtaskPayload,
                                            phase: 'import',
                                        });
                                    } else if (
                                        (pData.key === 'environments' || pData.key === 'posters')
                                        && designedPosters > 0
                                        && importedPosters <= 0
                                    ) {
                                        subtaskImportError = 'cover_poster_not_imported';
                                        logAssetImportFailureDiagnostic(pData.key, {
                                            traceId: subtaskTraceId,
                                            importReport: subtaskImportReport,
                                            importError: subtaskImportError,
                                            subjectsPayload: subtaskPayload,
                                            phase: 'import',
                                        });
                                        onLog?.(
                                            `[Stage 3 Asset Design] Environment imported but cover poster was not persisted key=${pData.key} trace_id=${subtaskTraceId} designed_posters=${designedPosters}`,
                                            'warning'
                                        );
                                    } else if (environmentSubtaskMissingMainEnvError(pData.key, subtaskImportReport, subtaskPayload)) {
                                        subtaskImportError = environmentSubtaskMissingMainEnvError(pData.key, subtaskImportReport, subtaskPayload);
                                        logAssetImportFailureDiagnostic(pData.key, {
                                            traceId: subtaskTraceId,
                                            importReport: subtaskImportReport,
                                            importError: subtaskImportError,
                                            subjectsPayload: subtaskPayload,
                                            phase: 'import',
                                        });
                                        onLog?.(
                                            `[Stage 3 Asset Design] 环境资产未解析/未入库主环境 key=${pData.key} trace_id=${subtaskTraceId} reason=${subtaskImportError} posters=${importedPosters}`,
                                            'error'
                                        );
                                    } else {
                                        onLog?.(`[Stage 3 Asset Design] Subtask import done key=${pData.key || `slot${index + 1}`} trace_id=${subtaskTraceId} created=${subCreated} skipped=${subSkipped} counted=${countedImported}`, 'success');
                                    }
                                }
                            } catch (subImportErr) {
                                subtaskImportError = String(subImportErr?.message || subImportErr || 'unknown import error');
                                logAssetImportFailureDiagnostic(pData.key, {
                                    traceId: subtaskTraceId,
                                    importError: subtaskImportError,
                                    subjectsPayload: subtaskPayload,
                                    phase: 'import_exception',
                                });
                            }
                        } else {
                            const countMeta = res?.subjects_json_count || res?.result?.subjects_json_count || {};
                            const truncated = Boolean(res?.__truncated__ || res?.result?.__truncated__);
                            const truncatedNoSubjects = Boolean(
                                res?.__truncated_without_subjects__
                                || res?.result?.__truncated_without_subjects__
                            );
                            const emptyReason = truncatedNoSubjects
                                ? 'truncated_result_missing_subjects_json'
                                : (truncated ? 'truncated_result_empty_subjects' : 'llm_json_not_parsed');
                            subtaskImportError = emptyReason;
                            onLog?.(
                                `[Stage 3 Asset Design] Subtask has no importable subjects key=${pData.key || `slot${index + 1}`} trace_id=${subtaskTraceId}`
                                + ` reason=${emptyReason} counts=${JSON.stringify(countMeta)} truncated=${truncated ? 'yes' : 'no'}`
                                + ` analysis_chars=${String(aText || '').length}`,
                                'warning'
                            );
                            logAssetImportFailureDiagnostic(pData.key, {
                                traceId: subtaskTraceId,
                                importError: emptyReason,
                                subjectsPayload: subtaskPayload,
                                phase: 'parse',
                            });
                        }

                        const readyCounts = subtaskImportReport?.importedSubjectCounts || {};
                        const readyCountedImported = (
                            Number(readyCounts.character || 0)
                            + Number(readyCounts.prop || 0)
                            + Number(readyCounts.environment || 0)
                            + Number(readyCounts.poster || 0)
                        );
                        const assetImportReady = Boolean(
                            subtaskHasImportableSubjects
                            && subtaskImportReport
                            && typeof subtaskImportReport === 'object'
                            && !subtaskImportError
                            && (
                                Number(subtaskImportReport?.createdSubjectItems?.length || 0) > 0
                                || Number(subtaskImportReport?.skippedSubjectItems?.length || 0) > 0
                                || readyCountedImported > 0
                            )
                        );
                        if (assetImportReady) {
                            markAssetCategoryPersisted(pData.key, {
                                highlightHint: buildAssetReadyHint(pData.key),
                            });
                        } else {
                            // Round-1 mid-flight: distinguish "LLM done awaiting import" vs "imported".
                            // Concrete per-category failure lines are shown when the batch decides to retry.
                            refreshAssetDesignProgressStatus();
                        }

                        // Storyboard gate: ENV asset design only — never open on character/prop completion.
                        if (pData.key === 'environments' && assetImportReady) {
                            markEnvironmentAssetDesignReady(`env-subtask-ok:${subtaskTraceId}`);
                        }

                        return {
                            key: pData.key,
                            traceId: subtaskTraceId,
                            importSessionId: subtaskImportSessionId,
                            result: res,
                            analysisText: aText,
                            subjectsJson: bJson,
                            hasImportableSubjects: subtaskHasImportableSubjects,
                            subtaskImportReport,
                            subtaskImportError,
                        };
                    });
            };

            const resultByKey = new Map();
            const cachedSubjectsByKey = new Map();
            const summarizeCategoryFailure = (key, settled) => {
                if (!settled) return `${key}:missing_result`;
                if (settled.status === 'rejected') {
                    const reason = String(settled.reason?.message || settled.reason || 'llm_failed').slice(0, 160);
                    return `${key}:${reason}`;
                }
                const value = settled.value || {};
                if (value.skippedExisting) return '';
                const err = String(value.subtaskImportError || '').trim();
                if (err) return `${key}:${err}`;
                if (!value.hasImportableSubjects) return `${key}:llm_json_not_parsed`;
                return `${key}:not_persisted`;
            };
            const isCategoryPersistOk = (settled) => {
                if (!settled || settled.status !== 'fulfilled' || !settled.value) return false;
                if (settled.value.skippedExisting) return true;
                const report = settled.value.subtaskImportReport;
                if (!report || typeof report !== 'object') return false;
                const created = Number(report?.createdSubjectItems?.length || 0);
                const skipped = Number(report?.skippedSubjectItems?.length || 0);
                const counts = report?.importedSubjectCounts || {};
                const countedImported = (
                    Number(counts.character || 0)
                    + Number(counts.prop || 0)
                    + Number(counts.environment || 0)
                    + Number(counts.poster || 0)
                );
                const importErr = String(settled.value?.subtaskImportError || '').trim();
                // Category completes independently only when that category actually landed in DB
                // (created or skipped-as-existing). LLM-returned JSON alone is not enough.
                if (importErr || !(created > 0 || skipped > 0 || countedImported > 0)) return false;
                const key = String(settled.value?.key || '').trim();
                if (key === 'environments' || key === 'posters') {
                    const designedPosters = countDesignedCoverPosterItems(settled.value?.subjectsJson);
                    if (designedPosters > 0 && reportImportedPosterCount(report) <= 0) return false;
                }
                if (environmentSubtaskMissingMainEnvError(key, report, settled.value?.subjectsJson)) return false;
                return true;
            };
            const importCachedCategorySubjects = async (pData, roundTag = '') => {
                const key = String(pData.key || '');
                const cached = cachedSubjectsByKey.get(key);
                if (!cached || typeof cached !== 'object') return null;
                const subtaskPayload = buildSubtaskSubjectsPayload(key, cached);
                if (!hasAnySubjects(subtaskPayload)) return null;
                const subtaskTraceId = `${phase2BatchTraceId}-${key}${roundTag}-importonly`;
                const subtaskImportSessionId = `import-${subtaskTraceId}`;
                const subtaskTargetTypes = (() => {
                    if (key === 'characters') return ['characters'];
                    if (key === 'props') return ['props'];
                    if (key === 'environments' && Array.isArray(requestedTargetFilters) && requestedTargetFilters.length > 0) {
                        return coupleEnvPosterTargetFilters(
                            requestedTargetFilters.filter((item) => ENV_POSTER_TARGET_KEYS.includes(item))
                        );
                    }
                    if (key === 'environments') return [...ENV_POSTER_TARGET_KEYS];
                    if (key === 'posters') return ['posters', 'covers'];
                    return undefined;
                })();
                onLog?.(
                    `[Stage 3 Asset Design] Import-only retry key=${key} trace_id=${subtaskTraceId} (reuse prior LLM subjects_json; no LLM re-call)`,
                    'info'
                );
                let subtaskImportReport = null;
                let subtaskImportError = '';
                try {
                    subtaskImportReport = await importSubjectsJsonWithDedupe(
                        JSON.stringify(subtaskPayload, null, 2),
                        {
                            reason: `phase2-subtask-${key}-importonly`,
                            subjectsJson: subtaskPayload,
                            forceRetry: true,
                            importOptions: {
                                onLog,
                                projectId,
                                episodeId: activeEpisode?.id,
                                importSessionId: subtaskImportSessionId,
                                targetEntityTypes: subtaskTargetTypes,
                                overwriteExistingSubjects,
                                suppressAlerts: true,
                                forceRetry: true,
                            },
                        }
                    );
                    if (!subtaskImportReport || typeof subtaskImportReport !== 'object') {
                        subtaskImportError = 'import returned non-object result';
                    } else {
                        const subCreated = Number(subtaskImportReport?.createdSubjectItems?.length || 0);
                        const subSkipped = Number(subtaskImportReport?.skippedSubjectItems?.length || 0);
                        const counts = subtaskImportReport?.importedSubjectCounts || {};
                        const countedImported = (
                            Number(counts.character || 0)
                            + Number(counts.prop || 0)
                            + Number(counts.environment || 0)
                            + Number(counts.poster || 0)
                        );
                        if (subCreated <= 0 && subSkipped <= 0 && countedImported <= 0) {
                            subtaskImportError = String(
                                subtaskImportReport?.reason
                                || 'import produced zero created/skipped rows'
                            );
                        } else if (
                            (key === 'environments' || key === 'posters')
                            && countDesignedCoverPosterItems(subtaskPayload) > 0
                            && reportImportedPosterCount(subtaskImportReport) <= 0
                        ) {
                            subtaskImportError = 'cover_poster_not_imported';
                        } else if (environmentSubtaskMissingMainEnvError(key, subtaskImportReport, subtaskPayload)) {
                            subtaskImportError = environmentSubtaskMissingMainEnvError(key, subtaskImportReport, subtaskPayload);
                        }
                    }
                } catch (subImportErr) {
                    subtaskImportError = String(subImportErr?.message || subImportErr || 'unknown import error');
                }
                const counts = subtaskImportReport?.importedSubjectCounts || {};
                const countedImported = (
                    Number(counts.character || 0)
                    + Number(counts.prop || 0)
                    + Number(counts.environment || 0)
                    + Number(counts.poster || 0)
                );
                const assetImportReady = Boolean(
                    !subtaskImportError
                    && subtaskImportReport
                    && typeof subtaskImportReport === 'object'
                    && (
                        Number(subtaskImportReport?.createdSubjectItems?.length || 0) > 0
                        || Number(subtaskImportReport?.skippedSubjectItems?.length || 0) > 0
                        || countedImported > 0
                    )
                );
                if (key === 'environments' && assetImportReady) {
                    markEnvironmentAssetDesignReady(`env-import-only-ok:${subtaskTraceId}`);
                }
                if (assetImportReady) {
                    onLog?.(
                        `[Stage 3 Asset Design] Import-only retry succeeded key=${key} created=${Number(subtaskImportReport?.createdSubjectItems?.length || 0)} skipped=${Number(subtaskImportReport?.skippedSubjectItems?.length || 0)}`,
                        'success'
                    );
                    markAssetCategoryPersisted(key, {
                        highlightHint: buildAssetReadyHint(key),
                    });
                } else {
                    logAssetImportFailureDiagnostic(key, {
                        traceId: subtaskTraceId,
                        importReport: subtaskImportReport,
                        importError: subtaskImportError || 'import_only_retry_failed',
                        subjectsPayload: subtaskPayload,
                        phase: 'import_only_retry',
                    });
                }
                return {
                    status: 'fulfilled',
                    value: {
                        key,
                        traceId: subtaskTraceId,
                        importSessionId: subtaskImportSessionId,
                        result: null,
                        analysisText: '',
                        subjectsJson: cached,
                        hasImportableSubjects: true,
                        subtaskImportReport,
                        subtaskImportError,
                        importOnlyRetry: true,
                    },
                };
            };
            let pendingAssetPrompts = [...promptsData];
            let lastPersistFailureSummary = '';
            let lastPersistFailureLines = [];
            while (pendingAssetPrompts.length > 0) {
                throwIfAnalysisStopped();
                assetRetryRound += 1;
                if (assetRetryRound > 1) {
                    const retryTypes = pendingAssetPrompts.map((item) => item.key).filter(Boolean).join(', ');
                    onLog?.(
                        `[Stage 3 Asset Design] Persistence gap — auto-retry round ${assetRetryRound} for incomplete categories only: ${retryTypes || 'unknown'}.`
                        + (lastPersistFailureSummary ? ` reasons=${lastPersistFailureSummary}` : ''),
                        'warning'
                    );
                    // Failed empty imports must not block the next persistence attempt.
                    resetAutoSubjectsImportCache();
                    refreshAssetDesignProgressStatus({
                        pendingKeys: pendingAssetPrompts.map((item) => item.key).filter(Boolean),
                        failureLines: lastPersistFailureLines,
                    });
                    const delayMs = Math.min(
                        ANALYSIS_PIPELINE_RETRY_BASE_DELAY_MS * assetRetryRound,
                        ANALYSIS_PIPELINE_RETRY_MAX_DELAY_MS
                    );
                    await new Promise((resolve) => setTimeout(resolve, delayMs));
                    throwIfAnalysisStopped();
                } else {
                    refreshAssetDesignProgressStatus({
                        pendingKeys: pendingAssetPrompts.map((item) => item.key).filter(Boolean),
                    });
                }

                const batchResults = await Promise.allSettled(
                    pendingAssetPrompts.map(async (pData, index) => {
                        const key = String(pData.key || '');
                        // If this category already has parseable subjects_json, NEVER re-call LLM.
                        // Re-generation causes duplicate design work and can create duplicate entities.
                        // Retries are import-only until persist OK / DB coverage / retry budget exhausted.
                        if (assetRetryRound > 1 && cachedSubjectsByKey.has(key)) {
                            const importOnlySettled = await importCachedCategorySubjects(
                                pData,
                                `-r${assetRetryRound}`
                            );
                            if (importOnlySettled) {
                                if (!isCategoryPersistOk(importOnlySettled)) {
                                    onLog?.(
                                        `[Stage 3 Asset Design] Import-only retry still failing key=${key};`
                                        + ' keeping cached subjects_json and will not re-call LLM for this category.',
                                        'warning'
                                    );
                                }
                                return importOnlySettled.value;
                            }
                            onLog?.(
                                `[Stage 3 Asset Design] Cached subjects_json present but import-only retry returned null key=${key};`
                                + ' skipping LLM re-call to avoid duplicate generation.',
                                'warning'
                            );
                            return (
                                resultByKey.get(key)?.value
                                || {
                                    key,
                                    subjectsJson: cachedSubjectsByKey.get(key),
                                    hasImportableSubjects: true,
                                    subtaskImportReport: null,
                                    subtaskImportError: 'import_only_retry_returned_null',
                                }
                            );
                        }
                        const stableIndex = Math.max(0, promptsData.findIndex((item) => item.key === pData.key));
                        return runOneAssetSubtask(
                            pData,
                            stableIndex >= 0 ? stableIndex : index,
                            assetRetryRound > 1 ? `-r${assetRetryRound}` : ''
                        );
                    })
                );
                pendingAssetPrompts.forEach((pData, idx) => {
                    const settled = batchResults[idx];
                    resultByKey.set(String(pData.key || ''), settled);
                    if (settled?.status === 'fulfilled' && settled.value?.subjectsJson) {
                        const payload = buildSubtaskSubjectsPayload(pData.key, settled.value.subjectsJson);
                        const cacheable = pData.key === 'environments'
                            ? (Array.isArray(payload.environments) && payload.environments.length > 0)
                            : hasAnySubjects(payload);
                        if (cacheable) {
                            cachedSubjectsByKey.set(String(pData.key || ''), settled.value.subjectsJson);
                        }
                    }
                    if (settled?.status === 'rejected') {
                        onLog?.(
                            `[Stage 3 Asset Design] Subtask rejected key=${pData.key}: ${settled.reason?.message || settled.reason}`,
                            'warning'
                        );
                    }
                });

                const nextPending = [];
                const failureParts = [];
                const failureLines = [];
                for (const pData of pendingAssetPrompts) {
                    const settled = resultByKey.get(String(pData.key || ''));
                    if (!settled) {
                        nextPending.push(pData);
                        failureParts.push(`${pData.key}:missing_result`);
                        failureLines.push(formatAssetCategoryFailureLine(pData.key, null));
                        continue;
                    }
                    if (isCategoryPersistOk(settled)) {
                        markAssetCategoryPersisted(pData.key, {
                            highlightHint: buildAssetReadyHint(pData.key),
                        });
                        continue;
                    }
                    nextPending.push(pData);
                    const part = summarizeCategoryFailure(pData.key, settled);
                    if (part) failureParts.push(part);
                    const line = formatAssetCategoryFailureLine(pData.key, settled);
                    if (line) failureLines.push(line);
                }
                lastPersistFailureSummary = failureParts.join('；').slice(0, 360);
                lastPersistFailureLines = failureLines;

                if (nextPending.length <= 0) {
                    pendingAssetPrompts = [];
                    break;
                }

                if (assetRetryRound >= (1 + MAX_ASSET_PERSIST_RETRY_ROUNDS)) {
                    onLog?.(
                        `[Stage 3 Asset Design] Stopping persistence retries after ${assetRetryRound} rounds. Remaining: ${nextPending.map((x) => x.key).join(', ')}. ${lastPersistFailureSummary}`,
                        'warning'
                    );
                    refreshAssetDesignProgressStatus({
                        pendingKeys: nextPending.map((x) => x.key).filter(Boolean),
                        failureLines: lastPersistFailureLines,
                        stopped: true,
                    });
                    pendingAssetPrompts = [];
                    break;
                }

                // Drop categories only when THIS-RUN designed names (or Subject Index
                // names) are already in the entity table. Raw type counts are not
                // enough: leftover derived ENVs can outnumber the 4 new mains and
                // falsely mark environment design as imported.
                if (projectId && episodeIdForAssetSubtasks && typeof fetchEntities === 'function') {
                    try {
                        const dbEntities = await fetchEntities(projectId, {
                            episode_id: Number(episodeIdForAssetSubtasks) || undefined,
                        }).catch(() => []);
                        const collectDesignedSubjectEntries = (pData, cachedPayload, filteredText) => {
                            const entries = [];
                            const payload = cachedPayload && typeof cachedPayload === 'object' ? cachedPayload : {};
                            const buckets = pData.key === 'characters'
                                ? ['characters']
                                : (pData.key === 'props' ? ['props'] : ['environments', 'posters', 'covers']);
                            const bucketToReport = {
                                characters: 'character',
                                props: 'prop',
                                environments: 'environment',
                                posters: 'poster',
                                covers: 'poster',
                            };
                            buckets.forEach((bucket) => {
                                (Array.isArray(payload[bucket]) ? payload[bucket] : []).forEach((item) => {
                                    const name = String(
                                        item?.name
                                        || item?.name_zh
                                        || item?.subject_name_zh
                                        || item?.subject_name_exact
                                        || item?.subject_name
                                        || ''
                                    ).trim();
                                    if (name) {
                                        entries.push({
                                            name,
                                            reportType: bucketToReport[bucket] || 'environment',
                                        });
                                    }
                                });
                            });
                            if (entries.length > 0) return entries;
                            String(filteredText || '').split('\n').forEach((line) => {
                                const detected = detectSubjectIndexLineType(line);
                                if (!detected.isSubjectRow) return;
                                const reportType = detected.type === 'cover_poster'
                                    ? 'poster'
                                    : (detected.type === 'character' || detected.type === 'prop' || detected.type === 'environment'
                                        ? detected.type
                                        : '');
                                if (!reportType) return;
                                extractSubjectIndexRowNames(line).forEach((name) => {
                                    if (name) entries.push({ name, reportType });
                                });
                            });
                            return entries;
                        };
                        const countDesignedEntriesCovered = (entries) => {
                            const byType = new Map();
                            (Array.isArray(entries) ? entries : []).forEach((entry) => {
                                const type = String(entry?.reportType || '').trim() || 'environment';
                                if (!byType.has(type)) byType.set(type, []);
                                byType.get(type).push(entry);
                            });
                            let covered = 0;
                            byType.forEach((list, type) => {
                                covered += countSubjectIndexEntriesCoveredInDb(list, type, dbEntities);
                            });
                            return covered;
                        };
                        const stillMissing = [];
                        for (const pData of nextPending) {
                            const filtered = filterSubjectIndexTextForAssetTask(
                                finalSubjectIndexText,
                                pData.key,
                                requestedTargetFilters
                            );
                            const cachedPayload = cachedSubjectsByKey.get(String(pData.key || ''));
                            const designedEntries = collectDesignedSubjectEntries(
                                pData,
                                cachedPayload,
                                filtered.text
                            );
                            const covered = countDesignedEntriesCovered(designedEntries);
                            const needed = designedEntries.length;
                            // CHAR/PROP/ENV now come from extracts/plans, not Subject Index
                            // rows. A parse miss leaves keptRows=0 and no cache — that must
                            // stay in the retry queue so LLM can run again (3 total attempts).
                            if (needed <= 0) {
                                onLog?.(
                                    t(
                                        `[Stage 3 Asset Design] ${getAssetDesignTaskLabel(pData.key)} 未解析到可入库结果，将重跑该类（第 ${assetRetryRound + 1} 轮）。`,
                                        `[Stage 3 Asset Design] ${pData.key} has no importable result; will rerun this category (round ${assetRetryRound + 1}).`
                                    ),
                                    'warning'
                                );
                                stillMissing.push(pData);
                                continue;
                            }
                            if (needed > 0 && covered >= needed) {
                                onLog?.(
                                    `[Stage 3 Asset Design] ${pData.key} already covered in DB by name (${covered}/${needed}); stop retrying this category.`,
                                    'info'
                                );
                                resultByKey.set(String(pData.key || ''), {
                                    status: 'fulfilled',
                                    value: {
                                        key: pData.key,
                                        skippedExisting: true,
                                        hasImportableSubjects: false,
                                        subtaskImportReport: {
                                            createdSubjectItems: [],
                                            skippedSubjectItems: [{
                                                type: pData.key,
                                                reason: 'db_name_coverage',
                                                count: covered,
                                            }],
                                        },
                                        subtaskImportError: '',
                                    },
                                });
                                markAssetCategoryPersisted(pData.key, {
                                    highlightHint: buildAssetReadyHint(pData.key),
                                });
                                continue;
                            }
                            onLog?.(
                                t(
                                    `[Stage 3 Asset Design] ${getAssetDesignTaskLabel(pData.key)} 入库未齐套（按名称 ${covered}/${needed || filtered.keptRows}），继续补入库，不用库内残留数量冒充完成。`,
                                    `[Stage 3 Asset Design] ${pData.key} not name-covered in DB (${covered}/${needed || filtered.keptRows}); keep retrying import instead of counting leftover rows.`
                                ),
                                'warning'
                            );
                            stillMissing.push(pData);
                        }
                        pendingAssetPrompts = stillMissing;
                    } catch (_) {
                        pendingAssetPrompts = nextPending;
                    }
                } else {
                    pendingAssetPrompts = nextPending;
                }
            }

            const results = promptsData.map((pData) => (
                resultByKey.get(String(pData.key || ''))
                || {
                    status: 'rejected',
                    reason: new Error(`Missing asset subtask result for ${pData.key || 'unknown'}`),
                }
            ));

            throwIfAnalysisStopped();
            await refreshEpisodeOwnedEntities();

            const completedAssetTaskLabels = assetsGenCompletedKeys.map(getAssetDesignTaskLabel).filter(Boolean).join('、');
            const unfinishedKeys = assetPromptKeysSnapshot.filter((key) => !assetsGenCompletedKeys.includes(key));
            const unfinishedLines = unfinishedKeys
                .map((key) => formatAssetCategoryFailureLine(key, resultByKey.get(key)))
                .filter(Boolean);
            const assetsGenCompleteMessage = unfinishedKeys.length > 0
                ? buildAssetProgressMessage({
                    persistedKeys: [...assetsGenCompletedKeys],
                    llmDoneKeys: [...assetsLlmDoneKeys],
                    pendingKeys: unfinishedKeys,
                    failureLines: unfinishedLines,
                    retryRound: Math.max(assetRetryRound, 2),
                    stopped: true,
                })
                : t(
                    `✅ 第四阶段资产设计已入库完成 (${assetsGenCompletedCount}/${targetAssetsCount}${completedAssetTaskLabels ? `：${completedAssetTaskLabels}` : ''})`,
                    `Stage 4 asset design imported (${assetsGenCompletedCount}/${targetAssetsCount}${completedAssetTaskLabels ? `: ${completedAssetTaskLabels.replace(/、/g, ', ')}` : ''})`
                );
            finalizeAnalysisFlowHistoryForPhase('assets_gen', assetsGenCompleteMessage);
            setAnalysisFlowStatus((prev) => {
                const prevPhase = String(prev?.phase || '').trim().toLowerCase();
                const preserveLivePhase = Boolean(options?.isRetryPhase2 && analysisRunInFlightRef.current)
                    && prevPhase
                    && !['idle', 'failed'].includes(prevPhase);
                return {
                    ...(prev && typeof prev === 'object' ? prev : {}),
                    phase: preserveLivePhase ? prevPhase : 'assets_gen',
                    message: preserveLivePhase ? (String(prev?.message || '').trim() || assetsGenCompleteMessage) : assetsGenCompleteMessage,
                    highlightHint: preserveLivePhase
                        ? t('所选资产已重跑完成，可前往资产库查看', 'Selected assets finished rerunning; open the Assets library to review')
                        : (prev?.highlightHint || ''),
                    assetsGenSettled: unfinishedKeys.length === 0,
                };
            });

            // Merge results
            let mergedBackendSubjectsJson = { characters: [], environments: [], props: [], posters: [], covers: [] };
            const isSingleSubjectRerun = Boolean(
                collectEntityPurgeNameCandidates(
                    options?.rerunSubject?.name,
                    options?.rerunSubject?.fields,
                ).length
            );
            const scopedEnvMerge = ['main', 'derived'].includes(String(options.envScope || '').trim().toLowerCase());
            const existingEntities = getAnalysisEntitiesPayloadFromJsonText(
                activeEpisode?.ai_entity_design_result || llmAssetRawResultContent || ''
            ) || {};
            if (options.targetEntityTypes && Array.isArray(options.targetEntityTypes)) {
                ['characters', 'environments', 'props', 'posters', 'covers'].forEach(k => {
                    const isTarget = options.targetEntityTypes.includes(k) || ((k === 'posters' || k === 'covers') && (options.targetEntityTypes.includes('posters') || options.targetEntityTypes.includes('covers')));
                    if (!isTarget && existingEntities[k]) {
                        mergedBackendSubjectsJson[k] = existingEntities[k];
                    } else if (isTarget && (isSingleSubjectRerun || (k === 'environments' && scopedEnvMerge)) && Array.isArray(existingEntities[k])) {
                        // Keep siblings / the other ENV subset; incoming LLM rows upsert by name below.
                        mergedBackendSubjectsJson[k] = existingEntities[k];
                    }
                });
            } else if (scopedEnvMerge && Array.isArray(existingEntities.environments)) {
                mergedBackendSubjectsJson.environments = existingEntities.environments;
            }
            let rawTextParts = [];
            
            for (let idx = 0; idx < results.length; idx += 1) {
                const r = results[idx];
                if (r.status === 'fulfilled' && r.value.result) {
                    const bJson = r.value.subjectsJson || {};
                    const aText = r.value.analysisText || '';

                                          if (bJson) {
                          // Only replace a category when the subtask returned non-empty rows.
                          // Empty arrays must not wipe previously merged / persisted subjects.
                          // Single-subject rerun upserts by name so siblings remain.
                          if (r.value.key === 'characters' && Array.isArray(bJson.characters) && bJson.characters.length > 0) {
                              mergedBackendSubjectsJson.characters = isSingleSubjectRerun
                                  ? upsertEntityDesignItemsByName(mergedBackendSubjectsJson.characters, bJson.characters)
                                  : bJson.characters;
                          }
                          if (r.value.key === 'environments') {
                              if (Array.isArray(bJson.environments) && bJson.environments.length > 0 && (!options.targetEntityTypes || options.targetEntityTypes.includes('environments'))) {
                                  mergedBackendSubjectsJson.environments = (isSingleSubjectRerun || scopedEnvMerge)
                                      ? upsertEntityDesignItemsByName(mergedBackendSubjectsJson.environments, bJson.environments)
                                      : bJson.environments;
                              }
                              if (Array.isArray(bJson.posters) && bJson.posters.length > 0 && (!options.targetEntityTypes || options.targetEntityTypes.includes('posters') || options.targetEntityTypes.includes('covers'))) {
                                  mergedBackendSubjectsJson.posters = isSingleSubjectRerun
                                      ? upsertEntityDesignItemsByName(mergedBackendSubjectsJson.posters, bJson.posters)
                                      : bJson.posters;
                              }
                              if (Array.isArray(bJson.covers) && bJson.covers.length > 0 && (!options.targetEntityTypes || options.targetEntityTypes.includes('covers') || options.targetEntityTypes.includes('posters'))) {
                                  mergedBackendSubjectsJson.covers = isSingleSubjectRerun
                                      ? upsertEntityDesignItemsByName(mergedBackendSubjectsJson.covers, bJson.covers)
                                      : bJson.covers;
                              }
                          }
                          if (r.value.key === 'props' && Array.isArray(bJson.props) && bJson.props.length > 0) {
                              mergedBackendSubjectsJson.props = isSingleSubjectRerun
                                  ? upsertEntityDesignItemsByName(mergedBackendSubjectsJson.props, bJson.props)
                                  : bJson.props;
                          }
                        if (r.value.key === 'posters') {
                            if (Array.isArray(bJson.posters) && bJson.posters.length > 0 && (!options.targetEntityTypes || options.targetEntityTypes.includes('posters') || options.targetEntityTypes.includes('covers'))) {
                                mergedBackendSubjectsJson.posters = isSingleSubjectRerun
                                    ? upsertEntityDesignItemsByName(mergedBackendSubjectsJson.posters, bJson.posters)
                                    : bJson.posters;
                            }
                            if (Array.isArray(bJson.covers) && bJson.covers.length > 0 && (!options.targetEntityTypes || options.targetEntityTypes.includes('covers') || options.targetEntityTypes.includes('posters'))) {
                                mergedBackendSubjectsJson.covers = isSingleSubjectRerun
                                    ? upsertEntityDesignItemsByName(mergedBackendSubjectsJson.covers, bJson.covers)
                                    : bJson.covers;
                            }
                        }
                    }
                    if (aText) {
                        if (r.value.key === 'environments') {
                            let extEnv = bJson?.environments || [];
                            let extPos = bJson?.posters || bJson?.covers || [];
                            if (extEnv.length > 0 || extPos.length > 0) {
                                let wrapObj = {};
                                if (extEnv.length > 0) wrapObj.environments = extEnv;
                                if (extPos.length > 0) wrapObj.posters = extPos;
                                rawTextParts.push(`\n\n\`\`\`json\n${JSON.stringify(wrapObj, null, 2)}\n\`\`\`\n\n`);
                            } else {
                                rawTextParts.push(`\n\n${aText}\n\n`);
                            }
                        } else {
                            let extractedArr = bJson && bJson[r.value.key] ? bJson[r.value.key] : null;
                            if (r.value.key === 'posters' && (!extractedArr || !extractedArr.length) && bJson?.covers) {
                                extractedArr = bJson.covers;
                            }
                            if (extractedArr && extractedArr.length > 0) {
                                rawTextParts.push(`\n\n\`\`\`json\n${JSON.stringify({[r.value.key]: extractedArr}, null, 2)}\n\`\`\`\n\n`);
                            } else {
                                rawTextParts.push(`\n\n${aText}\n\n`);
                            }
                        }
                    }
                } else if (r.status === 'rejected') {
                    const failedKey = promptsData[idx]?.key || `slot${idx + 1}`;
                    const failedTraceId = `${phase2BatchTraceId}-${failedKey}`;
                    onLog?.(`[Stage 3 Asset Design] Warning: task ${failedKey} failed (trace_id=${failedTraceId}): ${r.reason}`, "warning");
                }
            }

            const canonicalAssetDesignText = String(
                buildCanonicalAssetDesignJsonText(mergedBackendSubjectsJson) || rawTextParts.join('\n')
            ).trim();
            setLlmAssetRawResultContent(canonicalAssetDesignText);

            // Override to persist true result manually
            try {
                if (canonicalAssetDesignText) {
                    await persistLlmResultContent(canonicalAssetDesignText || '', 'ai_entity_design_result');
                }
            } catch (persistErr) {
                if (isPromptInjectionRiskError(persistErr)) throw persistErr;
                onLog?.(t(`保存资产设计结果时出现问题：${persistErr?.message || persistErr}`, `Could not save asset design: ${persistErr?.message || persistErr}`), 'warning');
            }

            if (canonicalAssetDesignText) {
                throwIfAnalysisStopped();
                // Safeguard: make sure we are not importing plain text phase 1 by mistake
                const hasValidSubjectJsonBlock = /"characters"\s*:\s*\[|"props"\s*:\s*\[|"environments"\s*:\s*\[|"posters"\s*:\s*\[|"covers"\s*:\s*\[/i.test(canonicalAssetDesignText);
                
                if (!hasValidSubjectJsonBlock && Object.values(mergedBackendSubjectsJson).every(arr => arr.length === 0)) {
                    onLog?.(t('AI未返回可入库的资产设计，已跳过导入以免覆盖现有清单。', 'AI did not return importable asset design; skipped import to keep the current inventory.'), "warning");
                    throw new Error("AI 引擎在整理出场名单时开小差了，未能返回标准数据表。请点击查阅原文检查，是否可以手动重新生成。");
                } else {
                    const completedReports = results
                        .filter((item) => item.status === 'fulfilled' && item.value && item.value.subtaskImportReport)
                        .map((item) => item.value.subtaskImportReport);

                    const subtaskReports = results.map((item, idx) => {
                        const fallbackKey = promptsData[idx]?.key || `slot${idx + 1}`;
                        const fallbackTraceId = `${phase2BatchTraceId}-${fallbackKey}`;
                        if (item.status === 'fulfilled' && item.value) {
                            const created = Number(item.value.subtaskImportReport?.createdSubjectItems?.length || 0);
                            const skipped = Number(item.value.subtaskImportReport?.skippedSubjectItems?.length || 0);
                            const hasImportableSubjects = Boolean(item.value.hasImportableSubjects);
                            const status = item.value.skippedExisting
                                ? 'ok'
                                : (item.value.subtaskImportError
                                    ? 'import_failed'
                                    : ((created > 0 || skipped > 0)
                                        ? 'ok'
                                        : (hasImportableSubjects ? 'import_failed' : 'incomplete_return')));
                            const recommendation = status === 'incomplete_return'
                                ? `LLM 已返回但未解析到可入库的 ${fallbackKey} 资产。建议点击“重跑失败路由”，仅重跑缺失资产类型：${fallbackKey}。`
                                : (status === 'import_failed' && !item.value.subtaskImportError
                                    ? `LLM 已返回 ${fallbackKey}，但实体库落库为 0。建议仅重跑该分类：${fallbackKey}。`
                                    : '');
                            return {
                                key: item.value.key || fallbackKey,
                                traceId: item.value.traceId || fallbackTraceId,
                                importSessionId: item.value.importSessionId || `import-${fallbackTraceId}`,
                                status,
                                created,
                                skipped,
                                error: String(item.value.subtaskImportError || ''),
                                recommendation,
                            };
                        }
                        return {
                            key: fallbackKey,
                            traceId: fallbackTraceId,
                            importSessionId: `import-${fallbackTraceId}`,
                            status: 'llm_failed',
                            created: 0,
                            skipped: 0,
                            error: String(item?.reason || ''),
                        };
                    });

                    const mergedCounts = completedReports.reduce((acc, report) => {
                        acc.character += Number(report?.importedSubjectCounts?.character || 0);
                        acc.prop += Number(report?.importedSubjectCounts?.prop || 0);
                        acc.environment += Number(report?.importedSubjectCounts?.environment || 0);
                        acc.poster += Number(report?.importedSubjectCounts?.poster || 0);
                        return acc;
                    }, { character: 0, prop: 0, environment: 0, poster: 0 });

                    const createdItems = completedReports.flatMap((report) => Array.isArray(report?.createdSubjectItems) ? report.createdSubjectItems : []);
                    const skippedItems = completedReports.flatMap((report) => Array.isArray(report?.skippedSubjectItems) ? report.skippedSubjectItems : []);
                    const createdLen = createdItems.length;
                    const matchedLen = skippedItems.length;

                    const failedSubtaskItems = subtaskReports
                        .filter((x) => x.status !== 'ok')
                        .map((x) => ({
                            key: x.key,
                            traceId: x.traceId,
                            importSessionId: x.importSessionId,
                            reason: x.error || x.recommendation || x.status,
                            recommendation: x.recommendation || '',
                        }));
                    if (
                        !allowRepeatAutoStage3
                        && episodeIdForPhase2 > 0
                        && !options?.deferEnvironmentDesign
                        && failedSubtaskItems.length <= 0
                    ) {
                        phase2AutoCompletedEpisodeRef.current = episodeIdForPhase2;
                    }
                    if (failedSubtaskItems.length > 0) {
                        const retryLabels = failedSubtaskItems
                            .map((x) => getAssetDesignTaskLabel(x.key))
                            .filter(Boolean);
                        onLog?.(
                            t(
                                `部分资产尚未入库${retryLabels.length ? `（${retryLabels.join('、')}）` : ''}，稍后会自动补齐。`,
                                `Some assets are not in the library yet${retryLabels.length ? ` (${retryLabels.join(', ')})` : ''}; they will be filled in automatically.`
                            ),
                            'warning'
                        );
                    }

                    const envSubtaskOk = subtaskReports.some((report) => (
                        String(report?.key || '').trim() === 'environments'
                        && String(report?.status || '').trim().toLowerCase() === 'ok'
                    ));
                    const envSubtaskSkipped = results.some((item) => (
                        item.status === 'fulfilled'
                        && String(item.value?.key || '').trim() === 'environments'
                        && Boolean(item.value?.skippedExisting)
                    ));
                    // Only open the storyboard gate when THIS run's env/poster node settled.
                    // Do not fall back to stale episode JSON after a failed env subtask.
                    if (envSubtaskOk || envSubtaskSkipped || environmentAssetReadyRef.current) {
                        markEnvironmentAssetDesignReady(
                            envSubtaskOk
                                ? 'env-subtask-settled-ok'
                                : (envSubtaskSkipped ? 'env-subtask-skipped-existing' : 'env-already-ready')
                        );
                    } else if (promptFiles.some((p) => p.key === 'environments')) {
                        onLog?.(
                            t(
                                '环境与海报资产设计未完成，等待中的分镜已停止。',
                                'Environment and cover asset design did not finish; pending storyboards were stopped.'
                            ),
                            'warning'
                        );
                        failWaitingStoryboardKickoffsForEnvAbort('env-subtask-failed');
                    }

                    return {
                        checkedSceneCount: importedSceneRows.length,
                        missingSceneCount: 0,
                        missingItemCount: createdLen + matchedLen + failedSubtaskItems.length,
                        supplementReport: {
                            createdItems,
                            skippedItems,
                            failedItems: failedSubtaskItems,
                        },
                        importedSubjectCounts: mergedCounts,
                        subtaskReports,
                    };
                }
            }

        } catch (error) {
            console.error("Stage 3 asset design step failed:", error);
            // Keep pending=true on failure so concurrent/residual kickoffs cannot use stale env JSON.
            if (isTaskCanceledError(error) || analysisStopRequestedRef.current) {
                environmentAssetDesignPendingRef.current = false;
                const timedOut = Boolean(error?.isPipelineTimeout)
                    || analysisStopReasonRef.current === 'timeout';
                if (timedOut) {
                    onLog?.(t('资产设计因超时已停止。', 'Asset design stopped because the run timed out.'), 'warning');
                    throw createAnalysisPipelineTimeoutError();
                }
                const episodeId = Number(activeEpisode?.id || latestActiveEpisodeIdRef.current || 0);
                const control = episodeId ? getEpisodeAnalysisPipelineControl(episodeId) : null;
                const explicitlyStoppedByUser = Boolean(
                    (analysisStopRequestedRef.current || control?.stopRequested)
                    && String(analysisStopReasonRef.current || control?.stopReason || '') === 'user'
                );
                if (explicitlyStoppedByUser) {
                    onLog?.(t('资产设计已停止。', 'Asset design was stopped.'), 'warning');
                    throw createAnalysisCanceledError();
                }
                onLog?.(t('资产设计被中断。', 'Asset design was interrupted.'), 'warning');
                throw error;
            }
            onLog?.(t(`资产设计失败：${error.message}`, `Asset design failed: ${error.message}`));
            throw error;
        } finally {
            releaseIncomingAssetLock();
            setLiveAssetDesignTaskKeys((prev) => (
                (Array.isArray(prev) ? prev : []).filter((key) => !launchedLiveKeys.includes(key))
            ));
            // Parent analysis pipeline still owns task markers while scenes/storyboard continue.
            if (activeEpisode?.id && !analysisRunInFlightRef.current) {
                clearAnalysisTaskMarker(activeEpisode.id);
            }
        }

        return emptyReport;
    }, [
        projectId, llmRawResultContent, llmResultContent, activeEpisode, t, onLog,
        fetchPrompt, analyzeScene, awaitAnalyzeSceneWithRecovery, adaptationText,
        analysisAttentionNotes, selectedReuseSubjectAssets, extractAnalysisTextFromResult, doImportText,
        isSuperuser, setSystemPrompt, setUserPrompt, setShowAnalysisModal, functionApiConfigs,
        project, extractPureSubjectIndexText, extractAnalysisSections, filterSubjectIndexTextForAssetTask,
        filterSubjectIndexTextByEnvironmentScope,
        filterSubjectIndexExcludingExistingEntities, buildExistingEntityNameSet, fetchEntities,
        detectSubjectIndexLineType, extractSubjectIndexRowNames,
        hasSubjectIndexStructure, hasEnvironmentsToDesign, hasPersistedEnvironmentAssetDesign, markEnvironmentAssetDesignReady,
        hasPropExtractForAssetDesign, hasPersistedPropAssetDesign,
        hasCharExtractForAssetDesign, hasPersistedCharacterAssetDesign,
        failWaitingStoryboardKickoffsForEnvAbort,
        throwIfAnalysisStopped, registerActiveAnalysisTask, isTaskCanceledError, createAnalysisCanceledError,
        createAnalysisPipelineTimeoutError,
        buildStage2_2UserInputFromStage1, clearAnalysisTaskMarker, finalizeAnalysisFlowHistoryForPhase,
        saveAnalysisTaskMarker, updateEpisodeAnalysisRun, resolveSelectedScriptAnalysisApiId,
        refreshEpisodeOwnedEntities,
    ]);

    const applyBackgroundTaskMonitoringUi = useCallback((phase, startedAt = Date.now(), options = {}) => {
        const resolvedPhase = String(phase || 'script_opt').trim() || 'script_opt';
        const started = Number(startedAt || Date.now());
        const elapsedMs = Math.max(0, Date.now() - (Number.isFinite(started) && started > 0 ? started : Date.now()));
        const forAssets = resolvedPhase === 'assets_gen' || Number(options?.phaseNum) === 2;
        beginAnalysisTimer(started);
        if (forAssets) {
            setIsAnalyzing(false);
            setIsRetryingPhase2(true);
        } else {
            setIsAnalyzing(true);
            setIsRetryingPhase2(false);
        }
        setAnalysisFlowStatus({
            phase: resolvedPhase,
            message: String(options?.message || '').trim()
                || t('后台分析任务进行中，正在恢复进度监控...', 'Background analysis task in progress; restoring progress monitoring...'),
        });
        setAnalysisUiReport((prev) => ({
            ...(prev && typeof prev === 'object' ? prev : {}),
            status: 'running',
            startedAt: Number(prev?.startedAt || started) || started,
            durationMs: elapsedMs,
            warning: '',
            error: '',
        }));
    }, [beginAnalysisTimer, t]);

    const resumeAnalysisFromTaskMarker = useCallback(async (marker) => {
        if (!activeEpisode?.id || !marker?.taskId) return;
        if (getEpisodeAnalysisRun(activeEpisode.id)?.promise) return;
        if (analysisResumeInFlightRef.current || analysisRunInFlightRef.current) return;
        if (isRetryingPhase2 || phase2GenerationInFlightRef.current || analysisFallbackRetryRef.current.running) return;
        if (isAsyncTaskPollInFlight(marker.taskId)) {
            if (onLog) onLog?.('[Analysis Resume] Task poll already active; skipping duplicate marker resume.', 'info');
            return;
        }

        if (Number(marker?.phase) === 2) {
            if (clearStalePhase2AssetMarkerIfDesignExists(activeEpisode.id, 'resume-guard')) return;
        }
        analysisResumeInFlightRef.current = true;
        analysisAwaitingStoryboardRef.current = false;

        const markerStartedAt = Number(marker?.startedAt || 0);
        const startedAt = (Number.isFinite(markerStartedAt) && markerStartedAt > 0) ? markerStartedAt : Date.now();
        const elapsedMs = Math.max(0, Date.now() - startedAt);
        beginAnalysisTimer(startedAt);
        const remainingTimeoutMs = Math.max(0, ANALYSIS_TASK_MAX_AGE_MS - elapsedMs);
        const markerTaskIds = Array.from(new Set([
            String(marker?.taskId || '').trim(),
            ...(Array.isArray(marker?.taskIds) ? marker.taskIds.map((item) => String(item || '').trim()) : []),
        ].filter(Boolean)));
        markerTaskIds.forEach((taskId) => activeAnalysisTaskIdsRef.current.add(taskId));
        if (marker?.phase === 2) {
            setIsAnalyzing(false);
            setIsRetryingPhase2(true);
            setActiveAnalysisTaskId(markerTaskIds[markerTaskIds.length - 1] || String(marker?.taskId || '').trim());
            setAnalysisUiReport({
                status: 'running',
                startedAt,
                durationMs: elapsedMs,
                phaseTimings: null,
                importReport: null,
                runtimeMeta: null,
                warning: '',
                error: '',
            });
            setAnalysisFlowStatus({
                phase: 'assets_gen',
                message: t("✨ 发现有个未完成的第三阶段任务，正在继续执行资产设计...", "Resuming Stage 3 asset design..."),
            });
            let keepPhase2Monitoring = false;
            try {
                const result = await awaitAnalyzeSceneWithRecovery(
                    () => waitForAsyncTask(marker.taskId, { interval: 2500, timeout: remainingTimeoutMs }),
                    { startedAt, baselineText: activeEpisode?.ai_entity_design_result || '', resultField: 'ai_entity_design_result' }
                );
                const analyzedText = extractAnalysisTextFromResult(result);
                const backendSubjectsJson = result?.subjects_json;
                const canonicalAssetDesignText = String(
                    buildCanonicalAssetDesignJsonText(backendSubjectsJson) || analyzedText || ''
                ).trim();
                setLlmAssetRawResultContent(canonicalAssetDesignText);

                const savedByBackend = !!(result?.meta?.saved_to_episode);
                try {
                    if (true || !savedByBackend || (canonicalAssetDesignText && canonicalAssetDesignText !== String(analyzedText || '').trim())) {
                        await persistLlmResultContent(canonicalAssetDesignText || '', 'ai_entity_design_result');
                    } else {
                        // await refreshAnalysisFromDB({ resultField: 'ai_entity_design_result' }); // TEMPORARY DISABLE
                    }
                } catch (persistErr) {
                    if (isPromptInjectionRiskError(persistErr)) throw persistErr;
                    onLog?.(`[Stage 3 Asset Design] Recovery save warning: ${persistErr?.message || persistErr}`, 'warning');
                }

                if (canonicalAssetDesignText) {
                    const hasValidSubjectJsonBlock = /"characters"\s*:\s*\[|"props"\s*:\s*\[|"environments"\s*:\s*\[|"posters"\s*:\s*\[|"covers"\s*:\s*\[/i.test(canonicalAssetDesignText);
                    if (!hasValidSubjectJsonBlock && !backendSubjectsJson) {
                        onLog?.(`[Stage 3 Asset Design] Warning: AI did not return a valid asset-design JSON block during recovery.`);
                    } else {
                        const sceneImportReport = await importSubjectsJsonWithDedupe(canonicalAssetDesignText, {
                            reason: 'phase2-entity-design',
                            subjectsJson: backendSubjectsJson || null,
                            importOptions: {
                                onLog,
                                projectId,
                                episodeId: activeEpisode?.id,
                                subjectsJson: backendSubjectsJson || null,
                                suppressAlerts: true,
                            },
                        });
                        
                        setAnalysisUiReport(prev => {
                            const prevImport = prev?.importReport || { importedSceneRows: [] };
                            return {
                                status: 'completed',
                                startedAt,
                                durationMs: Date.now() - startedAt,
                                phaseTimings: null,
                                warning: '',
                                error: '',
                                runtimeMeta: null,
                                importReport: {
                                    ...prevImport,
                                    sceneSubjectPostImportReport: { checkedSceneCount: 0, missingSceneCount: 0, missingItemCount: (sceneImportReport?.createdSubjectItems?.length || 0) + (sceneImportReport?.skippedSubjectItems?.length || 0), missingSceneReports: [], supplementReport: { createdItems: sceneImportReport?.createdSubjectItems || [], skippedItems: sceneImportReport?.skippedSubjectItems || [], failedItems: [], countsByType: { character: 0, prop: 0, environment: 0 } }, importedSubjectCounts: sceneImportReport?.importedSubjectCounts || { character: 0, prop: 0, environment: 0 } },
                                    dbRunInsertedCounts: sceneImportReport?.dbRunInsertedCounts,
                                    dbPersistedCounts: sceneImportReport?.dbPersistedCounts,
                                    importedSubjectCounts: prevImport.importedSubjectCounts ? {
                                        character: (prevImport.importedSubjectCounts.character || 0) + (sceneImportReport?.importedSubjectCounts?.character || 0),
                                        prop: (prevImport.importedSubjectCounts.prop || 0) + (sceneImportReport?.importedSubjectCounts?.prop || 0),
                                        environment: (prevImport.importedSubjectCounts.environment || 0) + (sceneImportReport?.importedSubjectCounts?.environment || 0),
                                    } : sceneImportReport?.importedSubjectCounts,
                                }
                            };
                        });
                        
                        const createdCount = sceneImportReport?.createdSubjectItems?.length || 0;
                        const skippedCount = sceneImportReport?.skippedSubjectItems?.length || 0;
                        setAnalysisFlowStatus({
                            phase: 'completed',
                            message: t(`🎉 恢复成功！系统回溯了进度，顺利为您生成了 ${createdCount} 个全新资产（有 ${skippedCount} 个已存在从而跳过）。`, `Recovery successful. Generated ${createdCount} new assets (skipped ${skippedCount}).`)
                        });
                    }
                } else {
                    setAnalysisFlowStatus({ phase: 'warning', message: t('恢复第三阶段资产设计失败：未返回有效内容', 'Failed to resume Stage 3 asset design: returned no content') });
                }
                clearAnalysisTaskMarker(activeEpisode.id);
            } catch (e) {
                console.error("Stage 3 recovery error:", e);
                const friendlyRecoveryError = localizeAnalysisFailureMessage(e?.message || String(e || ''));
                const canceled = isTaskCanceledError(e) || analysisStopRequestedRef.current;
                const retainMarker = shouldRetainAnalysisTaskMarker({
                    canceled,
                    error: e,
                    mounted: scriptEditorMountedRef.current,
                });
                if (scriptEditorMountedRef.current) {
                    if (canceled) {
                        setAnalysisFlowStatus({ phase: 'warning', message: t('分析任务已停止。', 'Analysis task was stopped.') });
                        setAnalysisUiReport((prev) => ({ ...(prev || {}), status: 'warning', error: '', warning: t('分析任务已由用户停止。', 'Analysis task was stopped by user.') }));
                    } else if (retainMarker) {
                        // Background task still alive — restore monitoring only, no failure/retry prompt.
                        keepPhase2Monitoring = true;
                        applyBackgroundTaskMonitoringUi('assets_gen', startedAt, { phaseNum: 2 });
                    } else {
                        setAnalysisFlowStatus({ phase: 'failed', message: t(`恢复第三阶段资产设计任务失败：${friendlyRecoveryError}`, `Failed to resume Stage 3 asset design task: ${friendlyRecoveryError}`) });
                        setAnalysisUiReport(prev => ({ ...prev, status: 'error', error: friendlyRecoveryError }));
                    }
                }
                if (!retainMarker) {
                    clearAnalysisTaskMarker(activeEpisode.id);
                }
            } finally {
                analysisResumeInFlightRef.current = false;
                if (!keepPhase2Monitoring) {
                    setIsRetryingPhase2(false);
                    setActiveAnalysisTaskId('');
                }
            }
            return;
        }

        if (String(marker?.phase || '').trim() === 'scene_beats') {
            setIsAnalyzing(true);
            setActiveAnalysisTaskId(markerTaskIds[markerTaskIds.length - 1] || String(marker?.taskId || '').trim());
            analysisStopRequestedRef.current = false;
            setAnalysisUiReport({
                status: 'running',
                startedAt,
                durationMs: elapsedMs,
                phaseTimings: null,
                importReport: null,
                runtimeMeta: null,
                warning: '',
                error: '',
            });
            setAnalysisFlowStatus({
                phase: 'scene_beats',
                message: t('🔄 发现未完成的场景编排任务，正在继续接收 Stage 2.2 输出...', 'Detected an unfinished scene beats task, resuming Stage 2.2 output...'),
            });
            let keepSceneBeatsMonitoring = false;
            try {
                const result = await awaitAnalyzeSceneWithRecovery(
                    () => waitForAsyncTask(marker.taskId, { interval: 2500, timeout: remainingTimeoutMs }),
                    {
                        startedAt,
                        baselineText: String(activeEpisode?.ai_scene_analysis_scene_markdown || activeEpisode?.ai_scene_analysis_result || '').trim(),
                        resultField: 'ai_scene_analysis_scene_markdown',
                        expectedResultKind: 'scene_beats',
                    }
                );
                const rawText = extractAnalysisTextFromResult(result) || '';
                const stage2_2Check = validateStage2_2BeatsOutput(rawText, 'Stage 2.2 recovery');
                if (!stage2_2Check.ok) {
                    throw new Error(stage2_2Check.reason || 'Stage 2.2 recovery returned invalid scene table.');
                }
                const validatedBeatsText = stage2_2Check.normalizedText;
                const sceneBeatsRuntimeMeta = result?.meta ? extractAnalysisRuntimeMeta(result.meta) : null;
                setAnalysisRuntimeMeta(sceneBeatsRuntimeMeta);
                setLlmRawResultContent(validatedBeatsText);
                setLlmResultContent(validatedBeatsText);
                lastLoadedAnalysisRef.current = validatedBeatsText;

                const stage2_1Text = String(
                    getStageOutputContent('stage2', 'subject_index')
                    || activeEpisode?.ai_scene_analysis_subject_index
                    || ''
                ).trim();
                await persistSceneMarkdownBundle(validatedBeatsText, {
                    source: 'resume-stage2_2-scene-beats',
                    stage1RawText: buildStage1RestartSourceText(),
                    stage2RawText: [stage2_1Text, validatedBeatsText].filter(Boolean).join('\n\n'),
                    stage2_1Text: stage2_1Text || undefined,
                });

                const sceneBeatsImportReport = await runAutoImportAndSwitchToScenes(validatedBeatsText, {
                    switchToScenes: false,
                    importOptions: {
                        autoSupplementSceneSubjects: false,
                        suppressAlerts: true,
                        subjectsJson: null,
                    },
                });

                const recoveryStoryboard = await awaitPendingStoryboardTasks({
                    importReport: sceneBeatsImportReport,
                    ensureResidual: true,
                });
                const recoveryStoryboardStarted = Boolean(recoveryStoryboard?.started);

                setAnalysisUiReport(buildCompletedAnalysisUiReport({
                    status: 'completed',
                    startedAt,
                    durationMs: Date.now() - startedAt,
                    phaseTimings: null,
                    importReport: sceneBeatsImportReport,
                    runtimeMeta: sceneBeatsRuntimeMeta,
                    storyboardAutoStarted: recoveryStoryboardStarted,
                    storyboardTaskProgress: recoveryStoryboard?.progress || EMPTY_STORYBOARD_TASK_PROGRESS,
                    warning: '',
                    error: '',
                }));
                setAnalysisFlowStatus({
                    phase: 'completed',
                    message: t('场景编排任务已恢复并导入完成。', 'Scene beats task resumed and imported.')
                        + buildStoryboardCompletionSuffix(recoveryStoryboard),
                });
                clearAnalysisTaskMarker(activeEpisode.id);
            } catch (e) {
                console.error('Stage 2.2 recovery error:', e);
                const friendlyRecoveryError = localizeAnalysisFailureMessage(e?.message || String(e || ''));
                const canceled = isTaskCanceledError(e) || analysisStopRequestedRef.current;
                const retainMarker = shouldRetainAnalysisTaskMarker({
                    canceled,
                    error: e,
                    mounted: scriptEditorMountedRef.current,
                });
                if (scriptEditorMountedRef.current) {
                    if (canceled) {
                        setAnalysisFlowStatus({ phase: 'warning', message: t('分析任务已停止。', 'Analysis task was stopped.') });
                        setAnalysisUiReport((prev) => ({ ...(prev || {}), status: 'warning', error: '', warning: t('分析任务已由用户停止。', 'Analysis task was stopped by user.') }));
                    } else if (retainMarker) {
                        keepSceneBeatsMonitoring = true;
                        applyBackgroundTaskMonitoringUi('scene_beats', startedAt);
                    } else {
                        setAnalysisFlowStatus({
                            phase: 'failed',
                            message: t(`恢复场景编排任务失败：${friendlyRecoveryError}`, `Failed to resume scene beats task: ${friendlyRecoveryError}`),
                        });
                        setAnalysisUiReport(prev => ({ ...(prev || {}), status: 'error', error: friendlyRecoveryError }));
                    }
                }
                if (!retainMarker) {
                    clearAnalysisTaskMarker(activeEpisode.id);
                }
            } finally {
                analysisResumeInFlightRef.current = false;
                if (!keepSceneBeatsMonitoring) {
                    setIsAnalyzing(false);
                    setActiveAnalysisTaskId('');
                }
            }
            return;
        }

        
        if (remainingTimeoutMs <= 0) {
            clearAnalysisTaskMarker(activeEpisode.id);
            setAnalysisFlowStatus({
                phase: 'warning',
                message: t('检测到过期的分析任务恢复标记，已自动清理。', 'Detected an expired analysis task marker and cleared it automatically.'),
            });
            analysisResumeInFlightRef.current = false;
            return;
        }
        const phaseMarks = {
            submitStartedAt: startedAt,
            analyzeStartedAt: startedAt,
            llmReturnedAt: 0,
            importStartedAt: 0,
            importFinishedAt: 0,
            persistStartedAt: 0,
            persistFinishedAt: 0,
            completedAt: 0,
        };
        let runtimeMeta = null;
        let importReport = null;
        let postImportSceneSubjectReport = null;
        let importWarningMessage = '';

        setIsAnalyzing(true);
        setActiveAnalysisTaskId(markerTaskIds[markerTaskIds.length - 1] || String(marker?.taskId || '').trim());
        analysisStopRequestedRef.current = false;
        setAnalysisFlowStatus({
            phase: 'script_opt',
            message: t('🔄 发现有个没完成的场景任务，接着帮您做完...', 'Detected an in-progress analysis task, reconnecting...'),
        });
        setAnalysisUiReport({
            status: 'running',
            startedAt,
            durationMs: 0,
            phaseTimings: null,
            importReport: null,
            runtimeMeta: null,
            warning: '',
            error: '',
        });

        try {
            const baselineText = String(activeEpisode?.ai_scene_analysis_result || llmRawResultContent || '').trim();
            const result = await awaitAnalyzeSceneWithRecovery(
                () => waitForAsyncTask(marker.taskId, { interval: 2500, timeout: remainingTimeoutMs }),
                { startedAt, baselineText }
            );
            const analyzedText = extractAnalysisTextFromResult(result);
            phaseMarks.llmReturnedAt = Date.now();
            const savedByBackend = !!(result?.meta?.saved_to_episode);
            let rawResultPersistedEarly = false;

            if (true || !savedByBackend) {
                phaseMarks.persistStartedAt = Date.now();
                try {
                    await persistLlmResultContent(analyzedText || '', 'ai_scene_analysis_result', {
                        source: 'resume-analysis-immediate',
                        stage1RawText: analyzedText || '',
                    });
                    rawResultPersistedEarly = true;
                } catch (persistErr) {
                    if (isPromptInjectionRiskError(persistErr)) throw persistErr;
                    onLog?.(`Resume immediate raw LLM output save warning: ${persistErr?.message || persistErr}`, 'warning');
                } finally {
                    phaseMarks.persistFinishedAt = Date.now();
                }
            }

            if (result && result.meta) {
                runtimeMeta = extractAnalysisRuntimeMeta(result.meta);
                setAnalysisRuntimeMeta(runtimeMeta);
            } else {
                runtimeMeta = null;
                setAnalysisRuntimeMeta(null);
            }

            const integrityWarnings = collectAnalysisWarnings(result);
            const displayWarnings = collectAnalysisWarnings(result, { includeLogOnly: false });
            if (displayWarnings.length > 0) {
                showAnalysisWarningStatus(displayWarnings);
            }

            setLlmRawResultContent(analyzedText || '');
            setLlmResultContent(normalizeLlmMarkdownTable(analyzedText || ''));
            lastLoadedAnalysisRef.current = analyzedText || '';

            phaseMarks.importStartedAt = Date.now();
            try {
                importReport = await runAutoImportAndSwitchToScenes(analyzedText || '', { 
                    switchToScenes: false,
                    importOptions: { suppressAlerts: true }
                });
                if (!importReport) {
                    importWarningMessage = t('自动导入未返回结果，请检查导入配置或返回格式。', 'Auto-import returned no result. Check import config or response format.');
                    setAnalysisFlowStatus({ phase: 'warning', message: importWarningMessage });
                    const sceneRegenStarted = await triggerSceneArrangementRegenerationTask(analyzedText || '', {
                        reason: importWarningMessage,
                        source: 'resume-analysis-empty-import',
                    });
                    if (sceneRegenStarted) {
                        importWarningMessage = `${importWarningMessage}；${t('已自动发起单独场景编排任务。', 'Started a separate scene arrangement task automatically.')}`;
                    }
                }
            } catch (importErr) {
                importWarningMessage = t(
                    `自动导入失败：${importErr?.message || importErr}`,
                    `Auto-import failed: ${importErr?.message || importErr}`
                );
                const sceneRegenStarted = await triggerSceneArrangementRegenerationTask(analyzedText || '', {
                    reason: importWarningMessage,
                    source: 'resume-analysis-import-error',
                });
                if (sceneRegenStarted) {
                    importWarningMessage = `${importWarningMessage}；${t('已自动发起单独场景编排任务。', 'Started a separate scene arrangement task automatically.')}`;
                }
                setAnalysisFlowStatus({ phase: 'warning', message: importWarningMessage });
            } finally {
                phaseMarks.importFinishedAt = Date.now();
            }
            maybeAlertIncompleteSubjectsImport(result, analyzedText || '');

            const postImportSceneSubjectReport = await runPostImportSceneSubjectPipeline(importReport, analyzedText);
            const mergedResumeScenePostReport = syncScenePostImportCheckedCount(importReport, postImportSceneSubjectReport);
            if (importReport && typeof importReport === 'object') {
                importReport = {
                    ...importReport,
                    sceneSubjectPostImportReport: mergedResumeScenePostReport,
                };
                if (mergedResumeScenePostReport?.dbRunInsertedCounts) {
                    importReport.dbRunInsertedCounts = mergedResumeScenePostReport.dbRunInsertedCounts;
                }
                if (mergedResumeScenePostReport?.dbPersistedCounts) {
                    importReport.dbPersistedCounts = mergedResumeScenePostReport.dbPersistedCounts;
                }
            }

            try {
                if (true || !savedByBackend && !rawResultPersistedEarly) {
                    phaseMarks.persistStartedAt = Date.now();
                    await persistLlmResultContent(analyzedText || '', 'ai_scene_analysis_result', {
                        source: 'resume-analysis',
                        stage1RawText: analyzedText || '',
                    });
                } else {
                    if (savedByBackend) {
                        phaseMarks.persistStartedAt = phaseMarks.persistStartedAt || Date.now();
                    }
                    // await refreshAnalysisFromDB(); // TEMPORARY DISABLE
                }
            } finally {
                phaseMarks.persistFinishedAt = Date.now();
            }

            let resumeReviewIssues = [];
            try {
                const firstPassReport = buildSubjectConsistencyReport(analyzedText || '');
                setSubjectConsistencyReport(firstPassReport);
                const { reviewIssues } = await publishAnalysisReviewFindings({
                    subjectReport: firstPassReport,
                });
                resumeReviewIssues = reviewIssues;
            } catch (_) {
                // non-blocking
            }

            if (analysisRunInFlightRef.current || analysisStopRequestedRef.current) {
                if (onLog) onLog('Resume was superseded by a new analysis run, stopping UI update.', 'warning');
                return;
            }

            const storyboardWaitResult = await awaitPendingStoryboardTasks({
                importReport,
                ensureResidual: true,
            });
            const storyboardGate = await ensureStoryboardStartedBeforeAnalysisComplete(storyboardWaitResult);
            if (!storyboardGate.allowComplete) {
                saveAnalysisTaskMarker(activeEpisode.id, {
                    taskId: String(loadAnalysisTaskMarker(activeEpisode.id)?.taskId || `storyboard-${activeEpisode.id}`),
                    startedAt,
                    phase: 'storyboard',
                });
            } else {
            const aiShotsBatchStarted = Boolean(storyboardGate.waitResult?.started);
            const storyboardProgressSnapshot = storyboardGate.waitResult?.progress || EMPTY_STORYBOARD_TASK_PROGRESS;

            phaseMarks.completedAt = Date.now();
            const phaseTimings = computeAnalysisPhaseTimings(phaseMarks);
            setAnalysisUiReport(buildCompletedAnalysisUiReport({
                status: 'completed',
                startedAt,
                durationMs: Date.now() - startedAt,
                phaseTimings,
                importReport,
                runtimeMeta,
                storyboardAutoStarted: aiShotsBatchStarted,
                storyboardTaskProgress: storyboardProgressSnapshot,
                warning: [importWarningMessage, resumeReviewIssues.length > 0 ? buildAnalysisReviewWarningMessage(resumeReviewIssues) : '']
                    .map((item) => String(item || '').trim())
                    .filter(Boolean)
                    .join('\n\n'),
                reviewIssues: resumeReviewIssues,
                error: '',
            }));

            const postImportMissingItems = Number(postImportSceneSubjectReport?.missingItemCount || 0);
            const postImportSupplementCreated = Number(postImportSceneSubjectReport?.supplementReport?.createdItems?.length || 0);
            const postImportSupplementFailed = Number(postImportSceneSubjectReport?.supplementReport?.failedItems?.length || 0);
            const postImportSupplementSkipped = Number(postImportSceneSubjectReport?.supplementReport?.skippedItems?.length || 0);
            const storyboardSuffix = buildStoryboardCompletionSuffix(storyboardGate.waitResult);

            setAnalysisFlowStatus({
                phase: 'completed',
                message: (postImportMissingItems > 0
                    ? (
                        postImportSupplementFailed > 0
                            ? t(`🎉 解析大功告成！我们在剧本中识别出 ${postImportMissingItems} 个核心元素，并为您自动化构建了 ${postImportSupplementCreated} 个专属资产（跳过 ${postImportSupplementSkipped} 个已存资产，遇到 ${postImportSupplementFailed} 个构建异常）。`, `Analysis complete! Auto-generated ${postImportSupplementCreated} new assets based on your story (${postImportSupplementSkipped} skipped, ${postImportSupplementFailed} failed).`)
                            : t(`🎉 解析大功告成！我们在剧本中识别出 ${postImportMissingItems} 个核心元素，并为您自动化构建了 ${postImportSupplementCreated} 个专属资产（跳过 ${postImportSupplementSkipped} 个已存资产）。`, `Analysis complete! Auto-generated ${postImportSupplementCreated} new assets based on your story (${postImportSupplementSkipped} skipped).`)
                    )
                    : t('✅ 分析管线已完成！该场景暂未发现需要新补充的主体资产。', 'Analysis pipeline completed. No missing entities to construct.')) + storyboardSuffix,
            });

            clearAnalysisTaskMarker(activeEpisode.id);
            }
        } catch (e) {
            const canceled = isTaskCanceledError(e) || analysisStopRequestedRef.current;
            phaseMarks.completedAt = Date.now();
            const phaseTimings = computeAnalysisPhaseTimings(phaseMarks);
            const retainMarker = shouldRetainAnalysisTaskMarker({
                canceled,
                error: e,
                mounted: scriptEditorMountedRef.current,
            });
            if (scriptEditorMountedRef.current) {
                if (canceled) {
                    setAnalysisFlowStatus({ phase: 'warning', message: t('分析任务已停止。', 'Analysis task was stopped.') });
                    setAnalysisUiReport({
                        status: 'warning',
                        startedAt,
                        durationMs: Date.now() - startedAt,
                        phaseTimings,
                        importReport,
                        runtimeMeta,
                        warning: t('分析任务已由用户停止。', 'Analysis task was stopped by user.'),
                        error: '',
                    });
                } else if (retainMarker) {
                    // Keep UI monitoring only — no failure/retry prompt while backend task lives.
                    applyBackgroundTaskMonitoringUi(
                        String(marker?.phase || '').trim() === 'scene_beats' ? 'scene_beats' : 'script_opt',
                        startedAt,
                    );
                } else {
                    setAnalysisFlowStatus({
                        phase: 'failed',
                        message: t(`恢复分析任务失败：${e?.message || e}`, `Failed to resume analysis task: ${e?.message || e}`),
                    });
                    setAnalysisUiReport({
                        status: 'failed',
                        startedAt,
                        durationMs: Date.now() - startedAt,
                        phaseTimings,
                        importReport,
                        runtimeMeta,
                        warning: '',
                        error: e?.message || String(e || ''),
                    });
                }
            }
            if (!retainMarker) {
                clearAnalysisTaskMarker(activeEpisode.id);
            }
        } finally {
            analysisResumeInFlightRef.current = false;
            const markerStillLive = Boolean(loadAnalysisTaskMarker(activeEpisode?.id)?.taskId);
            const userStopped = isEpisodeAnalysisUserStopRequested(activeEpisode?.id, {
                localStopRequested: analysisStopRequestedRef.current,
                localStopReason: analysisStopReasonRef.current,
            });
            if (userStopped) {
                analysisAwaitingStoryboardRef.current = false;
                latestIsAnalyzingRef.current = false;
                setIsAnalyzing(false);
                setIsRetryingPhase2(false);
                setActiveAnalysisTaskId('');
            } else if (analysisAwaitingStoryboardRef.current) {
                setIsAnalyzing(true);
            } else if (!analysisRunInFlightRef.current && scriptEditorMountedRef.current && !markerStillLive) {
                setIsAnalyzing(false);
                setActiveAnalysisTaskId('');
                analysisStopRequestedRef.current = false;
            }
        }
    }, [
        activeEpisode?.id,
        ANALYSIS_TASK_MAX_AGE_MS,
        applyBackgroundTaskMonitoringUi,
        beginAnalysisTimer,
        buildSubjectConsistencyReport,
        clearAnalysisTaskMarker,
        clearStalePhase2AssetMarkerIfDesignExists,
        collectAnalysisWarnings,
        computeAnalysisPhaseTimings,
        extractAnalysisRuntimeMeta,
        isTaskCanceledError,
        shouldRetainAnalysisTaskMarker,
        normalizeLlmMarkdownTable,
        persistLlmResultContent,
        persistSceneMarkdownBundle,
        refreshAnalysisFromDB,
        runAutoImportAndSwitchToScenes,
        showAnalysisWarningStatus,
        t,
        doImportText,
        setLlmAssetRawResultContent,
        setIsRetryingPhase2,
        isRetryingPhase2,
        projectId,
        onLog,
        awaitPendingStoryboardTasks,
        buildStoryboardCompletionSuffix,
        ensureStoryboardStartedBeforeAnalysisComplete,
        loadAnalysisTaskMarker,
        saveAnalysisTaskMarker,
    ]);

    useEffect(() => {
        latestIsAnalyzingRef.current = Boolean(isAnalyzing);
        latestActiveEpisodeIdRef.current = activeEpisode?.id || null;
        const episodeId = Number(activeEpisode?.id || 0);
        if (!episodeId || applyingRemoteProgressRef.current) return;
        // Remount starts with isAnalyzing=false. Do not overwrite the surviving
        // live snapshot until restore/bootstrap has hydrated this instance.
        if (!analysisProgressHydratedRef.current) return;
        publishEpisodeAnalysisProgress(episodeId, { isAnalyzing: Boolean(isAnalyzing) });
    }, [isAnalyzing, activeEpisode?.id]);

    const resetBootstrapAnalysisUiIfIdle = useCallback(() => {
        const episodeId = activeEpisode?.id;
        if (!episodeId) return;
        if (analysisEntryLockRef.current || isEpisodeAnalysisClaimed(episodeId)) return;
        const marker = loadAnalysisTaskMarker(episodeId);
        const stillLive = isEpisodeAnalysisTaskLive(episodeId, {
            loadAnalysisTaskMarker,
            analysisResumeInFlight: analysisResumeInFlightRef.current,
            analysisRunInFlight: analysisRunInFlightRef.current,
            phase2GenerationInFlight: phase2GenerationInFlightRef.current,
            analysisEntryLock: analysisEntryLockRef.current,
        });
        if (marker?.taskId || stillLive) return;

        // Keep restored progress logs for review; only tear down a bootstrap "running" shell.
        const ui = latestAnalysisProgressUiRef.current || {};
        const phase = String(ui?.flowStatus?.phase || '').trim().toLowerCase();
        const reportStatus = String(ui?.uiReport?.status || '').trim().toLowerCase();
        const history = Array.isArray(ui?.flowHistory) ? ui.flowHistory : [];
        if (['completed', 'warning', 'failed'].includes(phase)) return;
        if (['completed', 'warning', 'failed', 'error'].includes(reportStatus)) return;
        if (history.length > 0 && reportStatus !== 'running') return;
        if (reportStatus !== 'running' && (!phase || phase === 'idle')) return;

        clearAnalysisProgressUiState(episodeId);
    }, [activeEpisode?.id, clearAnalysisProgressUiState, loadAnalysisTaskMarker]);

    const reattachToExistingAnalysisRun = useCallback(async (entry) => {
        if (!activeEpisode?.id || !entry?.promise || analysisResumeInFlightRef.current) return false;
        if (isEpisodeAnalysisUserStopRequested(activeEpisode.id, {
            localStopRequested: analysisStopRequestedRef.current,
            localStopReason: analysisStopReasonRef.current,
        })) {
            return false;
        }
        analysisResumeInFlightRef.current = true;

        const startedAt = Number(entry.startedAt || Date.now());
        const elapsedMs = Math.max(0, Date.now() - startedAt);
        beginAnalysisTimer(startedAt);
        setIsAnalyzing(true);
        if (entry.taskId) {
            setActiveAnalysisTaskId(String(entry.taskId));
        }
        const resolvedPhase = entry.phase === 2 ? 'assets_gen' : (entry.phase === 'scene_beats' ? 'scene_beats' : 'script_opt');
        // Sync module control plane (survives leave/return) into this instance's refs.
        const control = getEpisodeAnalysisPipelineControl(activeEpisode.id);
        if (control?.stopRequested) {
            analysisStopRequestedRef.current = true;
            analysisStopReasonRef.current = String(control.stopReason || 'user');
        }
        if (Number(control?.deadlineAt || 0) > 0) {
            analysisPipelineDeadlineRef.current = Number(control.deadlineAt);
            analysisPipelineSupervisorActiveRef.current = Boolean(control.supervisorActive);
        }
        setAnalysisFlowStatus((prev) => {
            const prevPhase = String(prev?.phase || '').trim().toLowerCase();
            if (prevPhase && prevPhase !== 'idle') return prev;
            return {
                phase: resolvedPhase,
                message: t(
                    '已回到剧本页，正在恢复后台分析进度…',
                    'Back on the script page; restoring background analysis progress...'
                ),
            };
        });
        setAnalysisUiReport((prev) => {
            if (prev?.status === 'running') {
                return { ...prev, durationMs: elapsedMs };
            }
            return {
                status: 'running',
                startedAt,
                durationMs: elapsedMs,
                phaseTimings: null,
                importReport: null,
                runtimeMeta: null,
                warning: '',
                error: '',
            };
        });

        try {
            await entry.promise;
            await refreshAnalysisFromDB();
            await refreshAnalysisFromDB({ resultField: 'ai_entity_design_result' });
            const marker = loadAnalysisTaskMarker(activeEpisode.id);
            if (!marker?.taskId) {
                setAnalysisFlowStatus((prev) => {
                    const phase = String(prev?.phase || '').trim().toLowerCase();
                    if (['completed', 'warning', 'failed'].includes(phase)) return prev;
                    return {
                        phase: 'completed',
                        message: t('分析已成功完成。', 'Analysis completed successfully.'),
                    };
                });
                setAnalysisUiReport((prev) => {
                    const prevStatus = String(prev?.status || '').trim().toLowerCase();
                    if (['failed', 'error', 'warning'].includes(prevStatus)) {
                        return {
                            ...(prev || {}),
                            startedAt,
                            durationMs: Date.now() - startedAt,
                        };
                    }
                    return {
                        ...(prev || {}),
                        status: 'completed',
                        startedAt,
                        durationMs: Date.now() - startedAt,
                        error: '',
                    };
                });
            }
        } catch (e) {
            const canceled = isTaskCanceledError(e) || analysisStopRequestedRef.current;
            const retainMarker = shouldRetainAnalysisTaskMarker({
                canceled,
                error: e,
                mounted: true,
            });
            const friendlyError = localizeAnalysisFailureMessage(e?.message || String(e || ''));
            if (canceled) {
                setAnalysisFlowStatus({ phase: 'warning', message: t('分析任务已停止。', 'Analysis task was stopped.') });
            } else if (retainMarker) {
                applyBackgroundTaskMonitoringUi(
                    entry.phase === 2 ? 'assets_gen' : (entry.phase === 'scene_beats' ? 'scene_beats' : 'script_opt'),
                    startedAt,
                    { phaseNum: entry.phase === 2 ? 2 : undefined },
                );
            } else {
                setAnalysisFlowStatus({
                    phase: 'failed',
                    message: t(`分析失败：${friendlyError}`, `Analysis failed: ${friendlyError}`),
                });
                setAnalysisUiReport((prev) => ({
                    ...(prev || {}),
                    status: 'failed',
                    error: friendlyError,
                }));
            }
        } finally {
            analysisResumeInFlightRef.current = false;
            const stillHasRun = Boolean(getEpisodeAnalysisRun(activeEpisode.id)?.promise);
            const markerStillLive = Boolean(loadAnalysisTaskMarker(activeEpisode.id)?.taskId);
            if (!stillHasRun && !markerStillLive) {
                setIsAnalyzing(false);
                setActiveAnalysisTaskId('');
            }
        }
        return true;
    }, [
        activeEpisode?.id,
        applyBackgroundTaskMonitoringUi,
        beginAnalysisTimer,
        isTaskCanceledError,
        loadAnalysisTaskMarker,
        localizeAnalysisFailureMessage,
        refreshAnalysisFromDB,
        shouldRetainAnalysisTaskMarker,
        t,
    ]);

    const tryResumePendingAnalysis = useCallback(async () => {
        if (!activeEpisode?.id) return;
        const episodeId = activeEpisode.id;
        if (analysisResumeCoordinatorRef.current.running && analysisResumeCoordinatorRef.current.episodeId === episodeId) return;
        if (analysisResumeInFlightRef.current || phase2GenerationInFlightRef.current || isRetryingPhase2) return;
        if (analysisRunInFlightRef.current || sceneBeatsOnlyRerunInFlightRef.current) return;
        if (analysisFallbackRetryRef.current.running) return;
        if (isEpisodeAnalysisUserStopRequested(episodeId, {
            localStopRequested: analysisStopRequestedRef.current,
            localStopReason: analysisStopReasonRef.current,
        })) return;

        const pendingMarker = loadAnalysisTaskMarker(episodeId);
        const activeRun = getEpisodeAnalysisRun(episodeId);
        const hasPendingWork = Boolean(pendingMarker?.taskId || activeRun?.promise);
        if (!hasPendingWork) {
            // Stale isAnalyzing with no live marker/run (often after storyboard settles on phase=storyboard).
            // Never clear while a click claim / entry lock is held (prep before LLM task id exists).
            if (
                (isAnalyzing || isRetryingPhase2)
                && !analysisRunInFlightRef.current
                && !analysisResumeInFlightRef.current
                && !phase2GenerationInFlightRef.current
                && !analysisEntryLockRef.current
                && !isEpisodeAnalysisClaimed(episodeId)
            ) {
                const ui = latestAnalysisProgressUiRef.current || {};
                const phase = String(ui?.flowStatus?.phase || '').trim().toLowerCase();
                const reportStatus = String(ui?.uiReport?.status || '').trim().toLowerCase();
                const storyboardSettled = isStoryboardTaskProgressSettled(ui?.uiReport?.storyboardTaskProgress);
                if (
                    ['completed', 'warning', 'failed'].includes(phase)
                    || ['completed', 'warning', 'failed', 'error'].includes(reportStatus)
                    || (phase === 'storyboard' && storyboardSettled)
                ) {
                    latestIsAnalyzingRef.current = false;
                    setIsAnalyzing(false);
                    setIsRetryingPhase2(false);
                    setActiveAnalysisTaskId('');
                    if (phase === 'storyboard' && storyboardSettled) {
                        const storyboardOutcome = resolveSettledStoryboardUiOutcome(
                            ui?.uiReport?.storyboardTaskProgress
                        );
                        setAnalysisFlowStatus({
                            phase: storyboardOutcome.phase,
                            message: String(ui?.flowStatus?.message || '').trim()
                                || t('分镜生成已结束', 'Storyboard generation finished'),
                            highlightHint: ui?.flowStatus?.highlightHint || '',
                        });
                        setAnalysisUiReport((prev) => {
                            if (!prev || typeof prev !== 'object') return prev;
                            if (String(prev.status || '').trim().toLowerCase() === 'failed') return prev;
                            const startedAt = Number(prev.startedAt || analysisTimerStartedAtRef.current || 0);
                            return {
                                ...prev,
                                status: storyboardOutcome.status,
                                durationMs: startedAt > 0
                                    ? Math.max(0, Date.now() - startedAt)
                                    : Number(prev.durationMs || 0) || 0,
                                error: '',
                            };
                        });
                    }
                    return;
                }
                resetBootstrapAnalysisUiIfIdle();
            }
            return;
        }

        analysisResumeCoordinatorRef.current = { running: true, episodeId };
        try {
            await clearStaleAnalysisMarkerIfEpisodeComplete(episodeId, activeEpisode, 'resume-precheck');
            clearStalePhase2AssetMarkerIfDesignExists(episodeId, 'resume-precheck');

            let refreshedRun = getEpisodeAnalysisRun(episodeId);
            if (refreshedRun?.promise) {
                // Registry promise is the source of truth across remount. Never drop it just
                // because this ScriptEditor instance's in-flight refs are cold.
                if (analysisRunInFlightRef.current) {
                    bootstrapPendingAnalysisUi();
                    return;
                }
                clearEpisodeAnalysisDetached(episodeId);
                detachedAnalysisRunEpisodeRef.current = null;
                await reattachToExistingAnalysisRun(refreshedRun);
                return;
            }

            const marker = loadAnalysisTaskMarker(episodeId);
            if (!marker?.taskId) {
                resetBootstrapAnalysisUiIfIdle();
                return;
            }
            if (Number(marker?.phase) === 2 && clearStalePhase2AssetMarkerIfDesignExists(episodeId, 'pending-resume-guard')) {
                resetBootstrapAnalysisUiIfIdle();
                return;
            }

            const terminalInfo = await peekAsyncTaskTerminalInfo(marker.taskId);
            if (terminalInfo?.status) {
                const terminalStatus = String(terminalInfo.status || '').trim().toLowerCase();
                const markerPhase = normalizeAnalysisTaskMarkerPhase(marker?.phase);
                const markerPhaseKey = String(markerPhase ?? '1').trim().toLowerCase();
                const isSuccessTerminal = SUCCESS_ASYNC_TASK_STATUSES.has(terminalStatus);

                // Re-check after await: Stage 1/2.x node completion is normal mid-pipeline.
                // Never treat a single completed node task as whole-pipeline success while a run is live.
                const liveRun = getEpisodeAnalysisRun(episodeId);
                const pipelineStillLive = Boolean(
                    liveRun?.promise
                    || analysisRunInFlightRef.current
                    || analysisEntryLockRef.current
                    || isEpisodeAnalysisClaimed(episodeId)
                );
                if (pipelineStillLive) {
                    if (isSuccessTerminal && (markerPhaseKey === '1' || markerPhase === 1)) {
                        // Drop the completed Stage 1 task id so resume cannot false-complete later;
                        // Stage 2.1+ will write a fresh marker via onTaskCreated.
                        clearAnalysisTaskMarker(episodeId);
                        onLog?.(
                            `[Analysis Resume] Stage 1 backend task already ${terminalStatus}; cleared node marker while multi-stage pipeline continues.`,
                            'info'
                        );
                    } else {
                        bootstrapPendingAnalysisUi();
                    }
                    if (liveRun?.promise && !analysisRunInFlightRef.current) {
                        clearEpisodeAnalysisDetached(episodeId);
                        detachedAnalysisRunEpisodeRef.current = null;
                        await reattachToExistingAnalysisRun(liveRun);
                    }
                    return;
                }

                // Pipeline is not live. Success of an intermediate node ≠ episode analysis complete.
                if (isSuccessTerminal) {
                    const hasSubjectIndex = Boolean(String(activeEpisode?.ai_scene_analysis_subject_index || '').trim());
                    const hasSceneMarkdownByScene = (() => {
                        try {
                            const stageOutputs = JSON.parse(String(activeEpisode?.ai_stage_outputs || '').trim() || '{}');
                            const raw = String(stageOutputs?.stages?.stage2?.outputs?.scene_markdown_by_scene?.content || '').trim();
                            if (!raw) return false;
                            const parsed = JSON.parse(raw);
                            return parsed && typeof parsed === 'object'
                                && Object.values(parsed).some((entry) => String(entry?.markdown || '').trim());
                        } catch (_) {
                            return false;
                        }
                    })();
                    const hasSceneMarkdown = Boolean(
                        hasSceneMarkdownByScene || String(activeEpisode?.ai_scene_analysis_scene_markdown || '').trim()
                    );
                    const hasAdaptation = Boolean(String(
                        activeEpisode?.ai_scene_analysis_adaptation
                        || activeEpisode?.ai_scene_analysis_result
                        || ''
                    ).trim());
                    const hasEntityDesign = hasPersistedEntityDesignPayload(activeEpisode?.ai_entity_design_result);
                    const scenes = await fetchScenes(episodeId).catch(() => []);
                    const sceneCount = Array.isArray(scenes) ? scenes.length : 0;
                    const episodeArtifactsComplete = Boolean(
                        hasSubjectIndex && hasSceneMarkdown && hasEntityDesign && sceneCount > 0
                    );

                    if (!episodeArtifactsComplete) {
                        clearAnalysisTaskMarker(episodeId);
                        detachedAnalysisRunEpisodeRef.current = null;
                        // Incomplete leftover artifacts must not look like a finished pipeline.
                        const continueFn = resumeIncompleteAnalysisPipelineRef.current;
                        const fromStage1 = markerPhaseKey === '1' || markerPhase === 1;
                        const extractionAlreadyDone = Boolean(
                            String(latestStage2_1TextRef.current || '').trim()
                            || Number(markerPhase) === 2
                            || ['2', 'extract_assets', 'scene_beats', 'assets_gen'].includes(markerPhaseKey)
                        );
                        // Reuse a Subject Index that this run (or a later phase) already produced.
                        // Only force a fresh Stage 2.1 when Stage 1 just finished and no index exists yet.
                        const canSkipToExistingIndex = Boolean(hasSubjectIndex && (!fromStage1 || extractionAlreadyDone));
                        if (typeof continueFn === 'function' && (canSkipToExistingIndex || hasAdaptation)) {
                            setAnalysisFlowStatus({
                                phase: canSkipToExistingIndex ? 'scene_beats' : 'parallel_prepare',
                                message: t(
                                    '检测到上一阶段已完成但后续未跑完，正在自动继续分析…',
                                    'Previous stage finished but later stages did not; auto-continuing analysis...'
                                ),
                            });
                            try {
                                await continueFn({
                                    reason: `stale-terminal-${terminalStatus}`,
                                    markerPhase: markerPhaseKey,
                                    hasSubjectIndex: canSkipToExistingIndex,
                                    hasAdaptation,
                                    continueFromStage1: fromStage1,
                                });
                            } catch (continueErr) {
                                setIsAnalyzing(false);
                                setIsRetryingPhase2(false);
                                setActiveAnalysisTaskId('');
                                analysisRunInFlightRef.current = false;
                                setAnalysisFlowStatus({
                                    phase: 'warning',
                                    message: t(
                                        `自动继续分析失败：${continueErr?.message || continueErr}。请手动点击继续分析。`,
                                        `Auto-continue failed: ${continueErr?.message || continueErr}. Please resume analysis manually.`
                                    ),
                                });
                                onLog?.(
                                    `[Analysis Resume] Auto-continue after incomplete terminal task failed: ${continueErr?.message || continueErr}`,
                                    'error'
                                );
                            }
                            return;
                        }
                        setIsAnalyzing(false);
                        setIsRetryingPhase2(false);
                        setActiveAnalysisTaskId('');
                        setAnalysisFlowStatus({
                            phase: 'warning',
                            message: t(
                                '上一阶段后台任务已结束，但分析流水线尚未完成。请点击继续分析以接着跑后续阶段。',
                                'A prior backend task ended, but the analysis pipeline is incomplete. Click resume analysis to continue.'
                            ),
                        });
                        setAnalysisUiReport((prev) => ({
                            ...(prev || {}),
                            status: 'warning',
                            warning: t(
                                '分析未完整完成（仅部分阶段结束）。',
                                'Analysis is incomplete (only some stages finished).'
                            ),
                            error: '',
                        }));
                        return;
                    }
                }

                const localizedError = terminalInfo.error
                    ? localizeAnalysisFailureMessage(terminalInfo.error)
                    : '';
                const terminalUi = resolveAsyncTaskTerminalUi(
                    { ...terminalInfo, error: localizedError || terminalInfo.error },
                    t
                );
                clearAnalysisTaskMarker(episodeId);
                releaseEpisodeAnalysisRun(episodeId);
                detachedAnalysisRunEpisodeRef.current = null;
                setIsAnalyzing(false);
                setIsRetryingPhase2(false);
                setActiveAnalysisTaskId('');
                // Soft-stop monitoring — keep restored progress logs, but surface success vs failure.
                setAnalysisFlowStatus((prev) => {
                    const phase = String(prev?.phase || '').trim().toLowerCase();
                    // Prefer a more severe outcome if UI already has a terminal phase.
                    const severity = { completed: 1, warning: 2, failed: 3 };
                    if (
                        ['completed', 'warning', 'failed'].includes(phase)
                        && (severity[terminalUi.phase] || 0) <= (severity[phase] || 0)
                    ) {
                        return {
                            ...prev,
                            message: String(prev?.message || '').trim() || terminalUi.message,
                        };
                    }
                    return {
                        phase: terminalUi.phase,
                        message: terminalUi.message,
                    };
                });
                setAnalysisUiReport((prev) => {
                    const prevStatus = String(prev?.status || '').trim().toLowerCase();
                    const startedAt = Number(prev?.startedAt || Date.now());
                    const durationMs = Math.max(
                        0,
                        Date.now() - (Number.isFinite(startedAt) && startedAt > 0 ? startedAt : Date.now())
                    );
                    if (!prev) {
                        return {
                            status: terminalUi.status,
                            error: terminalUi.error,
                            warning: terminalUi.warning,
                            durationMs,
                        };
                    }
                    // Keep an already-failed report; upgrade running/completed when terminal is worse.
                    if (prevStatus === 'failed' && terminalUi.status !== 'failed') {
                        return { ...prev, durationMs: Number(prev.durationMs || 0) || durationMs };
                    }
                    if (prevStatus === 'warning' && terminalUi.status === 'completed') {
                        return { ...prev, durationMs: Number(prev.durationMs || 0) || durationMs };
                    }
                    return {
                        ...prev,
                        status: terminalUi.status,
                        error: terminalUi.error,
                        warning: terminalUi.warning,
                        durationMs: Number(prev.durationMs || 0) || durationMs,
                    };
                });
                if (onLog) {
                    const reason = terminalStatus === 'not_found'
                        ? 'backend task no longer exists (server may have restarted)'
                        : `backend task already ${terminalStatus}`;
                    const logLevel = terminalUi.phase === 'failed'
                        ? 'error'
                        : (terminalUi.phase === 'warning' ? 'warning' : 'info');
                    onLog?.(`[Analysis Resume] Cleared stale marker; ${reason}. Outcome=${terminalUi.phase}.`, logLevel);
                }
                return;
            }

            if (isAsyncTaskPollInFlight(marker.taskId)) {
                bootstrapPendingAnalysisUi();
                return;
            }

            bootstrapPendingAnalysisUi();
            await resumeAnalysisFromTaskMarker(marker);
        } finally {
            analysisResumeCoordinatorRef.current = { running: false, episodeId: null };
        }
    }, [
        activeEpisode,
        activeEpisode?.id,
        activeEpisode?.ai_entity_design_result,
        activeEpisode?.ai_scene_analysis_adaptation,
        activeEpisode?.ai_scene_analysis_result,
        activeEpisode?.ai_scene_analysis_scene_markdown,
        activeEpisode?.ai_scene_analysis_subject_index,
        bootstrapPendingAnalysisUi,
        clearAnalysisTaskMarker,
        clearStaleAnalysisMarkerIfEpisodeComplete,
        clearStalePhase2AssetMarkerIfDesignExists,
        fetchScenes,
        isAnalyzing,
        isRetryingPhase2,
        loadAnalysisTaskMarker,
        localizeAnalysisFailureMessage,
        normalizeAnalysisTaskMarkerPhase,
        onLog,
        reattachToExistingAnalysisRun,
        resetBootstrapAnalysisUiIfIdle,
        resumeAnalysisFromTaskMarker,
        t,
    ]);

    useEffect(() => {
        const episodeId = Number(activeEpisode?.id || 0);
        if (!episodeId) return;

        scriptEditorMountedRef.current = true;
        latestActiveEpisodeIdRef.current = episodeId;
        mountResumeReadyRef.current = false;
        analysisProgressHydratedRef.current = false;
        restoreAnalysisProgressFromSession(episodeId);
        bootstrapPendingAnalysisUi();
        analysisProgressHydratedRef.current = true;
        // Remount: rehydrate stop/deadline control so this instance matches the background run.
        const pipelineControl = getEpisodeAnalysisPipelineControl(episodeId);
        if (Number(pipelineControl?.deadlineAt || 0) > 0) {
            analysisPipelineDeadlineRef.current = Number(pipelineControl.deadlineAt);
            analysisPipelineSupervisorActiveRef.current = Boolean(pipelineControl.supervisorActive);
        }
        if (pipelineControl?.stopRequested) {
            analysisStopRequestedRef.current = true;
            analysisStopReasonRef.current = String(pipelineControl.stopReason || 'user');
        }
        // Remount during prep/clear must keep the CTA in running state if a module claim is held.
        const remountUserStopped = isEpisodeAnalysisUserStopRequested(episodeId, {
            localStopRequested: analysisStopRequestedRef.current,
            localStopReason: analysisStopReasonRef.current,
        });
        if (!remountUserStopped && (isEpisodeAnalysisClaimed(episodeId) || getEpisodeAnalysisRun(episodeId)?.promise)) {
            setIsAnalyzing(true);
            latestIsAnalyzingRef.current = true;
            if (!String(analysisFlowStatusRef.current?.message || '').trim()
                || String(analysisFlowStatusRef.current?.phase || '').trim().toLowerCase() === 'idle') {
                setAnalysisFlowStatus({
                    phase: String(analysisFlowStatusRef.current?.phase || 'script_opt').trim() || 'script_opt',
                    message: t(
                        '后台分析进行中，正在恢复进度显示…',
                        'Background analysis in progress; restoring progress display...'
                    ),
                });
            }
        }

        const unsubscribeProgress = subscribeEpisodeAnalysisProgress(episodeId, (snapshot) => {
            if (!scriptEditorMountedRef.current) return;
            if (analysisProgressDismissedRef.current) return;
            if (!snapshot || typeof snapshot !== 'object') return;
            // Owner instance already has React state; avoid echo loops while writing.
            // After leave/return the original owner is marked detached, so the new instance hydrates.
            if (analysisRunInFlightRef.current && !isEpisodeAnalysisDetached(episodeId)) return;
            applyLiveAnalysisProgressSnapshot(snapshot);
        });

        let cancelled = false;
        (async () => {
            ensureAnalysisFallbackState(episodeId);
            await clearStaleAnalysisMarkerIfEpisodeComplete(episodeId, activeEpisode, 'mount-precheck');
            if (cancelled) return;
            await tryResumePendingAnalysis();
            if (cancelled) return;
            if (!isEpisodeAnalysisTaskLive(episodeId, {
                loadAnalysisTaskMarker,
                isAnalyzing: latestIsAnalyzingRef.current,
                analysisRunInFlight: analysisRunInFlightRef.current,
                analysisResumeInFlight: analysisResumeInFlightRef.current,
                phase2GenerationInFlight: phase2GenerationInFlightRef.current,
            })) {
                resetBootstrapAnalysisUiIfIdle();
            }
            if (!cancelled) mountResumeReadyRef.current = true;
        })();

        return () => {
            // Keep backend analysis running when this view unmounts (tab/page switch).
            // Explicit cancellation should only happen via the "stop task" action.
            scriptEditorMountedRef.current = false;
            mountResumeReadyRef.current = false;
            cancelled = true;
            unsubscribeProgress();
            const leavingEpisodeId = Number(latestActiveEpisodeIdRef.current || episodeId);
            if (!leavingEpisodeId) return;

            if (getEpisodeAnalysisRun(leavingEpisodeId)?.promise || isEpisodeAnalysisClaimed(leavingEpisodeId)) {
                markEpisodeAnalysisDetached(leavingEpisodeId);
                detachedAnalysisRunEpisodeRef.current = leavingEpisodeId;
                // Flush one last live snapshot so remount hydrates beyond leave-time localStorage.
                publishLiveAnalysisProgressSnapshot({
                    isAnalyzing: Boolean(latestIsAnalyzingRef.current),
                    pipelineNodes: Array.isArray(diagnosticsPipelineNodesRef.current)
                        ? diagnosticsPipelineNodesRef.current
                        : [],
                    sceneUnits: Array.isArray(diagnosticsSceneUnitsRef.current)
                        ? diagnosticsSceneUnitsRef.current
                        : [],
                });
            }
            persistAnalysisSessionSnapshot(leavingEpisodeId);
            const stillRunning = isEpisodeAnalysisTaskLive(leavingEpisodeId, {
                loadAnalysisTaskMarker,
                isAnalyzing: latestIsAnalyzingRef.current,
                analysisRunInFlight: analysisRunInFlightRef.current,
                analysisResumeInFlight: analysisResumeInFlightRef.current,
                phase2GenerationInFlight: phase2GenerationInFlightRef.current,
            });
            if (stillRunning && onLog) {
                const now = Date.now();
                if (now - lastScriptLeaveNoticeAtRef.current > 3000) {
                    lastScriptLeaveNoticeAtRef.current = now;
                    const remainingMs = getEpisodeAnalysisPipelineRemainingMs(leavingEpisodeId);
                    const remainMin = Number.isFinite(remainingMs)
                        ? Math.max(1, Math.ceil(remainingMs / 60000))
                        : null;
                    onLog?.(
                        remainMin
                            ? t(
                                `已暂时离开剧本页：分析仍在后台继续（约剩 ${remainMin} 分钟时限）。返回后会自动恢复进度条与日志；停止请点「停止分析」。`,
                                `Left the script page temporarily: analysis continues in the background (~${remainMin} min left). Progress restores on return; use Stop Analysis to cancel.`
                            )
                            : t(
                                '已暂时离开剧本页：分析仍在后台继续。返回后会自动恢复进度条与日志；停止请点「停止分析」。',
                                'Left the script page temporarily: analysis continues in the background. Progress restores on return; use Stop Analysis to cancel.'
                            ),
                        'info'
                    );
                }
            }
        };
        // Intentionally keyed by episode id only — avoid re-running cleanup when activeEpisode object reference changes during analysis.
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [activeEpisode?.id]);

    useEffect(() => {
        const refreshPendingAnalysis = () => {
            if (!mountResumeReadyRef.current) return;
            if (document.visibilityState !== 'visible') return;
            const now = Date.now();
            if (now - lastTryResumePendingAnalysisAtRef.current < 5000) return;
            lastTryResumePendingAnalysisAtRef.current = now;
            tryResumePendingAnalysis();
        };
        const refreshDiagnosticsOnVisible = () => {
            if (document.visibilityState !== 'visible') return;
            setDiagnosticsRefreshNonce((value) => value + 1);
        };
        document.addEventListener('visibilitychange', refreshPendingAnalysis);
        window.addEventListener('focus', refreshPendingAnalysis);
        document.addEventListener('visibilitychange', refreshDiagnosticsOnVisible);
        window.addEventListener('focus', refreshDiagnosticsOnVisible);
        return () => {
            document.removeEventListener('visibilitychange', refreshPendingAnalysis);
            window.removeEventListener('focus', refreshPendingAnalysis);
            document.removeEventListener('visibilitychange', refreshDiagnosticsOnVisible);
            window.removeEventListener('focus', refreshDiagnosticsOnVisible);
        };
    }, [tryResumePendingAnalysis]);

    const activeEpisodeAnalysisResult = activeEpisode?.ai_scene_analysis_result || '';
    const activeEpisodeSubjectCheckResult = String(activeEpisode?.episode_info?.subject_check_result || '');
    const prevActiveEpisodeAnalysisResultRef = useRef(undefined);
    const prevAnalysisSyncEpisodeIdRef = useRef(null);
    useEffect(() => {
        // On episode change / analysis field update from parent. Do NOT depend on
        // normalizeLlmMarkdownTable — it was recreated every render and stormed GET /episodes/:id.
        const episodeId = activeEpisode?.id ?? null;
        const episodeChanged = prevAnalysisSyncEpisodeIdRef.current !== episodeId;
        if (episodeChanged) {
            prevAnalysisSyncEpisodeIdRef.current = episodeId;
            prevActiveEpisodeAnalysisResultRef.current = undefined;
            lastEpisodeSegmentsScriptKeyRef.current = '';
            lastEpisodeSyncScriptKeyRef.current = '';
            // Do NOT clear lastEpisodeReuseSubjectIdsKeyRef here — restore key already
            // includes episode id; clearing after restore re-applies [] and wipes auto-check.
        }
        const initial = activeEpisodeAnalysisResult;
        const normalizedInitial = normalizeLlmMarkdownTable(initial);
        setLlmRawResultContent((prev) => (prev === initial ? prev : initial));
        setLlmResultContent((prev) => (prev === normalizedInitial ? prev : normalizedInitial));
        setSubjectConsistencyResultText((prev) => (
            prev === activeEpisodeSubjectCheckResult ? prev : activeEpisodeSubjectCheckResult
        ));
        setAnalysisRuntimeMeta((prev) => (prev === null ? prev : null));
        lastLoadedAnalysisRef.current = initial;
        const prevInitial = prevActiveEpisodeAnalysisResultRef.current;
        prevActiveEpisodeAnalysisResultRef.current = initial;
        // Refresh from DB only on first empty mount/episode switch or when analysis was cleared.
        if (!initial && (prevInitial === undefined || Boolean(prevInitial))) {
            refreshAnalysisFromDBRef.current();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps -- normalize helper intentionally omitted
    }, [activeEpisode?.id, activeEpisodeAnalysisResult, activeEpisodeSubjectCheckResult]);

    const handleLlmCellChange = (rowIdx, colIdx, value) => {
        const parsed = parseMarkdownTable(llmMarkdownTableText || llmResultContent);
        if (!parsed) {
            const normalized = normalizeLlmMarkdownTable(value);
            setLlmResultContent(normalized);
            setLlmRawResultContent(prev => mergeEditedSceneTableIntoRaw(prev || llmRawResultContent || '', normalized));
            return;
        }

        const nextRows = parsed.rows.map(r => [...r]);
        if (!nextRows[rowIdx]) return;
        nextRows[rowIdx][colIdx] = value;
        const nextText = normalizeLlmMarkdownTable(buildMarkdownTable(parsed.headers, nextRows));
        setLlmResultContent(nextText);
        setLlmRawResultContent(prev => mergeEditedSceneTableIntoRaw(prev || llmRawResultContent || '', nextText));
    };

    const handlePersistLlmWorkspace = async () => {
        const normalizedTable = normalizeLlmMarkdownTable(llmResultContent || llmMarkdownTableText || '');
        const mergedRaw = mergeEditedSceneTableIntoRaw(llmRawResultContent || '', normalizedTable);
        setLlmRawResultContent(mergedRaw);
        lastLoadedAnalysisRef.current = mergedRaw;
        await persistLlmResultContent(mergedRaw);
    };

    const handleLlmRawContentChange = (value) => {
        const raw = String(value || '');
        llmRawAutoSaveArmedRef.current = true;
        setLlmRawResultContent(raw);
        setLlmResultContent(normalizeLlmMarkdownTable(raw));
    };

    const handleSaveLlmRawContent = async () => {
        const raw = String(llmRawResultContent || '');
        lastLoadedAnalysisRef.current = raw;
        await persistLlmResultContent(raw);
    };

    useEffect(() => {
        if (!activeEpisode?.id) return;
        if (!llmRawAutoSaveArmedRef.current) return;

        if (llmRawAutoSaveTimerRef.current) {
            clearTimeout(llmRawAutoSaveTimerRef.current);
        }

        llmRawAutoSaveTimerRef.current = setTimeout(async () => {
            const raw = String(llmRawResultContent || '');
            lastLoadedAnalysisRef.current = raw;
            await persistLlmResultContent(raw);
        }, 1200);

        return () => {
            if (llmRawAutoSaveTimerRef.current) {
                clearTimeout(llmRawAutoSaveTimerRef.current);
                llmRawAutoSaveTimerRef.current = null;
            }
        };
    }, [llmRawResultContent, activeEpisode?.id]);

    const handleSegmentChange = (idx, field, value) => {
        const newSegments = [...segments];
        newSegments[idx] = { ...newSegments[idx], [field]: value };
        setSegments(newSegments);
    };

    const getCurrentScriptContent = () => {
        let fullContent = rawContent;
        if (!isRawMode && segments.length > 0) {
            const header = `| Paragraph ID | Title | Content (Revised) | Content (Original) | Narrative Function | Analysis & Adaptation Notes |\n|---|---|---|---|---|---|`;
            const rows = segments.map(seg => {
                const clean = (txt) => (txt || '').replace(/\n/g, '<br>').replace(/\|/g, '\\|');
                return `| ${seg.id} | ${clean(seg.title)} | ${clean(seg.content)} | ${clean(seg.original)} | ${clean(seg.narrative_role)} | ${clean(seg.analysis)} |`;
            }).join('\n');
            fullContent = header + '\n' + rows;
        }
        return fullContent;
    };

    const DELETED_SEGMENT_MARKER_REGEX = /^(?:\[|\(|（)\s*(?:已删除|作废|废弃|deleted)\s*(?:\]|\)|）)/i;
    const DELETED_ONLY_LINE_REGEX = /^\s*(?:\[|\(|（)?\s*(?:已删除|作废|废弃|deleted)\s*(?:\]|\)|）)?\s*[:：-]?\s*$/i;

    const isExplicitlyDeletedSegment = (segment) => {
        const title = String(segment?.title || '').trim();
        const content = String(segment?.content || '').trim();
        if (DELETED_SEGMENT_MARKER_REGEX.test(title)) return true;
        if (DELETED_SEGMENT_MARKER_REGEX.test(content)) return true;
        if (DELETED_ONLY_LINE_REGEX.test(content)) return true;
        return false;
    };

    const stripExplicitDeletedLines = (text) => {
        return String(text || '')
            .split('\n')
            .filter((line) => !DELETED_SEGMENT_MARKER_REGEX.test(String(line || '').trim()))
            .join('\n')
            .trim();
    };

    const getAnalysisScriptContent = () => {
        if (!isRawMode && segments.length > 0) {
            const revisedBlocks = segments
                .filter((segment) => !isExplicitlyDeletedSegment(segment))
                .map((segment) => {
                    const title = String(segment?.title || '').trim();
                    const revised = String(segment?.content || '').trim();
                    if (!revised) return '';
                    return title ? `### ${title}\n${revised}` : revised;
                })
                .filter(Boolean);
            if (revisedBlocks.length > 0) {
                return revisedBlocks.join('\n\n').trim();
            }
        }
        return stripExplicitDeletedLines(rawContent || '');
    };

    const handleSave = async () => {
        if (!activeEpisode) return;
        if (onLog) onLog("Saving Script...");

        let fullContent = getCurrentScriptContent();

        // console.log("Saving Content:", fullContent.substring(0, 100) + "...");

        try {
            await onUpdateScript(activeEpisode.id, fullContent);
            if (onLog) onLog(`Script saved. Length: ${fullContent.length}`);
            // If we just saved from Raw Mode, keep it in sync but don't force parse unless user wants to
            // Actually the Effect will trigger on activeEpisode update if we parent updates it? 
            // Usually onUpdateScript updates parent state? If so, useEffect runs. 
            // If raw text saved, it will probably stay in Raw Mode (parsing fails).
            alert("Script saved successfully!");
        } catch (e) {
             console.error(e);
             if (onLog) onLog(`Script Save Failed: ${e.message}`);
             alert(`Failed to save script: ${e.message}`);
        }
    };
    
